INSERT INTO "characterizations" VALUES(3722,4167,'HRTEM','aligned nanorods: d = 0.325 nm, (110) plane of rutile (Fig. 6h = échantillon 4 M d''après la légende de la figure 6)','The distance between the lattice fringes (d = 0.325 nm) in the aligned nanorods can be assigned to the interplanar distance of rutile phase (110) plane','Results and Discussion',13512,13663,NULL,NULL);
