INSERT INTO "characterizations" VALUES(3738,4178,'XRD profile refinement (Le Bail)','0 0 1 preferential crystal orientation of MIL-96 modeled with the March-Dollase function; refined G parameter 0.51; Le Bail refinement of the unit cell (Table S2, Fig. S11)','The powder XRD refinement results (see Table S2 and Fig. S11†) confirm a 0 0 1 preferential crystal orientation','Influence of EtOH/H2O molar ratio',19843,19954,'FullProf software (profile refinement of the XRD data)','pattern matching in the range 5–40°; Pearson VII line shape; zero offset, scale factor, six background terms, profile parameters, preferred orientation (March–Dollase function) and unit cell parameters refined');
INSERT INTO "characterizations" VALUES(3739,4186,'XRD','perovskite structure, cubic system (JCPDS PDF #54-0752), peaks at 15.1°, 21.5°, 30.7°, 38.0° and 44.2° assigned to (100), (110), (200), (211) and (220)','indexed by a cubic crystal system','Results and Discussion',9712,9745,'Bruker D8 Advance diffractometer','Cu K‐alpha radiation, lambda = 1.5418 Å');
INSERT INTO "characterizations" VALUES(3740,4186,'XPS','Pb 4f spectrum with Pb2+ peaks at 142.8 and 138.0 eV and shoulder peaks at 141.2 and 136.4 eV associated with metallic Pb0','two shoulder peaks at 141.2 and 136.4 eV associated with metallic Pb0','Results and Discussion',7222,7291,'PHI 5300 (Physical Electronics)','250 W, 12 kV, Al as the target anode');
INSERT INTO "characterizations" VALUES(3741,4186,'TEM','interplanar distance of the (100) planes of 5.85 Å','from 5.85 Å for pristine CsPbBr3 NCs to 5.80 Å for CsPbBr3:xNd3+ (x = 7.2%) NCs','Results and Discussion',8665,8744,'FEI Tecnai G2 F20 with a charge‐coupled device camera (Quemese, EMSIS GmbH)','accelerating voltage of 200 kV');
INSERT INTO "characterizations" VALUES(3742,4186,'PL','PL peak of pristine CsPbBr3 NCs at 515 nm at room temperature','The intrinsic PL peak of pristine CsPbBr3 NCs sits at 515 nm at room temperature','Results and Discussion',19175,19255,'integrating sphere system with a fiber‐coupled spectrometer (Ocean Optics, QE Pro)','360 nm continuous wave laser');
INSERT INTO "characterizations" VALUES(3743,4186,'PLQY and time-resolved PL','PLQY of about 81% and average lifetime of 14.11 ns for pristine CsPbBr3','the PLQY for pristine CsPbBr3 is already very high (≈81%)','Results and Discussion',21804,21861,'Edinburgh FLS1000','excited at 365 nm');
INSERT INTO "characterizations" VALUES(3744,4186,'thermal cycling (PL)','55% of the initial PL intensity preserved for pristine NCs (Fig. S9)','The controlled heating ramp is 5 °C/min.','Supporting Information — ADVS-7-2001698-s001.pdf',39396,39436,NULL,'controlled heating ramp of 5 °C/min');
INSERT INTO "characterizations" VALUES(3745,4186,'photostability (PL)','about 60% of the relative PL preserved after 8 h under continuous UV irradiation (Fig. S10)','Photo-stability of pristine and doped CsPbBr3 nanocrystals under continuous ultraviolet irradiation (365 nm, 141 mW/cm2).','Supporting Information — ADVS-7-2001698-s001.pdf',39449,39570,NULL,'365 nm, 141 mW/cm2');
INSERT INTO "characterizations" VALUES(3746,4187,'XRD','perovskite structure; diffraction peaks shift to higher angles with increasing Nd3+ (lattice contraction); weak additional peaks at 15° to 20° and 25° to 30° at x > 7.0% attributed to an impurity phase','the additional weak peaks observed in the range of 15° to 20° and 25° to 30° at x > 7.0% are attributed to an impurity phase','Results and Discussion',10587,10711,'Bruker D8 Advance diffractometer','Cu K‐alpha radiation, lambda = 1.5418 Å');
INSERT INTO "characterizations" VALUES(3747,4187,'XPS','Nd 3d peak at 980.2 eV; Pb0 peaks suppressed and Pb2+ 4f peaks shifted to higher binding energy compared with pristine NCs','The additional peak in Nd3+‐doped CsPbBr3 NCs at 980.2 eV can be assigned to the Nd 3d signal, indicating the presence of Nd in the films','Results and Discussion',6853,6990,'PHI 5300 (Physical Electronics)','250 W, 12 kV, Al as the target anode');
