INSERT INTO "characterizations" VALUES(3856,4254,'photoluminescence','PL spectrum recorded for this sample (Fig. 6); comparison with pure ZnO is stated for all RE-doped ZnO together','Fig. 6 PL spectra of P-ZnO, La-ZnO, Dy-ZnO, Sm-ZnO and Nd-ZnO at excitation wavelength of 320 nm.','Figure captions',40356,40453,'Hitachi (F-2500) spectrofluorimeter','excitation wavelength 320 nm at room temperature');
