INSERT INTO "characterizations" VALUES(3902,4345,'TGA-MS (simulation of the calcination of the precursor mixture in air)','weight loss of 4.4 % between 30 and 700 °C (Table 3); H2O and CO2 released','Samples of about 50 mg were subjected to heating at a constant rate of 5 °C min−1 under air flow (100 mL min−1) according to the following procedure','2.2. Characterization Methods',10269,10417,'STA449C thermobalance (NETZSCH, Selb, Germany) coupled with the QMS 403C Aëolos quadrupole mass spectrometer (NETZSCH, Selb, Germany)','samples of about 50 mg, constant heating rate of 5 °C min−1 under air flow (100 mL min−1); heating to 500 °C, isotherm at 500 °C (30 min), heating to 650/700/750/800/850 °C, isotherm (90 min), cooling to 30 °C');
INSERT INTO "characterizations" VALUES(3903,4351,'galvanostatic cycling','initial charge/discharge capacities at 0.05C and rate capability of the cathodes (Tables 6, Figure 7)','Galvanostatic cycling was performed between 3 to 4.4 V vs. Li+/Li and at C-rate between 0.05C to 5C using a BioLogic multi-channel battery cycler (Biologic, Seyssinet-Pariset, France) at room temperature.','2.3. Electrochemical Evaluation',14027,14231,'BioLogic multi-channel battery cycler (Biologic, Seyssinet-Pariset, France)','room temperature; between 3 to 4.4 V vs. Li+/Li; C-rate between 0.05C to 5C');
INSERT INTO "characterizations" VALUES(3904,4352,'TEM','well-dispersed particles, wide size distribution 1–24 nm, average 8.33 nm','the WCDs are well‐dispersed with a wide particle size distribution (1–24 nm), and an average particle size of 8.33 nm (Figure 1a)','Results and Discussion',6230,6359,'JEOL JEM-2010 transmission electron microscope',NULL);
INSERT INTO "characterizations" VALUES(3905,4352,'HRTEM','some WCDs with lattice fringes of 0.21 nm spacing, others without visible fringes','some of the WCDs exhibit well‐resolved lattice fringes with a spacing of 0.21 nm','Results and Discussion',6410,6490,'JEOL JEM-2010 transmission electron microscope',NULL);
INSERT INTO "characterizations" VALUES(3906,4352,'PL','four emission peaks at 450, 513, 547 and 599 nm under 400 nm excitation','The PL spectra of WCDs show four obvious emission peaks at 450, 513, 547, and 599 nm when the excitation wavelength (λ ex) is 400 nm (Figure 1b)','Results and Discussion',6785,6929,'HORIBA FluoroMax-4 fluorescence spectrophotometer','excitation wavelength 400 nm; CIE coordinates measured on an ethanol solution at 0.625 mg mL−1');
INSERT INTO "characterizations" VALUES(3907,4352,'TGA','97.87% of the weight retained at 200 °C','The thermogravimetric curve was measured using a Setaram Labsys Evo thermogravimetric analyzer with a heating rate of 10 °C min−1 in a nitrogen atmosphere.','Characterization',27461,27616,'Setaram Labsys Evo thermogravimetric analyzer','heating rate of 10 °C min−1 in a nitrogen atmosphere');
INSERT INTO "characterizations" VALUES(3908,4352,'column chromatography','WCDs are a mixture of four kinds of CDs (BCDs, GCDs, YCDs, RCDs)','The photoluminescent (PL) spectra and column chromatography show that the synthesized WCDs are composed of four kinds of CDs, namely BCDs, GCDs, YCDs, and RCDs.','Introduction',4458,4618,NULL,NULL);
INSERT INTO "characterizations" VALUES(3909,4360,'XRD','broad diffraction band centered at about 24.5°, (002) plane of graphite, amorphous structure','BCDs, GCDs, and YCDs show a broad diffraction band centered at about 24.5°, corresponding to the (002) crystal plane of graphite structure demonstrating amorphous structures of CDs.','Results and Discussion',9248,9429,'Rigaku-D/Max 2500','Cu Kα radiation');
INSERT INTO "characterizations" VALUES(3910,4360,'Raman','D band at 1262 cm−1 and G band at 1607 cm−1 (given for the four CDs together)','The Raman spectra of multicolor CDs exhibit an obvious D band at 1262 cm−1 and a G band at 1607 cm−1','Results and Discussion',9698,9798,'HORIBA Evolution Raman spectrometer',NULL);
INSERT INTO "characterizations" VALUES(3911,4360,'FTIR','C=O band at 1724 cm−1 and –OH band at 1423 cm−1 of carboxylic acid (given for BCDs and GCDs)','For BCDs and GCDs, a stretching vibration band at 1724 cm−1 from C=O and a bending vibration band at 1423 cm−1 from the –OH of carboxylic acid','Results and Discussion',11333,11475,'TENSOR2 spectrometer',NULL);
INSERT INTO "characterizations" VALUES(3912,4360,'XPS','carbon, nitrogen and oxygen present; atomic and component contents in Tables S1–S4','The full scan XPS of four CDs demonstrates the presence of carbon, nitrogen, and oxygen elements','Results and Discussion',12105,12201,'AXIS ULTRA DLD',NULL);
INSERT INTO "characterizations" VALUES(3913,4360,'UV–vis','long-wavelength absorption band at about 300 nm (given for BCDs and GCDs)','For BCDs and GCDs, the long‐wavelength absorption bands are located at about 300 nm with a low oscillator strength','Results and Discussion',13984,14098,'HITACHI U-3900 spectrophotometer','Egap = 1240/λedge, λedge the wavelength of the maximum absorption edge');
INSERT INTO "characterizations" VALUES(3914,4360,'TRPL','average lifetime 1.36 ns (parameters in Table S5)','the time‐resolved PL decay (TRPL) curves of BCDs, GCDs, YCDs, and RCDs were tested at the λ ex of 375 nm','Results and Discussion',15624,15728,'EDINBURGH FLS980 spectrometer','excitation wavelength 375 nm; double-exponential fit');
