INSERT INTO "outcomes" VALUES(17611,3951,'uv_vis_absorption_maximum',455.0,NULL,'nm','In the UV–Visible spectrum a strong broad peak was observed at 455 nm, and widening of the peak indicated that the particles were polydispersed (Fig. 1.1).','Characterization of AgNPs',16290,16445,NULL);
INSERT INTO "outcomes" VALUES(17612,3951,'average_particle_size_DLS',30.5,NULL,'nm','Their size ranges from in between 5–85 nm (Fig. 1.2), and the size distribution histogram of DLS indicated that the average size was 30.5 nm (Fig.1).','Characterization of AgNPs',16645,16794,NULL);
