INSERT INTO "outcomes" VALUES(17895,4001,'PL_peak_positions',NULL,'~ 620 nm and ~ 670 nm',NULL,'Two peaks can be found in the PL spectra, ~ 620 nm and ~ 670 nm, and can be correlated to the B1 and A1 excitons of MoS2, respectively.','Results',11251,11386,NULL);
INSERT INTO "outcomes" VALUES(17896,4001,'film_size',NULL,'1 cm × 3 cm, limited by the size and temperature uniformity of the setup',NULL,'We should note that the size of the synthesized thin film (1 cm × 3 cm) is limited by the size and temperature uniformity of our current synthetic setup.','Results',8470,8623,NULL);
INSERT INTO "outcomes" VALUES(17897,4001,'field_effect_mobility',NULL,'0.003–0.03 cm2/V.s',NULL,'we can derive the field-effect mobility of charge carriers in the device as 0.003–0.03 cm2/V.s','Results',14031,14125,NULL);
INSERT INTO "outcomes" VALUES(17898,4001,'transistor_type',NULL,'n-type channel field effect transistor with ohmic contacts',NULL,'These results indicate that the device is an n-type channel field effect transistor','Results',13585,13668,NULL);
INSERT INTO "outcomes" VALUES(17899,4002,'thickness_AFM',1.4,NULL,'nm','The thickness of the synthesized MoS2 monolayers and bilayers are shown 0.68 nm and 1.40 nm (Fig. 1c–d)','Results',5001,5104,NULL);
INSERT INTO "outcomes" VALUES(17900,4002,'uniformity',NULL,'similar uniformity to the monolayer film',NULL,'Similar uniformity can also be found at the synthesized bilayer MoS2 film (Fig. S9–S10).','Results',8381,8469,NULL);
INSERT INTO "outcomes" VALUES(17901,4002,'PL_efficiency',NULL,'substantially smaller than that of synthesized monolayers',NULL,'We can find that the PL efficiency of the synthesized MoS2 bilayer is indeed substantially smaller than that of synthesized monolayers (Fig. S16).','Results',12376,12522,NULL);
INSERT INTO "outcomes" VALUES(17902,4002,'optical_contrast_on_sapphire',NULL,'little difference from the monolayer',NULL,'We can also find that the color contrasts of MoS2 monolayer and bilayer films bear little difference on sapphire but are substantially different on SiO2/Si','Results',4551,4706,NULL);
INSERT INTO "outcomes" VALUES(17903,4003,'optical_color',NULL,'pink',NULL,'the monolayer showing pink color while the bilayer more bluish','Results',4708,4770,NULL);
INSERT INTO "outcomes" VALUES(17904,4003,'PL_intensity',NULL,'much weaker than the films grown on sapphire',NULL,'We find that the PL from the MoS2 monolayer film grown on SiO2/Si substrates is much weaker than the films grown on sapphire (Fig. S15)','Results',11908,12043,NULL);
INSERT INTO "outcomes" VALUES(17905,4003,'crystalline_quality',NULL,'probably poorer than the films grown on sapphire',NULL,'probably due to a poorer crystalline quality in the films grown on SiO2/Si substrates than those grown on sapphire as reported previously','Results',12045,12182,NULL);
INSERT INTO "outcomes" VALUES(17906,4004,'optical_color',NULL,'more bluish than the monolayer',NULL,'the monolayer showing pink color while the bilayer more bluish','Results',4708,4770,NULL);
INSERT INTO "outcomes" VALUES(17907,4005,'layer_number',NULL,'bilayer, whereas the film on sapphire grown side by side is a monolayer',NULL,'With the same experimental conditions, while the film grown on sapphire substrates is monolayer (Δk 20.4 cm−1), the one grown on HOPG is bilayer (Δk 22.4 cm−1).','Discussion',21278,21438,NULL);
INSERT INTO "outcomes" VALUES(17908,4005,'Raman_frequency_difference_dk',22.4,NULL,'cm−1','the one grown on HOPG is bilayer (Δk 22.4 cm−1)','Discussion',21390,21437,NULL);
