INSERT INTO "outcomes" VALUES(18554,4119,'grain_size_at_least',160000.0,NULL,'μm2','The grain size of h-BN for fast- and slow-cooling samples was obtained to be at least 40,000 and 160,000 μm2, respectively','Synthesis and materials characterization of multilayer h-BN',7864,7986,NULL);
INSERT INTO "outcomes" VALUES(18555,4119,'CL_D_S_intensity_ratio',0.275,NULL,NULL,'The integrated intensity ratio of D/S is small (0.275), which is comparable to that of single-crystalline h-BN.','Synthesis and materials characterization of multilayer h-BN',9135,9246,NULL);
INSERT INTO "outcomes" VALUES(18556,4119,'surface_roughness',NULL,'∼0.2 nm',NULL,'roughness values of ∼0.2 nm are obtained for both samples, confirming the high quality of the CVD-grown samples','Synthesis and materials characterization of multilayer h-BN',10973,11084,NULL);
