INSERT INTO "outcomes" VALUES(18558,4119,'elastic_modulus_2D',18000.0,NULL,'Nm−1','which results in a measured average elastic modulus of 18,000 Nm−1 corresponding to a Young''s modulus of 1.16±0.1 TPa','Mechanical strength of multilayer h-BN film',14538,14655,NULL);
INSERT INTO "outcomes" VALUES(18559,4119,'d_spacing_10-10',2.17,NULL,'Å','The d-spacings of (10–10) and (11–20) planes are obtained to be 2.17 and 1.26 Å, respectively, which are in good agreement with theoretical values.','Characterization of structural quality of multilayer h-BN',12138,12285,NULL);
INSERT INTO "outcomes" VALUES(18560,4119,'d_spacing_11-20',1.26,NULL,'Å','The d-spacings of (10–10) and (11–20) planes are obtained to be 2.17 and 1.26 Å, respectively, which are in good agreement with theoretical values.','Characterization of structural quality of multilayer h-BN',12138,12285,NULL);
INSERT INTO "outcomes" VALUES(18561,4119,'d_spacing_0002',0.33,NULL,'nm','The (0002) lattice plane with a d-spacing of 0.33 nm in e is identified from the FFT image.','Figure captions',35943,36034,NULL);
INSERT INTO "outcomes" VALUES(18562,4119,'B_N_stoichiometry',NULL,'1:1',NULL,'It was also confirmed that the stoichiometry of boron and nitrogen is 1:1 through the EELS measurement, as well as through X-ray photoemission spectroscopy (Supplementary Figs 9 and 10).','Characterization of structural quality of multilayer h-BN',13340,13526,NULL);
INSERT INTO "outcomes" VALUES(18563,4119,'contact_angle_increase_vs_bare_Fe',NULL,'>30°',NULL,'The contact angle is increased by >30°, suggesting that these h-BN films can be used as hydrophobic surface coatings.','Synthesis and materials characterization of multilayer h-BN',10576,10693,NULL);
INSERT INTO "outcomes" VALUES(18564,4119,'average_terrace_size',NULL,'10 × 10 μm2 or larger',NULL,'The average terrace size of h-BN film was roughly obtained to be 10 × 10 μm2 or larger from AFM morphology analysis (Supplementary Fig. 6).','Synthesis and materials characterization of multilayer h-BN',11216,11355,NULL);
INSERT INTO "outcomes" VALUES(18565,4119,'Fe_substrate_reuse_cycles_with_identical_growth',10.0,NULL,NULL,'Even after 10 synthesis and transfers of h-BN on the reused Fe substrate, the morphology and quality of the growth results were confirmed to be almost identical (Supplementary Fig. 1).','Synthesis and materials characterization of multilayer h-BN',6364,6548,NULL);
INSERT INTO "outcomes" VALUES(18566,4120,'film_thickness_average',11.9,NULL,'nm','In the case of fast cooling (Supplementary Fig. 2b,c), a relatively thin h-BN film (an average thickness of 11.9 nm with a s.d. of 3.3 nm) with triangular islands covered the Fe surface (Supplementary Figs 3 and 4).','Synthesis and materials characterization of multilayer h-BN',7232,7447,NULL);
INSERT INTO "outcomes" VALUES(18567,4120,'grain_size_at_least',40000.0,NULL,'μm2','The grain size of h-BN for fast- and slow-cooling samples was obtained to be at least 40,000 and 160,000 μm2, respectively','Synthesis and materials characterization of multilayer h-BN',7864,7986,NULL);
INSERT INTO "outcomes" VALUES(18568,4121,'domain_size',NULL,'between 100 μm to a few hundred micrometres',NULL,'A typical size of a single-crystalline graphene domain is between 100 μm to a few hundred micrometres (Supplementary Fig. 15).','Device applications of multilayer h-BN',18445,18571,NULL);
INSERT INTO "outcomes" VALUES(18569,4122,'PL_exciton_emission_enhancement_on_hBN_vs_SiO2',NULL,'∼13 times greater',NULL,'The exciton emission of MoS2 on a h-BN substrate (ΔI1) is ∼13 times greater than that of MoS2 on a SiO2 substrate (ΔI2), respectively.','Optical and electrical properties of MoS2 and WSe2 on h-BN',23512,23646,NULL);
