INSERT INTO "outcomes" VALUES(18573,4122,'monolayer_thickness_AFM',NULL,'around 1 nm',NULL,'The thickness of monolayer MoS2 is around 1 nm, indicating that MoS2 is indeed monolayer.','Supporting Information — ncomms9662-s1.pdf',47642,47731,NULL);
INSERT INTO "outcomes" VALUES(18574,4123,'PL_exciton_emission_enhancement_on_hBN_vs_SiO2',NULL,'~ 6 times greater',NULL,'The exciton emission of WSe2 on an h-BN substrate (ΔI1) is ~ 6 times greater than that of WSe2 on a SiO2 substrate (ΔI2).','Supporting Information — ncomms9662-s1.pdf',49076,49197,NULL);
INSERT INTO "outcomes" VALUES(18575,4123,'monolayer_thickness_AFM',NULL,'around 1 nm',NULL,'The thickness of monolayer WSe2 film is around 1 nm, indicating that WSe2 is indeed monolayer.','Supporting Information — ncomms9662-s1.pdf',48106,48200,NULL);
INSERT INTO "outcomes" VALUES(18576,4127,'breakdown_electric_field',NULL,'∼2–4 MV cm−1 for a film thickness of 8–15 nm',NULL,'The breakdown electric field for a typical film thickness of 8–15 nm was ∼2–4 MV cm−1, which is within observed values for crystalline h-BN.','Dielectric properties of multilayer h-BN film',16028,16168,NULL);
