INSERT INTO "outcomes" VALUES(18580,4128,'relative_dielectric_constant',NULL,'3 to 5 (average)',NULL,'The average relative dielectric constant ranged from 3 to 5, which is consistent with expected values.','Dielectric properties of multilayer h-BN film',17336,17438,NULL);
