INSERT INTO "outcomes" VALUES(18966,4182,'BJH_pore_diameter_H2O_EtOH_series',33.0,NULL,'Å','Samples synthesized at pH 2.5 from mixtures of H2O and EtOH with molar ratios of 1.5 (pure MIL-100), 3.4 (mixture of MIL-100 and MIL-110) and 3.9 (mixture of MIL-100 and MIL-96) exhibited the narrowest BJH pore size distributions, which are centered at 33 Å','Influence of EtOH/H2O molar ratio',18933,19190,NULL);
INSERT INTO "outcomes" VALUES(18967,4183,'isotherm',NULL,'no hysteresis but high uptake at high P/P 0 (close to P/P 0 = 1)',NULL,'The isotherm acquired for the MOF obtained without a surfactant (Fig. S8†) showed no hysteresis but high uptake at high P/P 0 (close to P/P 0 = 1), pointing to the formation of much bigger MOF crystals and condensation in macropores formed around these bigger particles','Influence of pH',17262,17531,NULL);
INSERT INTO "outcomes" VALUES(18968,4184,'BJH_pore_size_distribution_center',18.0,NULL,'nm','The narrowest pore distributions were observed for the lowest CTAB/Al3+ ratio with pore size distributions centered at 18 nm','Supporting Information — CE-017-C4CE02324B-s001.pdf',31441,31565,NULL);
INSERT INTO "outcomes" VALUES(18969,4184,'S_EXT_over_S_INT',1.3,NULL,NULL,'Moreover, when CTAB/Al3+ was decreased from 1.2 to 0.3, the SEXT/SINT ratio increased from 0.7 to 1.3, respectively.','Supporting Information — CE-017-C4CE02324B-s001.pdf',31592,31708,NULL);
INSERT INTO "outcomes" VALUES(18970,4184,'mesoporosity_trend',NULL,'a decrease in the amount of CTAB led to a higher mesoporosity together with a narrower BJH pore size distribution',NULL,'It seems that a decrease in the amount of CTAB in the synthesis solution led to a higher mesoporosity together with a narrower BJH pore size distribution.','Supporting Information — CE-017-C4CE02324B-s001.pdf',31709,31863,NULL);
