INSERT INTO "outcomes" VALUES(19350,4244,'SBF_reagents',NULL,'sodium chloride salts, sodium hydrogen carbonate, potassium chloride, dipotassium hydrogen phosphate triplets, and magnesium chloride 6 hydrate (quantities calculated and prepared as in Table 2)',NULL,'The quantity of sodium chloride salts, sodium hydrogen carbonate, potassium chloride, dipotassium hydrogen phosphate triplets, and magnesium chloride 6 hydrate were calculated and prepared as in Table 2.','Preparation of simulated body fluid (SBF)',7941,8144,NULL);
INSERT INTO "outcomes" VALUES(19351,4244,'SBF_medium_preparation',NULL,'SBF prepared based on the Kokubo guidelines; the reagents were dissolved one by one in 1 L distilled water; buffered to pH = 7 with a solution of tris-hydroxyethyl aminomethane and hydrochloric acid',NULL,'The reagents were then dissolved one by one in 1 L distilled water, and the solution was buffered to pH = 7 with a solution of tris-hydroxyethyl aminomethane and hydrochloric acid.','Preparation of simulated body fluid (SBF)',8145,8325,NULL);
INSERT INTO "outcomes" VALUES(19352,4244,'SBF_immersion_duration',14.0,NULL,'days','immersion in Simulated Body Fluid (SBF) solution was carried out for 14 days under optimal conditions','Bioactive behavior of HAp powder',39559,39660,NULL);
INSERT INTO "outcomes" VALUES(19353,4244,'SBF_immersion_14_days_final_pH',NULL,'decreased to about 7 (initial pH of 7.4)',NULL,'After 14 days of nanometer hydroxyapatite immersion in the SBF solution, the solution pH decreased to about 7.','Bioactive behavior of HAp powder',39984,40094,NULL);
INSERT INTO "outcomes" VALUES(19354,4244,'bioactivity_SBF',NULL,'formation of a porous apatite layer on the HAp surface after immersion in SBF',NULL,'The formation of a porous apatite layer on the HAp surface in SBF solution is shown in Fig 21C, which indicates suitable level bioactivity of produced HAp [].','Bioactive behavior of HAp powder',41400,41558,NULL);
INSERT INTO "outcomes" VALUES(19355,4244,'SBF_EDX_Ca_P_peaks',NULL,'the peaks belonging to Ca and P have increased after immersion in SBF',NULL,'Due to the formation of an apatite layer on the HAp surface after immersion in SBF solution, the peaks belonging to Ca and P have increased.','Bioactive behavior of HAp powder',41767,41907,NULL);
INSERT INTO "outcomes" VALUES(19356,4245,'MnO2NFs_phase',NULL,'tetragonal α-MnO2',NULL,'It is in good agreement with XRD standard card JSPDF 44-0141 [,], suggesting tetragonal crystalline of α-MnO2 were successfully synthesized.','3.1. Physical Chararazation',12392,12532,NULL);
INSERT INTO "outcomes" VALUES(19357,4245,'MnO2NFs_morphology',NULL,'flower-like nanostructures composed of interconnected nanoflakes',NULL,'Obviously, flower-like nanostructures composed of interconnected nanoflakes suggests MnO2 nanoflowers were successfully synthesized.','3.1. Physical Chararazation',12674,12806,NULL);
INSERT INTO "outcomes" VALUES(19358,4246,'MnO2NFs_NrGO_morphology',NULL,'NrGO nanosheets were warped on the surface of MnO2NFs',NULL,'As shown in Figure 2C,D, the NrGO nanosheets were warped on the surface of MnO2NFs, suggesting MnO2NFs/NrGO nanocomposites were successfully prepared.','3.1. Physical Chararazation',12949,13099,NULL);
INSERT INTO "outcomes" VALUES(19359,4247,'effective_electroactive_area',0.7496,NULL,'cm2','The effective electroactive areas were estimated to be 0.0770, 0.3183, 0.3958, and 0.7496 cm2 for the bare GCE, MnO2NFs/GCE, NrGO/GCE, and MnO2NFs/NrGO/GCE, respectively.','3.2. Evaluation of Electrochemical Performances',14536,14706,NULL);
