INSERT INTO "outcomes" VALUES(19361,4247,'anodic_peak_current_ferricyanide',92.41,NULL,'μA','As expected, a well-defined and sharp redox peak was observed at the MnO2NFs/NrGO/GCE, with the highest anodic and cathodic peak currents (ipa = 92.41 μA, ipc = 87.89 μA).','3.2. Evaluation of Electrochemical Performances',13651,13822,NULL);
