INSERT INTO "outcomes" VALUES(19363,4247,'anodic_peak_current_DA_CV_10uM',14.8,NULL,'μA','Two sharp anodic peaks occurred at MnO2NFs/NrGO/GCE, and the anodic peak currents enhanced remarkably (ipa(DA) = 14.8 μA, ipa(UA) = 36.3 μA).','3.3. Voltammetric Responses of DA and UA at Various Electrodes',17854,17995,NULL);
