INSERT INTO "outcomes" VALUES(19365,4247,'peak_potential_separation_DA_UA',150.0,'about 150 mV','mV','It is worth noting the biggest peak potential separation (about 150 mV) at MnO2NFs/NrGO/GCE, rendering this composite more selective for the simultaneous detection of UA and DA.','3.3. Voltammetric Responses of DA and UA at Various Electrodes',18417,18594,NULL);
