INSERT INTO "outcomes" VALUES(19370,4247,'linear_range_simultaneous_low',NULL,'0.02 μM–6.0 μM',NULL,'At the lower concentration region (0.02 μM–6.0 μM), the ipa(DA) and ipa(UA) enhanced linearly with their concentrations increasing (Figure 10A, B).','3.5. Individual and Simultaneous Determination of DA and UA',24100,24247,NULL);
INSERT INTO "outcomes" VALUES(19371,4247,'linear_range_simultaneous_high',NULL,'6.0 μM to 100 μM (linear in the Napierian logarithm of the concentration)',NULL,'However, the ipa(DA) and ipa(UA) are positively proportional to the Napierian logarithm of the DA and UA concentrations (lnCDA and lnCUA) at the higher concentration region from 6.0 μM to 100 μM (Figure 10C, D).','3.5. Individual and Simultaneous Determination of DA and UA',24389,24600,NULL);
INSERT INTO "outcomes" VALUES(19372,4247,'repeatability_RSD_DA',6.35,'eight successive determinations of 1 μM DA and UA (1:1)','%','To check the repeatability, eight successive determinations of 1 μM DA and UA (1:1) were also performed. The relative standard deviation (RSD) for DA and UA were 6.35% and 5.32%, respectively, indicating good repeatability.','3.6. Selectivity, Repeatability, and Reproducbility Assay',25998,26221,NULL);
INSERT INTO "outcomes" VALUES(19373,4247,'repeatability_RSD_UA',5.32,'eight successive determinations of 1 μM DA and UA (1:1)','%','To check the repeatability, eight successive determinations of 1 μM DA and UA (1:1) were also performed. The relative standard deviation (RSD) for DA and UA were 6.35% and 5.32%, respectively, indicating good repeatability.','3.6. Selectivity, Repeatability, and Reproducbility Assay',25998,26221,NULL);
INSERT INTO "outcomes" VALUES(19374,4247,'reproducibility_RSD_DA',6.02,'anodic peak currents of 1 μM DA and UA recorded at five MnO2NFs/NrGO/GCEs','%','To examine electrode reproducibility, the anodic peak currents of 1 μM DA and UA were recorded at five MnO2NFs/NrGO/GCEs, which were prepared by similar procedure. The RSD of the anodic peaks were 6.02% and 4.70% for DA and UA respectively, showing that the electrode preparation have excellent reproducibility.','3.6. Selectivity, Repeatability, and Reproducbility Assay',26222,26533,NULL);
INSERT INTO "outcomes" VALUES(19375,4247,'reproducibility_RSD_UA',4.7,'anodic peak currents of 1 μM DA and UA recorded at five MnO2NFs/NrGO/GCEs','%','To examine electrode reproducibility, the anodic peak currents of 1 μM DA and UA were recorded at five MnO2NFs/NrGO/GCEs, which were prepared by similar procedure. The RSD of the anodic peaks were 6.02% and 4.70% for DA and UA respectively, showing that the electrode preparation have excellent reproducibility.','3.6. Selectivity, Repeatability, and Reproducbility Assay',26222,26533,NULL);
INSERT INTO "outcomes" VALUES(19376,4247,'interference_tolerance',NULL,'relative errors less than 5% in the presence of 100-fold interfering species (ascorbic acid, alanine, citric acid, glutamic acid, cysteine, and lysine)',NULL,'the LSV responses of the DA and UA in the coexistence of common interfering substances (i.e., ascorbic acid, alanine, citric acid, glutamic acid, cysteine, and lysine) were compared. The relative errors (less than 5%) were accepted even in the presence of 100-fold the above interfering species, demonstrating good selectivity (Figure S1).','3.6. Selectivity, Repeatability, and Reproducbility Assay',25517,25856,NULL);
INSERT INTO "outcomes" VALUES(19377,4247,'peak_potential_separation_AA_DA',0.26,'∆Ep = 0.260 V','V','It is noted that the 100-fold AA have no obvious interfering because of the well-separated peak potential between AA and DA (∆Ep = 0.260 V).','3.6. Selectivity, Repeatability, and Reproducbility Assay',25857,25997,NULL);
