INSERT INTO "outcomes" VALUES(19430,4253,'TEM_coverage',NULL,'coverage of nanoparticles with a layer of neodymium particles',NULL,'The only difference is the coverage of nanoparticles with a layer of neodymium particles as shown in Fig. 4c.','Structural and morphological analysis',16620,16729,NULL);
INSERT INTO "outcomes" VALUES(19431,4253,'EDS_elements',NULL,'Nd, Zn and O',NULL,'The results clearly indicate that Nd-doped ZnO nanoparticle contains three elements such as Nd, Zn and O, suggesting the existence of Nd into ZnO nanoparticles.','Structural and morphological analysis',15819,15979,NULL);
INSERT INTO "outcomes" VALUES(19432,4253,'HRTEM_lattice_fringe_spacing_101',0.26,NULL,'nm','The lattice fringe with inter-planar distance of 0.26 nm corresponds to the plane of (101) of ZnO nanoparticles as shown in Fig. 4d.','Structural and morphological analysis',16730,16862,NULL);
