INSERT INTO "outcomes" VALUES(19436,4253,'TGA_weight_loss_up_to_400C',NULL,'slight weight loss in both materials were observed up to 400 °C',NULL,'It could be seen from the figure that slight weight loss in both materials were observed up to 400 °C, which may be due to the loss of water molecule adsorbed on the surface of ZnO nanoparticles.','TGA analysis',19919,20114,NULL);
INSERT INTO "outcomes" VALUES(19437,4253,'TGA_weight_loss_vs_pure_ZnO',NULL,'relatively more weight loss than pure ZnO',NULL,'In contrast to pure ZnO, Nd-doped ZnO nanoparticles shows relatively more weight loss due to more adsorption of water molecule on the surface of Nd-doped ZnO nanoparticles.','TGA analysis',20315,20487,NULL);
INSERT INTO "outcomes" VALUES(19438,4253,'TGA_weight_loss_above_400C',NULL,'No significant weight loss was observed after 400 °C',NULL,'No significant weight loss was observed after 400 °C, indicating exceptionally high thermal stability of the prepared samples.','TGA analysis',20188,20314,NULL);
INSERT INTO "outcomes" VALUES(19439,4253,'PL_quenching',NULL,'significant quenching in the PL emission signal compared with pure and other RE-doped ZnO',NULL,'As compared to pure and other RE-doped ZnO nanoparticles, Nd-doped ZnO nanoparticles showed significant quenching in the PL emission signal suggesting Nd doping may lead to better separation efficiency and hence better photocatalytic activity.','Photoluminescence (PL) study',19406,19649,NULL);
INSERT INTO "outcomes" VALUES(19440,4253,'MB_photodegradation',98.0,'98% degradation efficiency of MB (légende de la Fig. 8 : catalyst used 2 g L−1, pH = 10 ; durée d''irradiation non citée)','%','Nd-doped ZnO showed the best activity with 98% degradation efficiency','Abstract',1143,1212,NULL);
INSERT INTO "outcomes" VALUES(19441,4253,'MB_rate_constant_pseudo_first_order_TableS1',0.158,NULL,'min-1','Nd-ZnO 0.158','Supporting Information — RA-008-C8RA01638K-s001.pdf',45491,45503,NULL);
INSERT INTO "outcomes" VALUES(19442,4253,'RhB_photodegradation',NULL,'excellent photocatalytic performance than that of the other catalysts and commercial ZnO',NULL,'For this dye as well, Nd-doped ZnO was found to show the excellent photocatalytic performance than that of the other catalysts and commercial ZnO','Photocatalytic activity',25651,25796,NULL);
INSERT INTO "outcomes" VALUES(19443,4253,'MB_TOC_removal_180min',NULL,'64–68 ± 6% mineralization',NULL,'The results indicate the 64–68 ± 6% mineralization of MB in 180 min of irradiation.','Photocatalytic activity',26257,26340,NULL);
INSERT INTO "outcomes" VALUES(19444,4253,'MB_TOC_test_conditions',NULL,'MB (50, 100 ppm) in the presence of Nd-doped ZnO (4 g L−1)',NULL,'the mineralization of MB measured in terms of TOC% removal on irradiation of an aqueous solution of MB (50, 100 ppm) in the presence of Nd-doped ZnO (4 g L−1)','Photocatalytic activity',26097,26255,NULL);
INSERT INTO "outcomes" VALUES(19445,4253,'MB_degradation_optimum_pH',10.0,'highest degradation is observed at pH 10 (pH range 5–11 studied)',NULL,'degradation efficiency increases with increasing pH and highest degradation is observed at pH 10','Effect of pH on degradation of MB',27240,27336,NULL);
INSERT INTO "outcomes" VALUES(19446,4253,'MB_degradation_optimum_catalyst_loading',2.0,'degradation efficiency increases from 1 to 2 g L−1 and then decreases (1 to 3 g L−1 studied)','g L−1','degradation efficiency increases with increasing catalyst dosage from 1 to 2 g L−1 and then decreases','Effect of catalyst dosage on degradation of MB',28583,28684,NULL);
INSERT INTO "outcomes" VALUES(19447,4253,'MB_degradation_vs_initial_concentration',NULL,'% degradation of MB decreases with increase in initial concentration from 10 ppm onwards (10–30 ppm studied)',NULL,'The results indicate that the % degradation of MB decreases with increase in initial concentration from 10 ppm onwards.','Effect of initial MB concentration',29724,29843,NULL);
INSERT INTO "outcomes" VALUES(19448,4253,'MB_oxidant_test_conditions',NULL,'(NH4)2S2O8, KBrO3 (2 mM) and H2O2 (10 mM)',NULL,'The effect of oxidants on the degradation of MB was studied at fixed concentration of (NH4)2S2O8, KBrO3 (2 mM) and H2O2 (10 mM), respectively.','Effect of oxidants on degradation of MB',30574,30716,NULL);
INSERT INTO "outcomes" VALUES(19449,4253,'MB_degradation_with_oxidants',NULL,'all the oxidants promoted the degradation and dye was found to decolorize within 15 min of illumination',NULL,'As expected, all the oxidants promoted the degradation and dye was found to decolorize within 15 min of illumination.','Effect of oxidants on degradation of MB',30919,31036,NULL);
INSERT INTO "outcomes" VALUES(19450,4253,'MB_degradation_oxidant_most_effective',NULL,'most profound effect with H2O2',NULL,'The most profound effect was observed in the case of H2O2.','Effect of oxidants on degradation of MB',31213,31271,NULL);
INSERT INTO "outcomes" VALUES(19451,4253,'MB_inorganic_anion_test_conditions',NULL,'MB (10 ppm), Nd-doped ZnO (2 g L−1), NaCl and Na2SO4 (0.2 mM)',NULL,'In this study, photocatalytic experiments were carried out using MB (10 ppm), Nd-doped ZnO (2 g L−1), anions such as NaCl and Na2SO4 (0.2 mM) under analogous conditions.','Effect of inorganic anions on degradation of MB',31931,32100,NULL);
INSERT INTO "outcomes" VALUES(19452,4253,'MB_degradation_with_inorganic_anions',NULL,'all anions make an adverse effect on the degradation of pollutant, with significant reduction with Cl− ions',NULL,'It could be seen from the figure that all anions make an adverse effect on the degradation of pollutant under investigation with significant reduction with Cl− ions.','Effect of inorganic anions on degradation of MB',32101,32266,NULL);
INSERT INTO "outcomes" VALUES(19453,4253,'MB_scavenger_IPA',NULL,'significant reduction in MB degradation (hydroxyl radical quenched)',NULL,'The results also indicate that the addition of IPA showed significant reduction in MB degradation by quenching hydroxyl radical formed in the reaction mixture indicating this species being actively involved in the degradation process.','Trapping studies and photocatalytic mechanism',34877,35111,NULL);
INSERT INTO "outcomes" VALUES(19454,4253,'MB_scavenger_BQ_EDTA',NULL,'photodegradation of MB is slightly reduced on addition of BQ and EDTA-2Na',NULL,'the photodegradation of MB is slightly reduced on addition of BQ and EDTA-2Na','Trapping studies and photocatalytic mechanism',35122,35199,NULL);
INSERT INTO "outcomes" VALUES(19455,4253,'terephthalic_acid_PL_signal_425nm',NULL,'PL intensity gradually increases with increasing irradiation time (PL signal observed at 425 nm)',NULL,'the PL intensity (due to the formation of hydroxyl radical) gradually increases with increasing irradiation time as evidenced by PL signal observed at 425 nm','Trapping studies and photocatalytic mechanism',36155,36312,NULL);
INSERT INTO "outcomes" VALUES(19456,4253,'MB_optimal_degradation_conditions',NULL,'2 g L−1 catalyst, reaction pH = 10 and 10 ppm MB concentration',NULL,'The results reveal that the optimal degradation conditions for MB degradation are: 2 g L−1 catalyst, reaction pH = 10 and 10 ppm MB concentration.','Conclusions',39341,39487,NULL);
