INSERT INTO "outcomes" VALUES(19654,4260,'phase',NULL,'pure zeolite X',NULL,'The prepared pure zeolite X with binary meso-microporous structure possessed remarkable thermal stability, high calcium ion exchange capacity of 248 mg/g and large surface area of 453 m2/g.','4. Conclusions',21333,21522,NULL);
INSERT INTO "outcomes" VALUES(19655,4260,'calcium_ion_exchange_capacity',248.0,NULL,'mg/g','Meanwhile, the calcium ion exchange capacity of the prepared zeolite X sample is 248 mg/g, which is higher than that of commercial zeolites X (232 mg/g).','3.4. Effect of Alkalinity',17938,18091,NULL);
INSERT INTO "outcomes" VALUES(19656,4260,'BET_surface_area',453.0,NULL,'m2/g','The specific surface area and total pore volume were up to 453 m2/g and 0.2838 cm3/g, respectively.','3.6. N2 Adsorption Performance',20226,20325,NULL);
