INSERT INTO "outcomes" VALUES(19666,4260,'Si_content_raw_material',3.22,NULL,'g','In addition, the contents of Si in the raw material and the synthesized X zeolite is 3.22 and 2.88 g, respectively, which is a highly efficient use of diatomite.','3.5. TG-DTA and XRF Analysis',18365,18526,NULL);
