INSERT INTO "outcomes" VALUES(19668,4260,'moisture_loss_TG',22.0,NULL,'wt %','TG results showed that the synthesized zeolite X products lost all its moisture (22 wt %) at temperatures lower than 350 °C.','3.5. TG-DTA and XRF Analysis',18773,18897,NULL);
INSERT INTO "outcomes" VALUES(19669,4260,'DTA_endothermic_peak_water_loss',150.0,NULL,'°C','Furthermore, DTA curves showed that the endothermic peaks occurred at lower temperatures (150 °C) of the synthesized zeolite X sample, which could be assigned to the loss of adsorbed water.','3.5. TG-DTA and XRF Analysis',19041,19230,NULL);
INSERT INTO "outcomes" VALUES(19670,4260,'DTA_exothermic_peak_framework_collapse',820.0,NULL,'°C','However, the exothermic peaks at the temperature of 820 °C could be attributed to the framework collapse and crystallization of NaAlSiO4 (JCPDS 52-1342), which can be attributed to the nepheline (Figure 11b).','3.5. TG-DTA and XRF Analysis',19231,19439,NULL);
