INSERT INTO "outcomes" VALUES(19678,4262,'phase',NULL,'typical diffraction peaks of X zeolite, zeolite X started to crystallize',NULL,'When the temperature was raised to 100 °C, typical diffraction peaks of X zeolite (JCPDS 38-0237) can be seen at 2θ = 6.10°, 9.97°, 11.76°, 15.39°, 18.46°, 20.12°, 23.24°, 26.58° and 30.86° suggesting that zeolite X started to crystallize (Figure 2a).','3.2. Effect of Crystallization',9846,10097,NULL);
