INSERT INTO "outcomes" VALUES(19877,4329,'phase',NULL,'pure ZIF-8 phase for n-hexane ≥3 v/v %',NULL,'With a further increment in the n-hexane concentration, a pure ZIF-8 phase was formed in the synthesis with n-hexane concentrations ≥3 v/v % (i.e., ≥1 mL).','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',21134,21289,NULL);
INSERT INTO "outcomes" VALUES(19878,4329,'hollow_structure',NULL,'no hollow structures, solid nanocrystals',NULL,'The absence of any hollow structures in these samples indicated that lower oil contents favored the formation of solid ZIF nanocrystals.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18539,18675,NULL);
INSERT INTO "outcomes" VALUES(19879,4330,'crystal_size',350.0,NULL,'nm','All samples showed spherical crystals with slightly increasing sizes, from ∼220 nm (1 v/v %) to ∼260 nm (3 v/v %), and then to ∼350 nm (5 v/v %), as also shown in Figure 2b–d.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18363,18538,NULL);
INSERT INTO "outcomes" VALUES(19880,4330,'phase',NULL,'pure ZIF-8 phase for n-hexane ≥3 v/v %',NULL,'With a further increment in the n-hexane concentration, a pure ZIF-8 phase was formed in the synthesis with n-hexane concentrations ≥3 v/v % (i.e., ≥1 mL).','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',21134,21289,NULL);
INSERT INTO "outcomes" VALUES(19881,4330,'hollow_structure',NULL,'no hollow structures, solid nanocrystals',NULL,'The absence of any hollow structures in these samples indicated that lower oil contents favored the formation of solid ZIF nanocrystals.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18539,18675,NULL);
INSERT INTO "outcomes" VALUES(19882,4331,'average_sphere_diameter',2.5,NULL,'μm','Figure 2e showed that a minimum of 9 v/v % of n-hexane was required to form a stable ME for initiating the growth of hollow structures with an average diameter of ∼2.50 ± 0.95 μm (Table S1) and a shell thickness of ∼0.25 ± 0.05 μm.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18804,19035,NULL);
INSERT INTO "outcomes" VALUES(19883,4331,'sphere_diameter_standard_deviation',0.95,NULL,NULL,'hollow structures with an average diameter of ∼2.50 ± 0.95 μm (Table S1)','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18921,18993,NULL);
INSERT INTO "outcomes" VALUES(19884,4331,'shell_thickness',0.25,NULL,'μm','Figure 2e showed that a minimum of 9 v/v % of n-hexane was required to form a stable ME for initiating the growth of hollow structures with an average diameter of ∼2.50 ± 0.95 μm (Table S1) and a shell thickness of ∼0.25 ± 0.05 μm.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18804,19035,NULL);
INSERT INTO "outcomes" VALUES(19885,4331,'particle_size_distribution',NULL,'broad PSD (∼0.50 to ∼5.5 μm), solid nanocrystals mixed with microsized hollow particles',NULL,'a broad PSD (∼0.50 to ∼5.5 μm) was observed, and the sample contained a majority of solid nanocrystals mixed with microsized hollow spherical particles','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',19132,19283,NULL);
INSERT INTO "outcomes" VALUES(19886,4331,'emulsion_droplet_size',NULL,'∼3.40 ± 1.10 μm',NULL,'having an average droplet size of ∼3.40 ± 1.10 μm along with the droplet size distribution curve','Pre-synthesis Ultrasonication',16408,16504,NULL);
