INSERT INTO "reagents" VALUES(4200,4027,'triethanolamine',NULL,'base',0.3,'vt%',NULL,NULL,'Aladdin Chemistry Co., Ltd.','For example under the same condition with 0.3 vt% TEA as base catalyst and 0.75 vt% TEOS as silica source, MSNs at 60 or 80 nm was obtained with 10 wt% CTAB or CTAC as templates, respectively.','Size-controlled synthesis and characterization of Ru@MSNs nanosystems',18072,18264,'Diethanolamine (DEA), triethanolamine (TEA), cetyltrimethylammonium chloride (CTAC), cetyltrimethylammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 1-(3-(dimethylamino)-propyl)-3-ethylcarbodiimide hydrochloride (EDC), N-Hydroxysuccinimide (NHS), poly (etherimide) (PEI, Mw =10,000), and folic acid (FA) were purchased from Aladdin Chemistry Co., Ltd. (Shanghai, China).');
