INSERT INTO "reagents" VALUES(4249,4079,'formamidinium acetate',NULL,'precursor',15.0,'mmol','1.563 g','99%','Sigma-Aldrich','In a three-necked round-bottom flask, 15 mmol (1.563 g) of FA-acetate, 15 mL of OA, and 15 mL of ODE were degassed under a vacuum at room temperature and 50 °C for 30 min, respectively.','Synthesis of FA-Oleate Precursor',23814,23999,'Formamidinium acetate (FA-acetate, 99%), oleic acid (OA, technical grade 90%), oleylamine (OAm, technical grade 70%), 1-octadecene (ODE, technical grade 90%), hexane (reagent grade ≥95%), octane (anhydrous, ≥99%), methyl acetate (MeOAc, anhydrous 99.5%), ethyl acetate (EtOAc, anhydrous 99.5%), R-methybenzylamine (98% purity), S-methybenzylamine (98% purity), hydrobromic acid (ACS reagent, 48%), and ethyl acetate (EtOAc, anhydrous, 99.8%) were purchased from Sigma-Aldrich.');
