INSERT INTO "reagents" VALUES(4277,4087,'cobalt nitrate hexahydrate','Co(NO3)2·6H2O','precursor',NULL,NULL,NULL,NULL,'Thermo Scientific','The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',8850,9070,'The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.');
INSERT INTO "reagents" VALUES(4278,4087,'lithium nitrate','LiNO3','precursor',NULL,NULL,NULL,NULL,'Thermo Scientific','The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',8850,9070,'The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.');
INSERT INTO "reagents" VALUES(4279,4087,'deionized water','H2O','solvent',NULL,NULL,NULL,NULL,NULL,'The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',8850,9070,NULL);
INSERT INTO "reagents" VALUES(4280,4087,'nitrogen','N2','gas',NULL,NULL,NULL,'99.998%','BOC','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067,'This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.');
INSERT INTO "reagents" VALUES(4281,4087,'air (quenching)',NULL,'gas',NULL,NULL,NULL,NULL,NULL,'The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878,NULL);
INSERT INTO "reagents" VALUES(4282,4102,'cobalt(II) acetate tetrahydrate','C4H6CoO4·4H2O','precursor',NULL,NULL,NULL,NULL,'Acros Organics','In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9214,9503,'In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.');
INSERT INTO "reagents" VALUES(4283,4102,'lithium acetate dihydrate','C2H3LiO2·2H2O','precursor',NULL,NULL,NULL,NULL,'Acros Organics','In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9214,9503,'In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.');
INSERT INTO "reagents" VALUES(4284,4102,'deionized water','H2O','solvent',NULL,NULL,NULL,NULL,NULL,'In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9214,9503,NULL);
INSERT INTO "reagents" VALUES(4285,4102,'nitrogen','N2','gas',NULL,NULL,NULL,'99.998%','BOC','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067,'This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.');
