INSERT INTO "reagents" VALUES(4287,4114,'nitrate-derived LiCoO2 (active material; cathodes of N800_A775_0.5h and N800_A775_1h)','LiCoO2','active_material',NULL,NULL,'90 parts by weight (active material:Super-P:PVDF = 90:5:5)',NULL,NULL,'The slurry for nitrate-derived LCO was formulated by combining the active material with carbon black (Super-P) and polyvinylidene fluoride (PVDF) in a weight ratio of 90:5:5.','Coin Cell Assembly and Electrochemical Tests',11483,11657,NULL);
INSERT INTO "reagents" VALUES(4288,4114,'carbon black (Super-P)','C','conductive_additive',NULL,NULL,'5 parts by weight (active material:Super-P:PVDF = 90:5:5)',NULL,NULL,'The slurry for nitrate-derived LCO was formulated by combining the active material with carbon black (Super-P) and polyvinylidene fluoride (PVDF) in a weight ratio of 90:5:5.','Coin Cell Assembly and Electrochemical Tests',11483,11657,NULL);
