INSERT INTO "reagents" VALUES(4292,4114,'lithium metal disc (counter electrode)','Li','counter_electrode',NULL,NULL,'15 mm disc',NULL,NULL,'CR2032 coin cells were assembled in an argon-filled glovebox, each containing a 15 mm Li metal disc counter electrode, a 19 mm diameter Celgard separator, and filled with 20 μL of LP40 electrolyte (1 M LiPF6 in EC/DEC, 1:1 v/v).','Coin Cell Assembly and Electrochemical Tests',12048,12276,NULL);
