INSERT INTO "reagents" VALUES(4296,4115,'acetate-derived LiCoO2 (active material; cathodes of A900_A750_3h and A900_A750_15h)','LiCoO2','active_material',NULL,NULL,'80 parts by weight (LCO:Super P:PVDF = 80:10:10)',NULL,NULL,'Adjusting for the acetate-derived LCO’s porous aggregated structure, the electrode composition was optimized to an 80:10:10 ratio of LCO to Super P to PVDF.','Coin Cell Assembly and Electrochemical Tests',12510,12666,NULL);
INSERT INTO "reagents" VALUES(4297,4115,'carbon black (Super P)','C','conductive_additive',NULL,NULL,'10 parts by weight (LCO:Super P:PVDF = 80:10:10)',NULL,NULL,'Adjusting for the acetate-derived LCO’s porous aggregated structure, the electrode composition was optimized to an 80:10:10 ratio of LCO to Super P to PVDF.','Coin Cell Assembly and Electrochemical Tests',12510,12666,NULL);
