INSERT INTO "reagents" VALUES(4299,4115,'lithium metal (counter electrode)','Li','counter_electrode',NULL,NULL,NULL,NULL,NULL,'We assessed the effectiveness of the selected annealing conditions in synthesizing LCO particles for battery cathodes through electrochemical tests using half-cells with a Li-metal counter electrode.','Electrochemical Performance',36039,36238,NULL);
INSERT INTO "reagents" VALUES(4300,4115,'Celgard separator',NULL,'separator',NULL,NULL,'18 mm',NULL,NULL,'The processed electrodes were punched into 14 mm discs and assembled into 2032-type coin cells, incorporating an 18 mm Celgard separator and 80 μL of 1.3 M LiPF6 electrolyte in EC:DEC (3:7 wt/wt), tailored for the electrode’s specific needs.','Coin Cell Assembly and Electrochemical Tests',12813,13054,NULL);
