INSERT INTO "reagents" VALUES(4302,4116,'3-aminopropyltriethoxysilane (APTES)',NULL,'precursor',8.85,'g',NULL,'analytical grade','Shanghai Aladdin Biochemical Reagents','8.85 g (39.98 mmoL) of APTES, 4.88 g (39.96 mmoL) of salicylaldehyde, and 100 mL of ethanol were added to a flask and reacted at 95 °C for 3 h','2.2.1. Preparation of Salicylaldimine',8251,8393,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4303,4116,'salicylaldehyde',NULL,'precursor',4.88,'g',NULL,'analytical grade','Shanghai Aladdin Biochemical Reagents','8.85 g (39.98 mmoL) of APTES, 4.88 g (39.96 mmoL) of salicylaldehyde, and 100 mL of ethanol were added to a flask and reacted at 95 °C for 3 h','2.2.1. Preparation of Salicylaldimine',8251,8393,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4304,4116,'ethanol (salicylaldimine synthesis)',NULL,'solvent',100.0,'mL',NULL,'analytical grade','Tianjin Damao Chemical Reagents','8.85 g (39.98 mmoL) of APTES, 4.88 g (39.96 mmoL) of salicylaldehyde, and 100 mL of ethanol were added to a flask and reacted at 95 °C for 3 h','2.2.1. Preparation of Salicylaldimine',8251,8393,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4305,4116,'dichloromethane','CH2Cl2','solvent',10.0,'mL',NULL,'analytical grade','Tianjin Damao Chemical Reagents','the intermediate products were dissolved in 10 mL (156.01 mmoL) of dichloromethane','2.2.1. Preparation of Salicylaldimine',8443,8525,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4306,4116,'deionized water (washing of salicylaldimine)','H2O','wash',NULL,NULL,NULL,NULL,NULL,'the product was washed with deionized water three times','2.2.1. Preparation of Salicylaldimine',8533,8588,NULL);
INSERT INTO "reagents" VALUES(4307,4116,'anhydrous magnesium sulfate','MgSO4','desiccant',0.5,'g',NULL,'analytical grade','Tianjin Damao Chemical Reagents','0.5 g (4.15 mmoL) anhydrous magnesium sulfate was used to remove the residual water','2.2.1. Preparation of Salicylaldimine',8663,8746,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4308,4116,'cetyl trimethyl ammonium bromide (CTAB)',NULL,'template',1.5,'g',NULL,'analytical grade','Shanghai Aladdin Biochemical Reagents','a total of 1.5 g (4.12 mmoL) of CTAB, 105 mL of ammonia solution (wt = 25%), and 150 mL of deionized water were added to the flask to be completely dissolved at 60 °C with 1 h of stirring','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9290,9477,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4309,4116,'ammonia solution','NH3','base',105.0,'mL',NULL,'wt = 25%','Tianjin Damao Chemical Reagents','a total of 1.5 g (4.12 mmoL) of CTAB, 105 mL of ammonia solution (wt = 25%), and 150 mL of deionized water were added to the flask to be completely dissolved at 60 °C with 1 h of stirring','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9290,9477,'Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China).');
INSERT INTO "reagents" VALUES(4310,4116,'deionized water (Sal-MCM synthesis)','H2O','solvent',150.0,'mL',NULL,NULL,NULL,'a total of 1.5 g (4.12 mmoL) of CTAB, 105 mL of ammonia solution (wt = 25%), and 150 mL of deionized water were added to the flask to be completely dissolved at 60 °C with 1 h of stirring','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9290,9477,NULL);
INSERT INTO "reagents" VALUES(4311,4116,'tetraethyl orthosilicate (TEOS)',NULL,'precursor',7.5,'g',NULL,'analytical grade','Shanghai Aladdin Biochemical Reagents','7.5 g (35.28 mmoL) of TEOS was added to the solution dropwise','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9485,9546,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4312,4116,'salicylaldimine',NULL,'ligand',2.5,'g',NULL,NULL,NULL,'After 1 h, 2.5 g of the as-synthesized salicylaldimine was added','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9548,9612,NULL);
INSERT INTO "reagents" VALUES(4313,4116,'ethanol (template removal)',NULL,'solvent',100.0,'mL',NULL,'analytical grade','Tianjin Damao Chemical Reagents','the template was removed with 100 mL ethanol at 110 °C for 72 h by the mean of reflux extraction to obtain Sal-MCM-41','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9751,9868,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4314,4116,'Sal-MCM-41',NULL,'substrate',500.0,'mg',NULL,NULL,NULL,'50 mL (100 mmoL) of zinc nitrate solution was added to 500 mg of Sal-MCM-41 or MCM-41 at 30 °C with stirring for 24 h','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10366,10483,NULL);
INSERT INTO "reagents" VALUES(4315,4116,'zinc nitrate solution','Zn(NO3)2','precursor',50.0,'mL',NULL,'analytical grade','Tianjin Damao Chemical Reagents','50 mL (100 mmoL) of zinc nitrate solution was added to 500 mg of Sal-MCM-41 or MCM-41 at 30 °C with stirring for 24 h','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10366,10483,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4316,4118,'MCM-41',NULL,'substrate',500.0,'mg',NULL,NULL,NULL,'50 mL (100 mmoL) of zinc nitrate solution was added to 500 mg of Sal-MCM-41 or MCM-41 at 30 °C with stirring for 24 h','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10366,10483,NULL);
