INSERT INTO "reagents" VALUES(4353,4129,'CVD h-BN film (15 nm) on 300 nm SiO2/Si','BN','substrate',15.0,'nm',NULL,NULL,NULL,'For the CVD graphene devices, a large-area CVD h-BN film was first transferred onto 300-nm-thick SiO2/Si wafers, followed by the transfer of large-area single-crystalline CVD-grown graphene (SCG) on the top of a 15-nm-thick h-BN film (Supplementary Fig. 14).','Device applications of multilayer h-BN',18186,18444,NULL);
