INSERT INTO "reagents" VALUES(4391,4142,'silicon powder','Si','precursor',NULL,NULL,NULL,'99.9985%','Alfa Aesar','Silicon powder (200 nm–2 μm in diameter, 99.9985% purity, Alfa Aesar, Ward Hill, MA) and carbon black powder (~50 nm in diameter, 99.9% purity, Alfa Aesar, Ward Hill, MA) were used as the starting materials.','Experimental Conditions',4780,4987,'Silicon powder (200 nm–2 μm in diameter, 99.9985% purity, Alfa Aesar, Ward Hill, MA) and carbon black powder (~50 nm in diameter, 99.9% purity, Alfa Aesar, Ward Hill, MA) were used as the starting materials.');
