INSERT INTO "reagents" VALUES(4548,4256,'nitric acid','HNO3','acid',100.0,'mL',NULL,'70%','Sigma-Aldrich','100 mL HNO3 (15 mol L-1) was prepared and added into a round bottom flask','Functionalization of carbon nanotubes',9590,9663,'Nitric acid (HNO3, 70%), copper (II) sulfate pentahydrate (CuSO4.5H2O), hexamethylenetetramine (HMTA, C6H12N4), zinc nitrate hexahydrate (Zn(NO3)2⋅6H2O), thioacetamide (CH3CSNH2), cetyltrimethylammonium bromide (CTAB, CH3(CH2)15 N(Br)(CH3)3), absolute ethanol (CH3CH2OH), hydrochloric acid solution (HCl, 37%), and sodium hydroxide (NaOH, pellets) were all purchased from Sigma-Aldrich without any impurities.');
