INSERT INTO "reagents" VALUES(4567,4260,'aluminum hydroxide (nordstrandite)','Al(OH)3','precursor',NULL,NULL,NULL,'analytical reagent grade','Xilong Reagent Co.','Initially, diatomite and Al(OH)3 were dispersed in NaOH solution under vigorous magnetic stirring to form a homogeneous dispersion.','2.2. Preparation of Zeolite X',5754,5885,'Sodium hydroxide, aluminum hydroxide (nordstrandite) and the other chemicals used in the experiments were purchased from Xilong Reagent Co. (Xilong, China). All chemicals were of analytical reagent grade and used without any further purification.');
