INSERT INTO "route_variations" VALUES(4944,4557,'graphene oxide dispersion (route GO)',NULL,NULL,'replaced by AGO powder (route AGO)',NULL,'graphene oxide dispersion (route GO)','The same procedure was carried out for AGO powder with the replacement of GO by AGO.','Synthesis of GO–CTS hydrogels',12744,12828,NULL);
INSERT INTO "steps" VALUES(4929,3951,1,'wash','Rinse fresh leaves with tap water then double distilled water to remove dust.','Fresh and healthy leaves were collected locally and rinsed thoroughly with tap water followed by doubled distilled water to remove all dust and unwanted visible particles','Preparation of the leaf extract',5140,5310);
INSERT INTO "steps" VALUES(4930,3951,2,'dry','Dry the rinsed leaves at room temperature to remove surface water.','after which they were dried at room temperature to remove the water from the surface of leaves, then cut into small pieces.','Preparation of the leaf extract',5312,5435);
INSERT INTO "steps" VALUES(4931,3951,3,'cut','Cut the dried leaves into small pieces.','after which they were dried at room temperature to remove the water from the surface of leaves, then cut into small pieces.','Preparation of the leaf extract',5312,5435);
INSERT INTO "steps" VALUES(4932,3951,4,'heat','Boil the leaf pieces in distilled water to prepare the extract.','Next, 10 g of these finely incised leaves were transferred into 250 ml beakers containing 100 ml distilled water and boiled at 80 °C for 20 min.','Preparation of the leaf extract',5436,5580);
INSERT INTO "steps" VALUES(4933,3951,5,'cool','Cool the extract at room temperature.','After cooling at room temperature, leaves were centrifuged at 12,000 rpm for 15 min at 4 °C and filtered through 0.45 μm PTFE filter.','Preparation of the leaf extract',5581,5714);
INSERT INTO "steps" VALUES(4934,3951,6,'centrifuge','Centrifuge the cooled extract.','After cooling at room temperature, leaves were centrifuged at 12,000 rpm for 15 min at 4 °C and filtered through 0.45 μm PTFE filter.','Preparation of the leaf extract',5581,5714);
INSERT INTO "steps" VALUES(4935,3951,7,'filter','Filter the supernatant through a PTFE filter.','After cooling at room temperature, leaves were centrifuged at 12,000 rpm for 15 min at 4 °C and filtered through 0.45 μm PTFE filter.','Preparation of the leaf extract',5581,5714);
INSERT INTO "steps" VALUES(4936,3951,8,'collect','Store the filtrate (leaf extract) before use as reducing and stabilizing agent.','The filtrates were then stored at 4–8 °C and used as reducing and stabilizing agents in the synthesis of AgNPs.','Preparation of the leaf extract',5715,5826);
INSERT INTO "steps" VALUES(4937,3951,9,'dissolve','Prepare a 1 mM aqueous silver nitrate solution.','Aqueous solution of 1 mM silver nitrate (AgNO3) was prepared in a 250 ml Erlenmeyer flask and used for the synthesis of AgNPs.','AgNPs synthesis',5898,6024);
INSERT INTO "steps" VALUES(4938,3951,10,'add','Add the leaf extract into the silver nitrate solution (extract added to AgNO3, not the reverse).','Briefly, 10 ml of Aloe vera leaf extract was added into 90 ml of aqueous solution of 1 mM silver nitrate and incubated in the dark overnight at room temperature.','AgNPs synthesis',6025,6186);
INSERT INTO "steps" VALUES(4939,3951,11,'age','Incubate the mixture in the dark at room temperature until the colour turns brownish yellow.','Briefly, 10 ml of Aloe vera leaf extract was added into 90 ml of aqueous solution of 1 mM silver nitrate and incubated in the dark overnight at room temperature.','AgNPs synthesis',6025,6186);
INSERT INTO "steps" VALUES(4940,3951,12,'collect','Seal the colloidal mixture and store it for later use.','The colloidal mixture was then sealed and stored properly for future use.','AgNPs synthesis',6310,6383);
INSERT INTO "steps" VALUES(4941,3952,1,'dissolve','Dissolve zinc nitrate hexahydrate and 2,6-pyridine dicarboxylic acid in double distilled water.','A mixture of zinc nitrate hexahydrate (0,120 mmol) and 2,6-pyridine dicarboxylic acid (0,120 mmol) is dissolved in 21 mL of double distilled water','Ultrasonic assisted reverse micelle method',7441,7587);
INSERT INTO "steps" VALUES(4942,3952,2,'add','Add the aqueous solution to the sodium dodecyl sulfate / hexane mixture to form the reverse micelle system.','The resulting solution was added to a mixture of 0.077 mmol of sodium dodecyl sulfate and 8 mL of hexane.','Ultrasonic assisted reverse micelle method',7652,7757);
INSERT INTO "steps" VALUES(4943,3952,3,'stir','Stir the resulting mixture at 85 °C for 1 h.','Then, the resulting mixture was stirred at temperature of 85 °C for 1 h.','Ultrasonic assisted reverse micelle method',7758,7830);
INSERT INTO "steps" VALUES(4944,3952,4,'react','Ultrasonic irradiation of the mixture under the conditions called optimum by the authors.','The resulting solution was put into the ultrasonic device and was placed under ultrasonic irradiation in optimum conditions including ultrasonic duration of 21 min, power of 175 W and ultrasonic temperature of 40 °C.','Ultrasonic assisted reverse micelle method',7831,8047);
INSERT INTO "steps" VALUES(4945,3952,5,'age','Wait 30 min, after which the Zn-MOF crystals are formed (starting point of the 30 min is not specified).','After 30 min, the Zn-MOF crystals are formed that are separated by centrifugation and washed by DMF.','Ultrasonic assisted reverse micelle method',8048,8148);
INSERT INTO "steps" VALUES(4946,3952,6,'centrifuge','Separate the Zn-MOF crystals by centrifugation.','separated by centrifugation','Ultrasonic assisted reverse micelle method',8102,8129);
INSERT INTO "steps" VALUES(4947,3952,7,'wash','Wash the crystals with DMF.','washed by DMF','Ultrasonic assisted reverse micelle method',8134,8147);
INSERT INTO "steps" VALUES(4948,3953,1,'mix','Add the aqueous enzyme solution and the aqueous zinc nitrate solution into the aqueous 2-methylimidazole solution.','HRP, CALB, Cyt c water solution (5 mg/mL, 4 mL), and Zn(NO3)2 water solution (92.5 mg/mL, 4 mL) were added into 2-methylimidazole water solution (4.1 g dissolved in 40 mL water)','Synthesis of the enzyme/ZIF-8 composite',5029,5206);
INSERT INTO "steps" VALUES(4949,3953,2,'stir','Stir the mixture at room temperature; it turns milky almost instantly.','followed by stirring for 30 min at room temperature','Synthesis of the enzyme/ZIF-8 composite',5208,5259);
INSERT INTO "steps" VALUES(4950,3953,3,'age','Age the milky suspension at room temperature.','After aged at room temperature for 12 h','Synthesis of the enzyme/ZIF-8 composite',5317,5356);
INSERT INTO "steps" VALUES(4951,3953,4,'centrifuge','Collect the product by centrifugation.','the product was collected by centrifugation at 6000 rpm for 10 min','Synthesis of the enzyme/ZIF-8 composite',5358,5424);
INSERT INTO "steps" VALUES(4952,3953,5,'wash','Wash the collected solid with deionized water (washing and centrifugation cycles, removing adsorbed protein).','washed with DI water for three times','Synthesis of the enzyme/ZIF-8 composite',5426,5462);
INSERT INTO "steps" VALUES(4953,3956,1,'mix','Physically mix the as-prepared pure ZIF-8 crystals with the enzyme solutions.','physically mixing the as-prepared pure ZIF-8 crystals with enzyme solutions to form the enzyme-adsorbed ZIF-8 samples','Results and discussion',10961,11078);
INSERT INTO "steps" VALUES(4954,3956,2,'wash','Wash the samples with the same washing step as for the embedded composites (DI water, three times, per the composite protocol; see doubts).','After the same washing step','Results and discussion',11080,11107);
INSERT INTO "steps" VALUES(4955,3957,1,'mix','Add aqueous solutions of CuCl2, HAuCl4 and glucose into a 20-ml glass vial already containing a mixture of HDA and water, at room temperature (Au/Cu molar ratio 1:1).','0.3 ml of aqueous CuCl2·2H2O (100 mM), 0.3 ml of aqueous HAuCl4·3H2O (100 mM), 45 mg of HDA, 0.28 ml of aqueous glucose (1 M) and 4 ml of water were added in a 20-ml vial at room temperature','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',32992,33182);
INSERT INTO "steps" VALUES(4956,3957,2,'stir','Cap the vial and stir magnetically at room temperature overnight.','After the vial had been capped, the solution was magnetically stirred at room temperature overnight.','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',33184,33284);
INSERT INTO "steps" VALUES(4957,3957,3,'heat','Transfer the capped vial into an oil bath and heat at 100 °C under magnetic stirring; the colour changes from kelly green to brown.','The capped vial was then transferred into an oil bath and heated at 100 °C for 30 min under magnetic stirring.','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',33285,33395);
INSERT INTO "steps" VALUES(4958,3957,4,'centrifuge','Centrifuge the product (described for preparing electron microscopy samples).','the pentacle nanocrystals were centrifugated at 10,000 r.p.m. for 8 min','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',33544,33615);
INSERT INTO "steps" VALUES(4959,3957,5,'wash','Wash with water three times and ethanol twice to remove excess precursor, HDA and glucose.','washed with water three times and ethanol twice to remove excess precursor, HDA and glucose','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',33620,33711);
INSERT INTO "steps" VALUES(4960,3975,1,'mix','Add aqueous CuCl2, aqueous HAuCl4, HDA, aqueous glucose and water into a 20-ml vial at room temperature.','0.3 ml of aqueous CuCl2·2H2O (100 mM), 0.3 ml of aqueous HAuCl4·3H2O (100 mM), 45 mg of HDA, 0.28 ml of aqueous glucose (1 M) and 4 ml of water were added in a 20-ml vial at room temperature. After the vial had been capped','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',32992,33214);
INSERT INTO "steps" VALUES(4961,3975,2,'stir','Stir magnetically at room temperature overnight.','the solution was magnetically stirred at room temperature overnight. The capped vial was then transferred into an oil bath and heated at 100 °C for 3 min.','Controlling the size of pentacle Au–Cu alloy nanocrystals',34228,34382);
INSERT INTO "steps" VALUES(4962,3975,3,'heat','Transfer the capped vial into an oil bath and heat at 100 °C for 3 min.','The capped vial was then transferred into an oil bath and heated at 100 °C for 3 min.','Controlling the size of pentacle Au–Cu alloy nanocrystals',34297,34382);
INSERT INTO "steps" VALUES(4963,3975,4,'add','Add 30 mg of additional HDA to the reaction solution at 100 °C.','Then 30 mg HDA was added into the reaction solution at 100 °C.','Controlling the size of pentacle Au–Cu alloy nanocrystals',34383,34445);
INSERT INTO "steps" VALUES(4964,3975,5,'cool','Stop the reaction and cool the solution with iced water when its colour changes from kelly green to brown.','The reaction was stopped and the solution was cooled down using iced water when its colour changed from kelly green to brown.','Controlling the size of pentacle Au–Cu alloy nanocrystals',34446,34571);
INSERT INTO "steps" VALUES(4965,3978,1,'coat','Coat the surface of the pentacle nanocrystals with a monolayer of PEG (no procedure given in the article).','The surface of pentacle nanocrystals was coated with a monolayer of polyethylene glycol (PEG)','Plasmonic properties and photothermal therapy (PTT)',24655,24748);
INSERT INTO "steps" VALUES(4966,3979,1,'dissolve','Dissolve l-cysteine in distilled water under magnetic stirring to obtain a colorless solution.','3 mmol l-cysteine was dissolved in 30 mL distilled water under magnetic stirring for 15 min to obtain a colorless solution','Material Synthesis',5115,5237);
INSERT INTO "steps" VALUES(4967,3979,2,'add','Pour distilled water and SbCl3 into the beaker under stirring to obtain a milky suspension.','30 mL distilled water and 2 mmol SbCl3 were systematically poured into the beaker under stirring for 35 min to produce a milky suspension liquid','Material Synthesis',5245,5389);
INSERT INTO "steps" VALUES(4968,3979,3,'heat','Hydrothermal treatment of the suspension in a Teflon-lined stainless-steel autoclave.','the above solution was transferred into an 80-mL Teflon-lined stainless-steel autoclave and then maintained at 150 °C for 12 h','Material Synthesis',5402,5528);
INSERT INTO "steps" VALUES(4969,3979,4,'wash','Collect the product and wash it with absolute ethyl alcohol and deionized water.','The Sb2S3 was gathered and washed several times with absolute ethyl alcohol and deionized water','Material Synthesis',5530,5625);
INSERT INTO "steps" VALUES(4970,3979,5,'dry','Dry the washed product in vacuum.','dried at 80 °C for 5 h in vacuum','Material Synthesis',5631,5663);
INSERT INTO "steps" VALUES(4971,3982,1,'mix','Mix CMC, acetylene black and the Sb2S3 active material in the mass ratio 1:1:3.','The work electrode was prepared by mixing the carboxymethyl cellulose Na salt (CMC), acetylene black, and active material in the mass ratio of 1:1:3','Electrochemical Measurements',5959,6107);
INSERT INTO "steps" VALUES(4972,3982,2,'add','Adjust the viscosity of the mixture with distilled water.','after which the viscosity was varied with distilled water and magnetic stirring overnight','Electrochemical Measurements',6109,6198);
INSERT INTO "steps" VALUES(4973,3982,3,'stir','Stir the slurry magnetically overnight.','after which the viscosity was varied with distilled water and magnetic stirring overnight','Electrochemical Measurements',6109,6198);
INSERT INTO "steps" VALUES(4974,3983,1,'assemble','Assemble the test cell from the working electrode, Celgard 2300 separator, lithium counter electrode and LiPF6 electrolyte, in an argon-filled glove box.','For LIBs, the testing batteries were assembled with the working electrode already prepared, and with Celgard 2300 film as the separator, lithium metal as the reference/counter electrode, and 1 M LiPF6 in dimethyl carbonate (DMC)/ethylene carbonate (EC) (1:1 v/v) as the electrolyte.','Electrochemical Measurements',6261,6543);
INSERT INTO "steps" VALUES(4975,3985,1,'add','Add CTAB to bi-distilled water in a flat-bottomed flask.','0.2 g of CTAB was added to 100 mL of bi-distilled (BD) water, in a flat-bottomed flask','Synthesis of thorn-like ZnO nanoparticles',4849,4935);
INSERT INTO "steps" VALUES(4976,3985,2,'add','Add the zinc acetate dihydrate solution to the CTAB solution.','To this, 10 mL of 1% Zn(CH3COO)2·2H2O solution was added.','Synthesis of thorn-like ZnO nanoparticles',4937,4994);
INSERT INTO "steps" VALUES(4977,3985,3,'stir','Place the apparatus on a mechanical stirrer at the chosen stirring speed (500 rpm for this sample).','The whole apparatus was kept on mechanical stirrer under different stirring conditions viz. 500 rpm, 1000 rpm, 1500 rpm and 2000 rpm.','Synthesis of thorn-like ZnO nanoparticles',4995,5128);
INSERT INTO "steps" VALUES(4978,3985,4,'add','Add the NaOH solution drop-wise; the colloidal solution turns milky within a few minutes of agitation.','Subsequently, the NaOH solution was added drop-wise to the cocktail.','Synthesis of thorn-like ZnO nanoparticles',5129,5197);
INSERT INTO "steps" VALUES(4979,3985,5,'react','Keep the setup as such for half an hour.','The setup was retained as such for half an hour.','Synthesis of thorn-like ZnO nanoparticles',5268,5316);
INSERT INTO "steps" VALUES(4980,3985,6,'cool','Cool the system.','The system was then cooled, centrifuged, dried at room temperature in a desiccator, and washed with BD water and methanol.','Synthesis of thorn-like ZnO nanoparticles',5317,5439);
INSERT INTO "steps" VALUES(4981,3985,7,'centrifuge','Centrifuge the cooled system to collect the solid.','The system was then cooled, centrifuged, dried at room temperature in a desiccator, and washed with BD water and methanol.','Synthesis of thorn-like ZnO nanoparticles',5317,5439);
INSERT INTO "steps" VALUES(4982,3985,8,'dry','Dry at room temperature in a desiccator.','The system was then cooled, centrifuged, dried at room temperature in a desiccator, and washed with BD water and methanol.','Synthesis of thorn-like ZnO nanoparticles',5317,5439);
INSERT INTO "steps" VALUES(4983,3985,9,'wash','Wash with bi-distilled water and methanol.','The system was then cooled, centrifuged, dried at room temperature in a desiccator, and washed with BD water and methanol.','Synthesis of thorn-like ZnO nanoparticles',5317,5439);
INSERT INTO "steps" VALUES(4984,3985,10,'store','Store the ZnO nanoparticles in an amber-coloured container until use.','Finally, the samples of ZnO-NPs were stored in amber colour container until further use.','Synthesis of thorn-like ZnO nanoparticles',5561,5649);
INSERT INTO "steps" VALUES(4985,3989,1,'mix','Mix methylammonium bromide and lead bromide in DMF in a glass vial.','0.16 mmol of methylammonium bromide (MABr) and 0.2 mmol of lead bromide (PbBr2) were mixed in 5 ml dimethylformamide (DMF) solution','Size-varied perovskite NC synthesis',30876,31007);
INSERT INTO "steps" VALUES(4986,3989,2,'add','Add oleylamine and oleic acid to the DMF solution to obtain the final precursor solution.','50 μl of oleylamine and 0.5 ml oleic acid were also mixed in the DMF solution to form the final precursor solution','Size-varied perovskite NC synthesis',31016,31130);
INSERT INTO "steps" VALUES(4987,3989,3,'heat','Preheat toluene in a round-bottom flask in an oil bath.','Another round-bottom flask containing 5 ml of toluene was preheated to 60 °C in an oil bath.','Size-varied perovskite NC synthesis',31132,31224);
INSERT INTO "steps" VALUES(4988,3989,4,'add','Swiftly inject the precursor solution into the hot toluene under vigorous stirring; the solution turns green.','Then 250 μl of as-prepared precursor solution was swiftly injected into hot toluene solution under vigorous stirring condition.','Size-varied perovskite NC synthesis',31225,31352);
INSERT INTO "steps" VALUES(4989,3989,5,'react','Let the reaction continue after injection.','The reaction was continued for another 5 min and stopped by cooling in a water bath.','Size-varied perovskite NC synthesis',31433,31517);
INSERT INTO "steps" VALUES(4990,3989,6,'cool','Stop the reaction by cooling in a water bath.','The reaction was continued for another 5 min and stopped by cooling in a water bath.','Size-varied perovskite NC synthesis',31433,31517);
INSERT INTO "steps" VALUES(4991,3989,7,'centrifuge','Centrifuge the reaction solution; the speed selects the NC size (8,000 r.p.m. for the medium NCs).','The reaction solution was transferred into a centrifuge tube and centrifuged at the desired speed for different sized spherical-shaped MAPbBr3 NCs.','Size-varied perovskite NC synthesis',31518,31665);
INSERT INTO "steps" VALUES(4992,3989,8,'dissolve','Re-dissolve the precipitate in toluene.','The precipitation of MAPbBr3 NCs was re-dissolved in toluene solution for further studies.','Size-varied perovskite NC synthesis',31666,31756);
INSERT INTO "steps" VALUES(4993,3992,1,'deposit','Spin-coat the 0.6 M MAPbBr3 solution in DMF on quartz substrates.','A solution containing 0.6 M MAPbBr3 in DMF was spin-coated (5,000 r.p.m., 12 s) on quartz substrates.','MAPbBr3 bulk-film fabrication',32063,32164);
INSERT INTO "steps" VALUES(4994,3992,2,'add','Add a few drops of toluene on the spinning film.','During spin-coating, few drops of toluene were added to the film at 3 s after the beginning of spinning.','MAPbBr3 bulk-film fabrication',32165,32269);
INSERT INTO "steps" VALUES(4995,3992,3,'dry','Dry the film at room temperature.','The film was then dried in room temperature for 30 min and annealed at 70 °C for 5 min.','MAPbBr3 bulk-film fabrication',32270,32357);
INSERT INTO "steps" VALUES(4996,3992,4,'anneal','Anneal the film.','The film was then dried in room temperature for 30 min and annealed at 70 °C for 5 min.','MAPbBr3 bulk-film fabrication',32270,32357);
INSERT INTO "steps" VALUES(4997,3994,1,'deposit','Spin-coat the NC solution on glass substrates, two layers.','To prepare the NC film, NCs in toluene (10 mg ml−1) was spin-coated on glass substrates for two layers.','MAPbBr3 NCs and EDT-NC film fabrications',32766,32869);
INSERT INTO "steps" VALUES(4998,3997,1,'deposit','Spin-coat the NC solution on top of the substrate.','(1) spin-coating of NC solution on top of substrate','MAPbBr3 NCs and EDT-NC film fabrications',32980,33031);
INSERT INTO "steps" VALUES(4999,3997,2,'add','Cover the NC film with 0.2 M EDT solution in 2-propanol, wait, then spin-coat.','(2) cover the NC film with 0.2 M EDT solution in 2-Propanol and wait for 30 s and then spin coat','MAPbBr3 NCs and EDT-NC film fabrications',33033,33129);
INSERT INTO "steps" VALUES(5000,3997,3,'wash','Drop anhydrous toluene on the film and spin-coat to remove the remaining long-chained ligands.','(3) dropping of anhydrous toluene on film and followed by spin-coating to clean the remaining long-chained ligands.','MAPbBr3 NCs and EDT-NC film fabrications',33131,33246);
INSERT INTO "steps" VALUES(5001,3997,4,'deposit','Repeat the three-step layer cycle to build up the film thickness.','The above process was repeated for two to ten times, to obtain the NC film with different thickness.','MAPbBr3 NCs and EDT-NC film fabrications',33247,33347);
INSERT INTO "steps" VALUES(5002,3999,1,'deposit','Spin-coat the NC solution on top of the substrate.','(1) spin-coating of NC solution on top of substrate','MAPbBr3 NCs and EDT-NC film fabrications',32980,33031);
INSERT INTO "steps" VALUES(5003,3999,2,'add','Cover the NC film with 0.2 M EDT solution in 2-propanol, wait, then spin-coat.','(2) cover the NC film with 0.2 M EDT solution in 2-Propanol and wait for 30 s and then spin coat','MAPbBr3 NCs and EDT-NC film fabrications',33033,33129);
INSERT INTO "steps" VALUES(5004,3999,3,'wash','Drop anhydrous toluene on the film and spin-coat to remove the remaining long-chained ligands.','(3) dropping of anhydrous toluene on film and followed by spin-coating to clean the remaining long-chained ligands.','MAPbBr3 NCs and EDT-NC film fabrications',33131,33246);
INSERT INTO "steps" VALUES(5005,3999,4,'deposit','Repeat the three-step layer cycle to build up the film thickness.','The above process was repeated for two to ten times, to obtain the NC film with different thickness.','MAPbBr3 NCs and EDT-NC film fabrications',33247,33347);
INSERT INTO "steps" VALUES(5006,3999,5,'anneal','Post-anneal the EDT-treated NC film.','For post-annealed samples, the annealing was performed at 70 °C for 5 min.','MAPbBr3 NCs and EDT-NC film fabrications',33348,33422);
INSERT INTO "steps" VALUES(5007,4000,1,'deposit','Thermal evaporation of Bphen on the NC films under vacuum.','Bphen was deposited on spin-coated non-annealed or annealed perovskites NCs films at a rate of 0.1–0.2 nm s−1.','Bphen thin-film fabrication',33622,33732);
INSERT INTO "steps" VALUES(5008,4001,1,'place','Place the MoCl5 powder at the center of the tube furnace and the sulfur powder at the upstream entry.','1–50 mg of molybdenum chloride (MoCl5) powder (99.99%, Sigma-Aldrich) was placed at the center of the furnace and 1 g of sulfur powder (Sigma-Aldrich) were placed at the upstream entry of the furnace','Methods',23251,23450);
INSERT INTO "steps" VALUES(5009,4001,2,'place','Place the receiving substrates downstream of the furnace center (sapphire for the reference monolayer).','Receiving substrates were placed downstream in a distance of 1–7 centimeters away from the center of the furnace.','Methods',23452,23565);
INSERT INTO "steps" VALUES(5010,4001,3,'heat','Heat the furnace under Ar flow to the growth temperature, hold, to grow the MoS2 film on the substrates.','In typical experiments, the furnace was heated up at a rate of 28°C/min under a flow of Ar gas, held at a setting temperature for 10 min','Methods',23566,23702);
INSERT INTO "steps" VALUES(5011,4001,4,'cool','Let the furnace cool down naturally to room temperature.','and then naturally cooled down to room temperature','Methods',23704,23754);
INSERT INTO "steps" VALUES(5012,4024,1,'transfer','Transfer the MoS2 film grown on sapphire to degenerately doped silicon substrates covered with a 280 nm SiO2 layer.','We transferred the thin film grown on sapphire to degenerately doped silicon substrates covered with 280-nm-thick SiO2','Results',13051,13169);
INSERT INTO "steps" VALUES(5013,4024,2,'place','Place a copper grid on top of the film as a mask for the electrodes.','A copper grid (100mesh, 30 micron spacing, Ted Pella) was placed on top of the thin film as mask for the electrode fabrication.','Methods',25048,25175);
INSERT INTO "steps" VALUES(5014,4024,3,'deposit','Evaporate Ti/Au electrodes on top of the MoS2 film.','The field-effect transistor device was fabricated by evaporating Ti/Au (5/200 nm) electrodes directly onto top of MoS2 films transferred to degenerately doped Si substrates with 280 nm thick silicon oxide.','Methods',24842,25047);
INSERT INTO "steps" VALUES(5015,4025,1,'react','Synthesis of the MSNs from TEOS and CTAB with DEA as base catalyst; the article gives no further operating details (renvoi to previous reports).','The same concentration of silica source (TEOS) and template (CTAB), but different DEA (0.2 and 0.6 vt%) created 20 and 40 nm MSNs, respectively.','Size-controlled synthesis and characterization of Ru@MSNs nanosystems',18521,18665);
INSERT INTO "steps" VALUES(5016,4027,1,'react','Synthesis of the MSNs from TEOS with TEA as base catalyst and CTAB as template; the article gives no further operating details (renvoi to previous reports).','For example under the same condition with 0.3 vt% TEA as base catalyst and 0.75 vt% TEOS as silica source, MSNs at 60 or 80 nm was obtained with 10 wt% CTAB or CTAC as templates, respectively.','Size-controlled synthesis and characterization of Ru@MSNs nanosystems',18072,18264);
INSERT INTO "steps" VALUES(5017,4029,1,'dissolve','Dissolve RuPOP in DMSO.','In detail, 20 mg of RuPOP was dissolved in 10 mL DMSO.','Synthesis of different-sized Ru@MSNs nanosystems',9361,9415);
INSERT INTO "steps" VALUES(5018,4029,2,'mix','Suspend the MSNs in the RuPOP solution and stir at room temperature (loading of RuPOP).','Then 50 mg of different-sized MSNs were suspended into the solution and stirred for 24 h at room temperature, respectively.','Synthesis of different-sized Ru@MSNs nanosystems',9416,9539);
INSERT INTO "steps" VALUES(5019,4029,3,'centrifuge','Collect the RuPOP-loaded nanoparticles by centrifugation.','The nanoparticles were obtained by centrifugation at 12,000 rpm for 10 min','Synthesis of different-sized Ru@MSNs nanosystems',9540,9614);
INSERT INTO "steps" VALUES(5020,4029,4,'mix','Mix the nanoparticles with a pre-prepared PEI-FA solution to coat them.','mixed with pre-prepared PEI-FA solution for 24 h','Synthesis of different-sized Ru@MSNs nanosystems',9619,9667);
INSERT INTO "steps" VALUES(5021,4029,5,'centrifuge','Collect the final Ru@MSNs by centrifugation.','Finally, different-sized Ru@MSNs was obtained by centrifugation and low-temperature vacuum drying.','Synthesis of different-sized Ru@MSNs nanosystems',9669,9767);
INSERT INTO "steps" VALUES(5022,4029,6,'dry','Dry the Ru@MSNs at low temperature under vacuum.','Finally, different-sized Ru@MSNs was obtained by centrifugation and low-temperature vacuum drying.','Synthesis of different-sized Ru@MSNs nanosystems',9669,9767);
INSERT INTO "steps" VALUES(5023,4032,1,'grind','Crush the as-received fennel seeds with a mixer grinder to obtain a fennel powder.','As received fennel seeds were crushed using a mixer grinder (Tiger mixer grinder, Japan).','Synthesis of C-QD',6423,6512);
INSERT INTO "steps" VALUES(5024,4032,2,'heat','Pyrolysis of the ground fennel powder (0.2 g) in a crucible cup on a heat plate at constant temperature.','Ground greenish fennel powder (0.2 g) was transferred to the crucible cup (AS ONE, Japan) and was heated using a heat plate (AS ONE, Japan) at a constant temperature of 500 °C for 3 hours.','Synthesis of C-QD',6513,6701);
INSERT INTO "steps" VALUES(5025,4032,3,'cool','Let the crucible cool down to room temperature; the powder has turned into a dark-gray carbonized product.','Subsequently, the crucible was allowed to cool down to room temperature.','Synthesis of C-QD',6702,6774);
INSERT INTO "steps" VALUES(5026,4032,4,'dissolve','Dissolve the dark-gray carbonized product in deionized water.','Carbonization of the greenish fennel powder turned into a dark-gray product, and it was dissolved in deionized water followed by the sonication for 5 minutes.','Synthesis of C-QD',6775,6933);
INSERT INTO "steps" VALUES(5027,4032,5,'sonicate','Sonicate the suspension after dissolution in deionized water.','it was dissolved in deionized water followed by the sonication for 5 minutes','Synthesis of C-QD',6856,6932);
INSERT INTO "steps" VALUES(5028,4032,6,'centrifuge','Centrifuge the black suspension to remove the large undissolved particles and keep the supernatant.','The black color suspension was centrifuged at 15000 rpm for 10 minutes to remove the large un-dissolved particles.','Synthesis of C-QD',6934,7048);
INSERT INTO "steps" VALUES(5029,4032,7,'filter','Filter the supernatant through a 100 nm pore size filter.','The supernatant was filtered using 100 nm pore size filter (PALL ACRO DISC, Japan)','Synthesis of C-QD',7049,7131);
INSERT INTO "steps" VALUES(5030,4032,8,'dialyze','Purify the filtered solution by dialysis.','subjected to the dialysis using dialysis kit (Float-A-Lyzer G2 Dialysis, Japan) for further purification','Synthesis of C-QD',7136,7240);
INSERT INTO "steps" VALUES(5031,4032,9,'collect','Transfer the purified C-QDs to a glass vial and store them for characterization.','The purified C-QDs was transferred to the glass vial and stored for further characterization.','Synthesis of C-QD',7242,7335);
INSERT INTO "steps" VALUES(5032,4037,1,'remove','Remove the cortical components of the bovine bone to keep the spongy bone.','spongy bone samples which were obtained after removal of the cortical components','2.1. Synthesis of Hydroxyapatite Particles',6695,6775);
INSERT INTO "steps" VALUES(5033,4037,2,'clean','Clean the bovine bone samples mechanically.','bovine bone samples were mechanically cleaned','2.1. Synthesis of Hydroxyapatite Particles',6870,6915);
INSERT INTO "steps" VALUES(5034,4037,3,'heat','Heat treatment to remove the organic components.','a heat treatment at 500 °C for one hour in order to remove organic components','2.1. Synthesis of Hydroxyapatite Particles',6929,7006);
INSERT INTO "steps" VALUES(5035,4037,4,'calcine','Proper thermal treatment of the cleaned bone at 1200 °C.','Proper thermal treatment was performed at 1200 °C for 6 h with a heating rate of 10 °C/min.','2.1. Synthesis of Hydroxyapatite Particles',7008,7099);
INSERT INTO "steps" VALUES(5036,4037,5,'cool','Cool the samples in air.','After cooling in the air','2.1. Synthesis of Hydroxyapatite Particles',7100,7124);
INSERT INTO "steps" VALUES(5037,4037,6,'grind','Grind the samples in an agate ball mill.','the samples were ground in an agate ball mill and then sieved','2.1. Synthesis of Hydroxyapatite Particles',7126,7187);
INSERT INTO "steps" VALUES(5038,4037,7,'sieve','Sieve the ground powder and keep the particles smaller than 40 µm.','hydroxyapatite particles with sizes smaller than 40 µm were used','2.1. Synthesis of Hydroxyapatite Particles',7212,7276);
INSERT INTO "steps" VALUES(5039,4038,1,'dissolve','Dissolve polylactic acid in chloroform to make a 12 wt.% solution.','Polylactic acid was dissolved in chloroform at a concentration of 12 wt.%.','2.2. Synthesis of PLA/HA Composite Films',7322,7396);
INSERT INTO "steps" VALUES(5040,4038,2,'mix','Disperse the hydroxyapatite particles (from route HA_bovine) in the polymer solution by ultrasonication.','The hydroxyapatite particles were dispersed by ultrasonication for 30 min into the polymer solution at three different concentrations (1, 2, and 4 wt.%, respectively) in order to obtain a homogenous solution.','2.2. Synthesis of PLA/HA Composite Films',7397,7605);
INSERT INTO "steps" VALUES(5041,4038,3,'deposit','Cast the mixture into a glass Petri dish.','casting the obtained mixture into a Petri glass 60 mm in diameter (LabBox, Barcelona, Spain)','2.2. Synthesis of PLA/HA Composite Films',7646,7738);
INSERT INTO "steps" VALUES(5042,4038,4,'evaporate','Evaporate the solvent in an oven to form the film.','evaporating the solvent at 40 °C for 72 h in an oven','2.2. Synthesis of PLA/HA Composite Films',7743,7795);
INSERT INTO "steps" VALUES(5043,4038,5,'wash','Wash the films with distilled water and ethanol to remove chloroform and polymer residues.','After synthesis, the composite films were washed with distilled water and ethanol to remove any chloroform and polymer residues and kept dry until use.','2.2. Synthesis of PLA/HA Composite Films',7948,8099);
INSERT INTO "steps" VALUES(5044,4038,6,'store','Keep the films dry until use.','kept dry until use','2.2. Synthesis of PLA/HA Composite Films',8080,8098);
INSERT INTO "steps" VALUES(5045,4042,1,'dissolve','Dissolve nickel acetate tetrahydrate and thioacetamide in water in a flat-bottomed beaker (Ni:S molar ratio 1:1).','we dissolved 2.49 g (= 0.01 mol) of Ni(CH3COO)2 ∙ 4H2O and 0.75 g (= 0.01 mol) of C2H5NS in 50 mL of water in a 100 mL flat-bottomed beaker','Experimental',6988,7127);
INSERT INTO "steps" VALUES(5046,4042,2,'sonicate','Sonicate the solution in ambient atmosphere with a direct immersion titanium horn at 70% amplitude; the green solution turns black.','The mixture was sonicated in an ambient atmosphere for 1 h using a Sonics and Materials VCX 600 sonicator (20 kHz, 1 cm2 Ti direct immersion horn) at different amplitudes, namely 30%, 50%, 70% and 90%.','Experimental',7129,7330);
INSERT INTO "steps" VALUES(5047,4042,3,'centrifuge','Centrifuge the black precipitate.','The black precipitate obtained after 1 h of sonication was centrifuged at 7000 RPM','Experimental',7444,7526);
INSERT INTO "steps" VALUES(5048,4042,4,'wash','Wash the precipitate twice with water and twice with absolute ethanol.','washed twice with water and twice with absolute ethanol','Experimental',7528,7583);
INSERT INTO "steps" VALUES(5049,4042,5,'dry','Air-dry the washed solid.','air-dried for 24 h','Experimental',7588,7606);
INSERT INTO "steps" VALUES(5050,4055,1,'dissolve','Dissolve cobalt acetate dihydrate and thioacetamide in water (Co:S molar ratio 1:1); the solution is red.','we dissolved 2.13 g (= 0.01 mol) of Co(CH3COO)2 ∙ 2H2O and 0.75 g (= 0.01 mol) of C2H5NS in 50 mL of water','Experimental',8320,8426);
INSERT INTO "steps" VALUES(5051,4055,2,'sonicate','Sonicate the solution at 70% amplitude; the red solution turns black after 5 min.','sonicated the solution for 1 h at 70% amplitude','Experimental',8431,8478);
INSERT INTO "steps" VALUES(5052,4055,3,'centrifuge','Centrifuge the black precipitate; the article only says it is handled as described above, so the speed is the one of the nickel procedure (see doubts).','The black precipitate obtained after 1 h of sonication was handled as described above.','Experimental',8537,8623);
INSERT INTO "steps" VALUES(5053,4055,4,'wash','Wash the precipitate twice with water and twice with absolute ethanol, as for the nickel sulfides (renvoi « as described above »).','The black precipitate obtained after 1 h of sonication was handled as described above.','Experimental',8537,8623);
INSERT INTO "steps" VALUES(5054,4055,5,'dry','Air-dry the washed solid for 24 h, as for the nickel sulfides (renvoi « as described above »).','The black precipitate obtained after 1 h of sonication was handled as described above.','Experimental',8537,8623);
INSERT INTO "steps" VALUES(5055,4055,6,'heat','Heat the amorphous sonochemical product at 500 °C to obtain nanocrystalline cobalt sulfide.','nanocrystalline products were obtained by heating the precursors obtained by the sonochemical reaction for 2 h at 500 °C','Cobalt sulfides',19336,19456);
INSERT INTO "steps" VALUES(5056,4061,1,'dissolve','Dissolve zinc acetate and CTAB in distilled water under constant stirring.','1 g of zinc acetate (Zn(Ac)2 2H2O) and 2g cetyltrimethylammonium bromide (CTAB, C19H42BrN) were dissolved in 60 mL distilled water under constant stirring','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',19773,19927);
INSERT INTO "steps" VALUES(5057,4061,2,'adjust_ph','Gradually introduce 5 mol/L NaOH solution until the pH reaches 13.','5 mol/L NaOH solution was gradually introduced to the mentioned solution until pH reached at 13','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',19937,20032);
INSERT INTO "steps" VALUES(5058,4061,3,'add','Add a certain amount of SDS so that the CTAB:SDS molar ratio takes the tested value (1:0 for this sample, i.e. no SDS).','certain amount of sodium dodecyl sulfate (SDS, C12H25SO4Na) was added to the solution as molar ratio of CATB: SDS equaled to 1:0, 1:0.2, 1:0.36, 1:0.5, 1:1 and 1:1.5','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20040,20205);
INSERT INTO "steps" VALUES(5059,4061,4,'heat','Hydrothermal growth in a Teflon-lined stainless steel autoclave.','solution with white flocculent precipitate was transferred into a teflon-lined stainless steel autoclave 50 mL and hydrothermal growth was carried out at 120 °C for 18 h','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20216,20385);
INSERT INTO "steps" VALUES(5060,4061,5,'cool','Let the autoclaves cool down after treatment.','After treatment, the autoclaves were allowed to cool down','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20387,20444);
INSERT INTO "steps" VALUES(5061,4061,6,'centrifuge','Collect the white precipitates and centrifuge them; discard the supernatant.','the white precipitates were collected, centrifuged at 40,000 (× g) for 10 min and supernatant was discarded','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20449,20556);
INSERT INTO "steps" VALUES(5062,4061,7,'wash','Wash the particles with ethanol and distilled water to remove impurities.','The obtained particles were washed three times with ethanol and distilled water','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20558,20637);
INSERT INTO "steps" VALUES(5063,4061,8,'dry','Dry the washed particles.','dried at 60 °C for 24 h','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20673,20696);
INSERT INTO "steps" VALUES(5064,4069,1,'add','Add zinc acetate and NaOH to distilled water and stir the solution.','Firstly 1 g zinc acetate (Zn(Ac)2 2H2O) and 1.12 g NaOH were added in 25 mL distilled water and the solution was stirred.','3.2.2. Synthesis of ZnO Using SDS (Constant) and CTAB (Variant)',20765,20886);
INSERT INTO "steps" VALUES(5065,4069,2,'stir','Keep stirring the solution before adding SDS.','After 1 h, 0.1 g SDS was added to the solution.','3.2.2. Synthesis of ZnO Using SDS (Constant) and CTAB (Variant)',20887,20934);
INSERT INTO "steps" VALUES(5066,4069,3,'add','Add SDS to the solution.','After 1 h, 0.1 g SDS was added to the solution.','3.2.2. Synthesis of ZnO Using SDS (Constant) and CTAB (Variant)',20887,20934);
INSERT INTO "steps" VALUES(5067,4069,4,'add','Add a certain amount of CTAB so that the SDS:CTAB molar ratio takes the tested value (1:0 for this sample, i.e. no CTAB).','certain amount of CTAB was added to above solution so that the molar ratio of SDS:CTAB was set to 1:0, 1:0.5, 1:1, 1:1.5 and 1:2','3.2.2. Synthesis of ZnO Using SDS (Constant) and CTAB (Variant)',20941,21069);
INSERT INTO "steps" VALUES(5068,4069,5,'heat','Hydrothermal growth in a Teflon-lined stainless steel autoclave (rest of the process same as in the CTAB-constant synthesis).','solution with white flocculent precipitate was transferred into a teflon-lined stainless steel autoclave 50 mL and hydrothermal growth was carried out at 120 °C for 18 h','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20216,20385);
INSERT INTO "steps" VALUES(5069,4069,6,'cool','Let the autoclaves cool down after treatment.','After treatment, the autoclaves were allowed to cool down','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20387,20444);
INSERT INTO "steps" VALUES(5070,4069,7,'centrifuge','Collect the white precipitates and centrifuge them; discard the supernatant.','the white precipitates were collected, centrifuged at 40,000 (× g) for 10 min and supernatant was discarded','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20449,20556);
INSERT INTO "steps" VALUES(5071,4069,8,'wash','Wash the particles with ethanol and distilled water to remove impurities.','The obtained particles were washed three times with ethanol and distilled water','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20558,20637);
INSERT INTO "steps" VALUES(5072,4069,9,'dry','Dry the washed particles.','dried at 60 °C for 24 h','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20673,20696);
INSERT INTO "steps" VALUES(5073,4070,1,'calcine','Calcine the as-synthesised ZnO-SDS powder at 500 °C.','The as-synthesised ZnO-SDS nanoparticles calcined at 500 °C shows no significant difference compared with that of the uncalcined one.','2.2. Morphology',5730,5863);
INSERT INTO "steps" VALUES(5074,4077,1,'calcine','Calcine the as-produced ZnO powder at 500 °C for 5 h.','FTIR spectra of as-produced ZnO samples at different mole ratios of (A) SDS:CTAB = 1:0.5 and (B) CTAB:SDS = 1:1 before and after the calcinations at 500 °C for 5 h.','Figure captions',26302,26466);
INSERT INTO "steps" VALUES(5075,4078,1,'calcine','Calcine the as-produced ZnO powder at 500 °C for 5 h.','FTIR spectra of as-produced ZnO samples at different mole ratios of (A) SDS:CTAB = 1:0.5 and (B) CTAB:SDS = 1:1 before and after the calcinations at 500 °C for 5 h.','Figure captions',26302,26466);
INSERT INTO "steps" VALUES(5076,4079,1,'degas','Degas formamidinium acetate, oleic acid and 1-octadecene in a three-necked flask under vacuum, first at room temperature then at 50 °C.','In a three-necked round-bottom flask, 15 mmol (1.563 g) of FA-acetate, 15 mL of OA, and 15 mL of ODE were degassed under a vacuum at room temperature and 50 °C for 30 min, respectively.','Synthesis of FA-Oleate Precursor',23814,23999);
INSERT INTO "steps" VALUES(5077,4079,2,'heat','Heat the FA-acetate / oleic acid / 1-octadecene mixture under N2 to form the FA-oleate stock solution and hold it at that temperature.','The temperature was then increased to 120 °C under N2 and kept at this temperature.','Synthesis of FA-Oleate Precursor',24000,24083);
INSERT INTO "steps" VALUES(5078,4079,3,'degas','Degas PbBr2 and 1-octadecene in a three-necked flask under vacuum, first at room temperature then at 120 °C.','In a three-necked round-bottom flask, 0.74 mmol (0.272 g) of PbBr2 and 25 mL of 1-ODE were degassed under vacuum at room temperature and 120 °C for 30 min, respectively.','Synthesis of FAPbBr3 NCs',24112,24281);
INSERT INTO "steps" VALUES(5079,4079,4,'add','Inject the preheated oleic acid and amine-ligand mixture (given ratio of (R)-2-octylamine to oleylamine) into the PbBr2 mixture under vacuum until the PbBr2 is dissolved and the solution is clear.','Mixtures of 12.1 mmol (4 mL) of OA and 6.05 mmol of amine ligands with different ratios of (R)-2-octylamine to OAm (1:0, 0.5:0.5, 0.25:0.75, 0:1) were preheated to 120 °C, then injected into the PbBr2 mixture under vacuum.','Synthesis of FAPbBr3 NCs',24282,24504);
INSERT INTO "steps" VALUES(5080,4079,5,'cool','Lower the temperature of the clear PbBr2 solution before injection to avoid rapid crystal growth.','Then the temperature of the solution was reduced to 80 °C to prevent rapid growth of FAPbBr3 crystals.','Synthesis of FAPbBr3 NCs',24565,24667);
INSERT INTO "steps" VALUES(5081,4079,6,'add','Swiftly inject the FA-oleate stock solution into the PbBr2 mixture under N2 flow (hot injection).','Under N2 flow, 5 mL of the FA-oleate stock solution was swiftly injected into the PbBr2 mixture, which was then quenched by immersing the flask in an ice bath.','Synthesis of FAPbBr3 NCs',24668,24827);
INSERT INTO "steps" VALUES(5082,4079,7,'quench','Quench the reaction by immersing the flask in an ice bath.','which was then quenched by immersing the flask in an ice bath.','Synthesis of FAPbBr3 NCs',24765,24827);
INSERT INTO "steps" VALUES(5083,4079,8,'centrifuge','Centrifuge the cooled solution to remove unreacted ligands and 1-octadecene.','After cooling to room temperature, the solution was centrifuged at 7500 rpm for 5 min to remove unreacted ligands and 1-ODE.','Synthesis of FAPbBr3 NCs',24828,24952);
INSERT INTO "steps" VALUES(5084,4079,9,'centrifuge','Disperse the precipitate in hexane and centrifuge again to remove the large precipitated particles.','The precipitate was dispersed in 5 mL of hexane, then centrifuged at 7500 rpm for 5 min to remove the precipitated large particles.','Synthesis of FAPbBr3 NCs',24953,25084);
INSERT INTO "steps" VALUES(5085,4079,10,'collect','Keep the supernatant NC solution in a refrigerator.','The supernatant NC solution was stored in a refrigerator.','Synthesis of FAPbBr3 NCs',25085,25142);
INSERT INTO "steps" VALUES(5086,4083,1,'mix','Place methylbenzylamine and ethanol in a flask in an ice bath.','In a one-necked round-bottom flask in an ice bath, 78 mmol (10 mL) of R-,S-MBA and 30 mL of ethanol were added','Synthesis of R-,S-MBA:Br',25171,25281);
INSERT INTO "steps" VALUES(5087,4083,2,'add','Add aqueous HBr dropwise under vigorous stirring.','then 116 mmol (13.2 mL) of HBr aqueous solution was added dropwise into the flask under vigorous stirring.','Synthesis of R-,S-MBA:Br',25283,25389);
INSERT INTO "steps" VALUES(5088,4083,3,'stir','Keep the solution stirring in the ice bath overnight.','The solution was kept stirring in an ice bath overnight.','Synthesis of R-,S-MBA:Br',25390,25446);
INSERT INTO "steps" VALUES(5089,4083,4,'collect','Collect the yellowish precipitate by evaporating the solvents.','The yellowish precipitate was collected by evaporation of solvents at 70 °C for 30 min','Synthesis of R-,S-MBA:Br',25447,25533);
INSERT INTO "steps" VALUES(5090,4083,5,'wash','Wash by repeated redissolution in ethanol and recrystallisation in diethyl ether until the solid is colorless.','then washed thoroughly by repeated redissolution in ethanol and recrystallization in diethyl ether until colorless.','Synthesis of R-,S-MBA:Br',25535,25650);
INSERT INTO "steps" VALUES(5091,4083,6,'recrystallize','Dissolve the white precipitate in a little hot ethanol to make a saturated solution and recrystallise it in a freezer.','The white precipitate was dissolved in a small amount of hot ethanol to make a saturated solution, then recrystallized in a freezer','Synthesis of R-,S-MBA:Br',25651,25782);
INSERT INTO "steps" VALUES(5092,4083,7,'dry','Dry the recrystallised product under vacuum.','The recrystallized precipitate was dried under vacuum overnight.','Synthesis of R-,S-MBA:Br',25897,25961);
INSERT INTO "steps" VALUES(5093,4084,1,'add','Add methyl acetate (antisolvent) to the NC stock solution.','To purify the FAPbBr3 NCs, 10 mL of MeOAc was added to 5 mL of a stock solution; then it was centrifuged at 7500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26014,26141);
INSERT INTO "steps" VALUES(5094,4084,2,'centrifuge','Centrifuge the MeOAc / NC mixture and keep the precipitate.','To purify the FAPbBr3 NCs, 10 mL of MeOAc was added to 5 mL of a stock solution; then it was centrifuged at 7500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26014,26141);
INSERT INTO "steps" VALUES(5095,4084,3,'centrifuge','Redisperse the precipitate in hexane and centrifuge again to discard aggregated particles.','The resulting precipitate was redispersed in 5 mL of hexane and centrifuged again at 7500 rpm for 5 min to discard the aggregated particles.','Purification and Ligand Treatment of FAPbBr3 NCs',26142,26282);
INSERT INTO "steps" VALUES(5096,4085,1,'add','Add methyl acetate (antisolvent) to the NC stock solution.','To purify the FAPbBr3 NCs, 10 mL of MeOAc was added to 5 mL of a stock solution; then it was centrifuged at 7500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26014,26141);
INSERT INTO "steps" VALUES(5097,4085,2,'centrifuge','Centrifuge the MeOAc / NC mixture and keep the precipitate.','To purify the FAPbBr3 NCs, 10 mL of MeOAc was added to 5 mL of a stock solution; then it was centrifuged at 7500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26014,26141);
INSERT INTO "steps" VALUES(5098,4085,3,'centrifuge','Redisperse the precipitate in hexane and centrifuge again to discard aggregated particles.','The resulting precipitate was redispersed in 5 mL of hexane and centrifuged again at 7500 rpm for 5 min to discard the aggregated particles.','Purification and Ligand Treatment of FAPbBr3 NCs',26142,26282);
INSERT INTO "steps" VALUES(5099,4085,4,'sonicate','Prepare a saturated solution of the chiral ligand in ethyl acetate by sonication.','a saturated solution of R-,S-MBA:Br in EtOAc was prepared by sonicating 200 mg of R-,S-MBA:Br in 20 mL of EtOAc','Purification and Ligand Treatment of FAPbBr3 NCs',26331,26442);
INSERT INTO "steps" VALUES(5100,4085,5,'centrifuge','Centrifuge the sonicated suspension to remove undissolved solid.','a saturated solution of R-,S-MBA:Br in EtOAc was prepared by sonicating 200 mg of R-,S-MBA:Br in 20 mL of EtOAc, then centrifuging at 3500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26331,26484);
INSERT INTO "steps" VALUES(5101,4085,6,'mix','Mix the saturated ligand solution with the purified NCs and stir mildly at room temperature.','The 1 mL of saturated R-,S-MBA:Br solution was mixed with 5 mL of purified FAPbBr3 NCs; the mixture was stirred mildly for 5 min at room temperature','Purification and Ligand Treatment of FAPbBr3 NCs',26485,26633);
INSERT INTO "steps" VALUES(5102,4085,7,'centrifuge','Centrifuge to precipitate aggregated particles and collect the supernatant (treated NCs).','the mixture was stirred mildly for 5 min at room temperature and then centrifuged at 7500 rpm for 5 min to precipitate the aggregated particles; the supernatant was collected.','Purification and Ligand Treatment of FAPbBr3 NCs',26573,26748);
INSERT INTO "steps" VALUES(5103,4087,1,'dissolve','Dissolve cobalt nitrate hexahydrate and lithium nitrate in deionized water at a Li:Co molar ratio of 1.05:1.','The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',8850,9070);
INSERT INTO "steps" VALUES(5104,4087,2,'atomize','Atomize the precursor solution into fine aerosol droplets with a quartz nebulizer.','A quartz nebulizer atomized the precursor solutions into fine aerosol droplets, subsequently vaporized in a stainless steel preheating section.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9712,9855);
INSERT INTO "steps" VALUES(5105,4087,3,'heat','Vaporize the droplets in the stainless steel preheating section under a nitrogen flow.','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067);
INSERT INTO "steps" VALUES(5106,4087,4,'react','Pyrolysis of the dried droplets in the heated section of a quartz tube furnace; the temperature is the set point, which is the peak of a parabolic axial furnace profile.','Postvaporization, the dried droplets were directed into a tube furnace (quartz tube).','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10298,10383);
INSERT INTO "steps" VALUES(5107,4087,5,'quench','Quench the decomposed particles with an air flow.','The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878);
INSERT INTO "steps" VALUES(5108,4087,6,'collect','Collect the particles in a filter bag fitted with a HEPA filter at the end of the housing.','before collecting them in a filter bag','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10839,10877);
INSERT INTO "steps" VALUES(5109,4087,7,'anneal','Anneal about 2 g of collected particles in an alumina crucible inside a second tube furnace under airflow, at 775 °C for 1 h.','For the purpose of achieving a higher crystalline layered structure, the collected particles (approximately 2 g) with promising structure and morphology were annealed in an alumina crucible.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10996,11186);
INSERT INTO "steps" VALUES(5110,4094,1,'dissolve','Dissolve cobalt nitrate hexahydrate and lithium nitrate in deionized water at a Li:Co molar ratio of 1.05:1.','The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',8850,9070);
INSERT INTO "steps" VALUES(5111,4094,2,'atomize','Atomize the precursor solution into fine aerosol droplets with a quartz nebulizer.','A quartz nebulizer atomized the precursor solutions into fine aerosol droplets, subsequently vaporized in a stainless steel preheating section.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9712,9855);
INSERT INTO "steps" VALUES(5112,4094,3,'heat','Vaporize the droplets in the stainless steel preheating section under a nitrogen flow.','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067);
INSERT INTO "steps" VALUES(5113,4094,4,'react','Pyrolysis of the dried droplets in the heated section of a quartz tube furnace; the temperature is the set point, which is the peak of a parabolic axial furnace profile.','Postvaporization, the dried droplets were directed into a tube furnace (quartz tube).','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10298,10383);
INSERT INTO "steps" VALUES(5114,4094,5,'quench','Quench the decomposed particles with an air flow.','The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878);
INSERT INTO "steps" VALUES(5115,4094,6,'collect','Collect the as-synthesized particles in a filter bag fitted with a HEPA filter at the end of the housing; no annealing.','before collecting them in a filter bag','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10839,10877);
INSERT INTO "steps" VALUES(5116,4102,1,'dissolve','Dissolve cobalt(II) acetate tetrahydrate and lithium acetate dihydrate in deionized water, with the same metal ratio, concentration and lithium excess as the nitrate solution.','In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9214,9503);
INSERT INTO "steps" VALUES(5117,4102,2,'atomize','Atomize the precursor solution into fine aerosol droplets with a quartz nebulizer.','A quartz nebulizer atomized the precursor solutions into fine aerosol droplets, subsequently vaporized in a stainless steel preheating section.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9712,9855);
INSERT INTO "steps" VALUES(5118,4102,3,'heat','Vaporize the droplets in the stainless steel preheating section under a nitrogen flow.','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067);
INSERT INTO "steps" VALUES(5119,4102,4,'react','Pyrolysis of the dried droplets in the heated section of a quartz tube furnace; the temperature is the set point, which is the peak of a parabolic axial furnace profile.','Postvaporization, the dried droplets were directed into a tube furnace (quartz tube).','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10298,10383);
INSERT INTO "steps" VALUES(5120,4102,5,'quench','Quench the decomposed particles with an air flow.','The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878);
INSERT INTO "steps" VALUES(5121,4102,6,'collect','Collect the particles in a filter bag fitted with a HEPA filter at the end of the housing.','before collecting them in a filter bag','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10839,10877);
INSERT INTO "steps" VALUES(5122,4102,7,'anneal','Anneal about 2 g of collected particles in an alumina crucible inside a second tube furnace under airflow, at 750 °C for 3 h.','For the purpose of achieving a higher crystalline layered structure, the collected particles (approximately 2 g) with promising structure and morphology were annealed in an alumina crucible.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10996,11186);
INSERT INTO "steps" VALUES(5123,4107,1,'dissolve','Dissolve cobalt(II) acetate tetrahydrate and lithium acetate dihydrate in deionized water, with the same metal ratio, concentration and lithium excess as the nitrate solution.','In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9214,9503);
INSERT INTO "steps" VALUES(5124,4107,2,'atomize','Atomize the precursor solution into fine aerosol droplets with a quartz nebulizer.','A quartz nebulizer atomized the precursor solutions into fine aerosol droplets, subsequently vaporized in a stainless steel preheating section.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9712,9855);
INSERT INTO "steps" VALUES(5125,4107,3,'heat','Vaporize the droplets in the stainless steel preheating section under a nitrogen flow.','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067);
INSERT INTO "steps" VALUES(5126,4107,4,'react','Pyrolysis of the dried droplets in the heated section of a quartz tube furnace; the temperature is the set point, which is the peak of a parabolic axial furnace profile.','Postvaporization, the dried droplets were directed into a tube furnace (quartz tube).','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10298,10383);
INSERT INTO "steps" VALUES(5127,4107,5,'quench','Quench the decomposed particles with an air flow.','The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878);
INSERT INTO "steps" VALUES(5128,4107,6,'collect','Collect the as-synthesized particles in a filter bag fitted with a HEPA filter at the end of the housing; no annealing.','before collecting them in a filter bag','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10839,10877);
INSERT INTO "steps" VALUES(5129,4114,1,'dissolve','Dissolve the PVDF in NMP to adjust the viscosity of the slurry.','PVDF was dissolved in N-methyl-2-pyrrolidone (NMP) to fine-tune the slurry’s viscosity, ensuring optimal electrode coating quality.','Coin Cell Assembly and Electrochemical Tests',11658,11789);
INSERT INTO "steps" VALUES(5130,4114,2,'mix','Blend the active material, Super-P and PVDF solution (weight ratio 90:5:5) in a Thinky mixer at 2000 rpm.','The mixture was blended at 2000 rpm in a Thinky mixer','Coin Cell Assembly and Electrochemical Tests',11790,11843);
INSERT INTO "steps" VALUES(5131,4114,3,'deposit','Cast the slurry onto aluminum foil with a linear coater.','cast onto aluminum foil using a linear coater set to a 150 μm gap','Coin Cell Assembly and Electrochemical Tests',11845,11910);
INSERT INTO "steps" VALUES(5132,4114,4,'dry','Dry the cast electrode film at 120 °C for 30 min.','and dried at 120 °C for 30 min','Coin Cell Assembly and Electrochemical Tests',11912,11942);
INSERT INTO "steps" VALUES(5133,4114,5,'cut','Shape the electrode into 13 mm discs.','The electrodes, shaped into 13 mm discs, were dried overnight in a vacuum oven at the same temperature.','Coin Cell Assembly and Electrochemical Tests',11944,12047);
INSERT INTO "steps" VALUES(5134,4114,6,'dry','Dry the electrode discs overnight in a vacuum oven, at the same temperature as the first drying.','The electrodes, shaped into 13 mm discs, were dried overnight in a vacuum oven at the same temperature.','Coin Cell Assembly and Electrochemical Tests',11944,12047);
INSERT INTO "steps" VALUES(5135,4114,7,'assemble','Assemble CR2032 coin cells in an argon-filled glovebox with a Li metal disc, a Celgard separator and LP40 electrolyte.','CR2032 coin cells were assembled in an argon-filled glovebox, each containing a 15 mm Li metal disc counter electrode, a 19 mm diameter Celgard separator, and filled with 20 μL of LP40 electrolyte (1 M LiPF6 in EC/DEC, 1:1 v/v).','Coin Cell Assembly and Electrochemical Tests',12048,12276);
INSERT INTO "steps" VALUES(5136,4114,8,'crimp','Crimp the coin cells at 1000 psi.','Cells were crimped at 1000 psi and underwent electrochemical testing','Coin Cell Assembly and Electrochemical Tests',12277,12345);
INSERT INTO "steps" VALUES(5137,4115,1,'mix','Mix the acetate-derived LCO, Super P and PVDF (80:10:10) into a slurry.','This slurry was mixed, cast, dried, and calendared to enhance the electrode’s structural integrity and ensure effective electrolyte infiltration.','Coin Cell Assembly and Electrochemical Tests',12667,12812);
INSERT INTO "steps" VALUES(5138,4115,2,'deposit','Cast the slurry.','This slurry was mixed, cast, dried, and calendared to enhance the electrode’s structural integrity and ensure effective electrolyte infiltration.','Coin Cell Assembly and Electrochemical Tests',12667,12812);
INSERT INTO "steps" VALUES(5139,4115,3,'dry','Dry the cast electrode.','This slurry was mixed, cast, dried, and calendared to enhance the electrode’s structural integrity and ensure effective electrolyte infiltration.','Coin Cell Assembly and Electrochemical Tests',12667,12812);
INSERT INTO "steps" VALUES(5140,4115,4,'calender','Calender the dried electrode to improve its structural integrity and electrolyte infiltration.','This slurry was mixed, cast, dried, and calendared to enhance the electrode’s structural integrity and ensure effective electrolyte infiltration.','Coin Cell Assembly and Electrochemical Tests',12667,12812);
INSERT INTO "steps" VALUES(5141,4115,5,'cut','Punch the processed electrodes into 14 mm discs.','The processed electrodes were punched into 14 mm discs','Coin Cell Assembly and Electrochemical Tests',12813,12867);
INSERT INTO "steps" VALUES(5142,4115,6,'assemble','Assemble 2032-type coin cells with an 18 mm Celgard separator and 80 μL of electrolyte.','The processed electrodes were punched into 14 mm discs and assembled into 2032-type coin cells, incorporating an 18 mm Celgard separator and 80 μL of 1.3 M LiPF6 electrolyte in EC:DEC (3:7 wt/wt), tailored for the electrode’s specific needs.','Coin Cell Assembly and Electrochemical Tests',12813,13054);
INSERT INTO "steps" VALUES(5143,4115,7,'crimp','Crimp the coin cells at 700 psi.','Crimped at 700 psi, the cells were conditioned for 8 h before being subjected to formation cycling at 0.1C, stability tests at 0.5C, and rate capability assessments ranging from 0.5C to 20C.','Coin Cell Assembly and Electrochemical Tests',13055,13245);
INSERT INTO "steps" VALUES(5144,4115,8,'age','Condition the crimped cells for 8 h before the electrochemical tests.','Crimped at 700 psi, the cells were conditioned for 8 h before being subjected to formation cycling at 0.1C, stability tests at 0.5C, and rate capability assessments ranging from 0.5C to 20C.','Coin Cell Assembly and Electrochemical Tests',13055,13245);
INSERT INTO "steps" VALUES(5145,4116,1,'react','Synthesis of salicylaldimine: APTES, salicylaldehyde and ethanol reacted in a flask.','8.85 g (39.98 mmoL) of APTES, 4.88 g (39.96 mmoL) of salicylaldehyde, and 100 mL of ethanol were added to a flask and reacted at 95 °C for 3 h','2.2.1. Preparation of Salicylaldimine',8251,8393);
INSERT INTO "steps" VALUES(5146,4116,2,'evaporate','Remove ethanol by rotary evaporation.','After removing ethanol with rotary evaporation','2.2.1. Preparation of Salicylaldimine',8395,8441);
INSERT INTO "steps" VALUES(5147,4116,3,'dissolve','Dissolve the intermediate product in dichloromethane.','the intermediate products were dissolved in 10 mL (156.01 mmoL) of dichloromethane','2.2.1. Preparation of Salicylaldimine',8443,8525);
INSERT INTO "steps" VALUES(5148,4116,4,'wash','Wash the product with deionized water.','the product was washed with deionized water three times','2.2.1. Preparation of Salicylaldimine',8533,8588);
INSERT INTO "steps" VALUES(5149,4116,5,'age','Leave the mixture to stand.','After being left to stand for 12 h','2.2.1. Preparation of Salicylaldimine',8590,8624);
INSERT INTO "steps" VALUES(5150,4116,6,'extract','Extract the organic layer.','the organic layer was extracted','2.2.1. Preparation of Salicylaldimine',8626,8657);
INSERT INTO "steps" VALUES(5151,4116,7,'dry','Remove residual water with anhydrous magnesium sulfate.','0.5 g (4.15 mmoL) anhydrous magnesium sulfate was used to remove the residual water','2.2.1. Preparation of Salicylaldimine',8663,8746);
INSERT INTO "steps" VALUES(5152,4116,8,'filter','Filter off magnesium sulfate and dichloromethane to obtain salicylaldimine.','the final product was filtered to remove dichloromethane and magnesium sulfate to obtain salicylaldimine','2.2.1. Preparation of Salicylaldimine',8757,8861);
INSERT INTO "steps" VALUES(5153,4116,9,'dissolve','Dissolve CTAB, ammonia solution and deionized water in the flask with stirring.','a total of 1.5 g (4.12 mmoL) of CTAB, 105 mL of ammonia solution (wt = 25%), and 150 mL of deionized water were added to the flask to be completely dissolved at 60 °C with 1 h of stirring','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9290,9477);
INSERT INTO "steps" VALUES(5154,4116,10,'add','Add TEOS dropwise to the solution.','7.5 g (35.28 mmoL) of TEOS was added to the solution dropwise','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9485,9546);
INSERT INTO "steps" VALUES(5155,4116,11,'add','One hour after the TEOS addition, add the as-synthesized salicylaldimine.','After 1 h, 2.5 g of the as-synthesized salicylaldimine was added','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9548,9612);
INSERT INTO "steps" VALUES(5156,4116,12,'stir','Stir the reaction mixture for a further period.','the reaction was stirred for another 6 h','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9618,9658);
INSERT INTO "steps" VALUES(5157,4116,13,'age','Crystallization of the mixture.','being crystallized for 24 h at 30 °C','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9666,9702);
INSERT INTO "steps" VALUES(5158,4116,14,'filter','Filter the solid.','filtered, washed, and dried at 80 °C','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9704,9740);
INSERT INTO "steps" VALUES(5159,4116,15,'wash','Wash the solid (washing solvent not stated).','filtered, washed, and dried at 80 °C','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9704,9740);
INSERT INTO "steps" VALUES(5160,4116,16,'dry','Dry the solid at 80 °C.','filtered, washed, and dried at 80 °C','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9704,9740);
INSERT INTO "steps" VALUES(5161,4116,17,'reflux','Remove the CTAB template by reflux extraction with ethanol to obtain Sal-MCM-41.','the template was removed with 100 mL ethanol at 110 °C for 72 h by the mean of reflux extraction to obtain Sal-MCM-41','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9751,9868);
INSERT INTO "steps" VALUES(5162,4116,18,'impregnate','Wet impregnation of Sal-MCM-41 with the zinc nitrate solution under stirring.','50 mL (100 mmoL) of zinc nitrate solution was added to 500 mg of Sal-MCM-41 or MCM-41 at 30 °C with stirring for 24 h','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10366,10483);
INSERT INTO "steps" VALUES(5163,4116,19,'filter','Filter the Zn-loaded solid to obtain Zn/Sal-MCM-41.','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5164,4116,20,'wash','Wash the Zn-loaded solid (conditions not stated).','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5165,4116,21,'dry','Dry the Zn-loaded solid (conditions not stated).','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5166,4116,22,'calcine','Calcination in air converting Zn ions to ZnO and removing the salicylaldimine.','following calcination at 550 °C for 6 h in air, ZnO-MCM was obtained','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10582,10650);
INSERT INTO "steps" VALUES(5167,4118,1,'prepare','Preparation of MCM-41, the mesoporous silica without salicylaldimine modification: the article gives no procedure, reagents, quantities, temperatures or durations for this sample.','Additionally, mesoporous silica without salicylaldimine modification was synthesized and noted as MCM-41.','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',10068,10173);
INSERT INTO "steps" VALUES(5168,4118,2,'impregnate','Wet impregnation of MCM-41 with the zinc nitrate solution under stirring.','50 mL (100 mmoL) of zinc nitrate solution was added to 500 mg of Sal-MCM-41 or MCM-41 at 30 °C with stirring for 24 h','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10366,10483);
INSERT INTO "steps" VALUES(5169,4118,3,'filter','Filter the Zn-loaded solid to obtain Zn/MCM-41.','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5170,4118,4,'wash','Wash the Zn-loaded solid (conditions not stated).','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5171,4118,5,'dry','Dry the Zn-loaded solid (conditions not stated).','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5172,4118,6,'calcine','Calcination in air converting Zn ions to ZnO.','following calcination at 550 °C for 6 h in air, ZnO-MCM was obtained','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10582,10650);
INSERT INTO "steps" VALUES(5173,4119,1,'anneal','Anneal the Fe foil under hydrogen to smoothen its surface before growth.','the Fe foil (Alfa Aesar) was annealed at 1,100 °C for 1 h to smoothen the Fe surface under a 10 s.c.c.m. hydrogen atmosphere','Synthesis of multi- and monolayer materials',27642,27766);
INSERT INTO "steps" VALUES(5174,4119,2,'deposit','Grow h-BN by supplying borazine vapour and hydrogen over the Fe foil.','borazine vapour and hydrogen with a rate of 0.1 and 10 s.c.c.m., respectively, were supplied at 1,100 °C for 30 min','Synthesis of multi- and monolayer materials',27785,27900);
INSERT INTO "steps" VALUES(5175,4119,3,'cool','Cool slowly down to 700 °C without supplying additional borazine, so that dissolved B and N segregate and precipitate at the surface.','different cooling rates (slow: 5 °C min−1, fast: 30 °C min−1) until 700 °C were applied','Synthesis of multi- and monolayer materials',27921,28008);
INSERT INTO "steps" VALUES(5176,4121,1,'anneal','Anneal the Cu foil under hydrogen.','copper foil (Alfa Aesar) was annealed at 1,040 °C for 30 min under a 10 s.c.c.m. hydrogen atmosphere','Synthesis of multi- and monolayer materials',28146,28246);
INSERT INTO "steps" VALUES(5177,4121,2,'deposit','First growth step with low methane flow to reduce the nucleation density.','then methane and hydrogen with a rate of 0.1 and 10 s.c.c.m., respectively, for 20 min was supplied to reduce the nucleation density','Synthesis of multi- and monolayer materials',28251,28383);
INSERT INTO "steps" VALUES(5178,4121,3,'deposit','Second growth step with higher methane flow to form a continuous graphene film.','followed by increasing the methane flow rate to 2 s.c.c.m. while maintaining the same flow rate of hydrogen to form a continuous graphene film','Synthesis of multi- and monolayer materials',28385,28527);
INSERT INTO "steps" VALUES(5179,4122,1,'deposit','CVD growth of monolayer MoS2 on a SiO2/Si substrate.','The growth of monolayers MoS2 and WSe2 was conducted at 750 °C for 10 min on a SiO2/Si substrate, respectively.','Synthesis of multi- and monolayer materials',28638,28749);
INSERT INTO "steps" VALUES(5180,4123,1,'deposit','CVD growth of monolayer WSe2 on a SiO2/Si substrate.','The growth of monolayers MoS2 and WSe2 was conducted at 750 °C for 10 min on a SiO2/Si substrate, respectively.','Synthesis of multi- and monolayer materials',28638,28749);
INSERT INTO "steps" VALUES(5181,4124,1,'spin_coat','Spin coat the h-BN/Fe sample with PMMA.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5182,4124,2,'dry','Dry the PMMA-coated sample in an oven.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5183,4124,3,'immerse','Immerse PMMA/h-BN/Fe in aqueous NaOH, the Fe foil acting as cathode.','The PMMA/h-BN/Fe was immersed in an aqueous solution of 0.1 M NaOH and used as a cathode.','Transfer of multi- and monolayer materials',29211,29300);
INSERT INTO "steps" VALUES(5184,4124,4,'delaminate','Delaminate PMMA/h-BN from the Fe foil by applying a voltage of 2 V.','PMMA/h-BN was delaminated from the Fe foil by applying a voltage of 2 V.','Transfer of multi- and monolayer materials',29301,29373);
INSERT INTO "steps" VALUES(5185,4124,5,'wash','Rinse the PMMA/h-BN film with distilled water.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5186,4124,6,'deposit','Transfer the film onto the target substrate.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5187,4124,7,'wash','Remove the PMMA with acetone.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5188,4124,8,'anneal','Anneal the transferred film under forming gas to remove PMMA residues.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5189,4125,1,'spin_coat','Spin coat the MoS2 (or WSe2)/SiO2 sample with PMMA.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5190,4125,2,'dry','Dry the PMMA-coated sample in an oven.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5191,4125,3,'immerse','Immerse PMMA/MoS2 (or WSe2)/SiO2 in 0.1 M KOH to detach the PMMA/MoS2 (or WSe2) film from the SiO2 substrate.','The PMMA/MoS2 (or WSe2)/SiO2 was immersed in 0.1 M KOH to detach the PMMA/MoS2 (or WSe2) film from the SiO2 substrate.','Transfer of multi- and monolayer materials',29374,29492);
INSERT INTO "steps" VALUES(5192,4125,4,'wash','Rinse the PMMA/h-BN film with distilled water.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5193,4125,5,'deposit','Transfer the film onto the target substrate.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5194,4125,6,'wash','Remove the PMMA with acetone.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5195,4125,7,'anneal','Anneal the transferred film under forming gas to remove PMMA residues.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5196,4126,1,'spin_coat','Spin coat the graphene/Cu sample with PMMA.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5197,4126,2,'dry','Dry the PMMA-coated sample in an oven.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5198,4126,3,'etch','Etch the Cu foil away with a copper etchant (wet-etching transfer).','For graphene, the conventional wet-etching transfer was used. Cu was etched by a copper etchant.','Transfer of multi- and monolayer materials',29493,29589);
INSERT INTO "steps" VALUES(5199,4126,4,'wash','Rinse the PMMA/h-BN film with distilled water.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5200,4126,5,'deposit','Transfer the film onto the target substrate.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5201,4126,6,'wash','Remove the PMMA with acetone.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5202,4126,7,'anneal','Anneal the transferred film under forming gas to remove PMMA residues.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5203,4127,1,'deposit','Pattern the Ti/Pt bottom electrodes by electron-beam lithography and lift-off on the SiO2 wafer.','First, non-oxidizing metal electrodes (10 nm Ti/20 nm Pt) were patterned by lift-off using electron-beam lithography onto a 1-μm thick thermally grown silicon dioxide wafer.','Device fabrication and analysis',30145,30318);
INSERT INTO "steps" VALUES(5204,4127,2,'deposit','Transfer the CVD h-BN film on top of the bottom electrodes as gate dielectric (standard transfer procedure).','Then CVD h-BN was transferred on-top as the gate dielectric following a standard transfer procedure and the second metal electrode (50 nm Pd) was deposited on-top forming a cross-bar structure.','Device fabrication and analysis',30319,30512);
INSERT INTO "steps" VALUES(5205,4127,3,'deposit','Deposit the 50 nm Pd top electrode to form a cross-bar structure (1 × 1 μm2 overlap for the breakdown devices).','Then CVD h-BN was transferred on-top as the gate dielectric following a standard transfer procedure and the second metal electrode (50 nm Pd) was deposited on-top forming a cross-bar structure.','Device fabrication and analysis',30319,30512);
INSERT INTO "steps" VALUES(5206,4129,1,'deposit','Transfer the large-area CVD h-BN film onto 300-nm-thick SiO2/Si wafers (see hBN_transfer_PMMA).','a large-area CVD h-BN film was first transferred onto 300-nm-thick SiO2/Si wafers','Device applications of multilayer h-BN',18216,18297);
INSERT INTO "steps" VALUES(5207,4129,2,'deposit','Transfer the single-crystalline CVD graphene onto the h-BN film (wet-etching transfer, see graphene_transfer_PMMA_Cu_etch).','For the CVD graphene devices, a large-area CVD h-BN film was first transferred onto 300-nm-thick SiO2/Si wafers, followed by the transfer of large-area single-crystalline CVD-grown graphene (SCG) on the top of a 15-nm-thick h-BN film (Supplementary Fig. 14).','Device applications of multilayer h-BN',18186,18444);
INSERT INTO "steps" VALUES(5208,4129,3,'deposit','Pattern Ti/Au ohmic contacts by e-beam lithography, electron-beam evaporation and lift-off.','Ohmic contacts (electron beam evaporated—1 nm Ti/30 nm Au) were patterned first using e-beam lithography and lift-off.','Device fabrication and analysis',30928,31046);
INSERT INTO "steps" VALUES(5209,4129,4,'etch','Isolate the graphene channel by oxygen plasma etching through a PMMA mask.','Electrical isolation was achieved using PMMA as a etch mask utilizing a reactive oxygen etching tool (Plasma-therm—50 W for 10 s).','Device fabrication and analysis',31047,31177);
INSERT INTO "steps" VALUES(5210,4132,1,'deposit','Transfer the CVD h-BN film onto the SiO2/Si substrate first (see hBN_transfer_PMMA).','For a graphene, MoS2 or WSe2 FET device, the h-BN film was first transferred, followed by transferring graphene, MoS2 or WSe2 on the h-BN substrate.','Transfer of multi- and monolayer materials',29854,30002);
INSERT INTO "steps" VALUES(5211,4132,2,'deposit','Transfer the monolayer MoS2 film onto the h-BN/SiO2/Si substrate (see MoS2_WSe2_transfer_PMMA_KOH).','For the MoS2 FET, after the MoS2 film was transferred to the h-BN/SiO2/Si substrate, the channel and electrode regime were defined using electron-beam lithography','Device fabrication and analysis',31178,31340);
INSERT INTO "steps" VALUES(5212,4132,3,'etch','Define the channel by electron-beam lithography and reactive ion etching with SF6.','plasma etching (reactive ion etching (RIE): SF6 10 s.c.c.m., 20 W, 10 s)','Device fabrication and analysis',31342,31414);
INSERT INTO "steps" VALUES(5213,4132,4,'deposit','Vacuum metallization with Pd/Au and lift-off to form the two-terminal FET.','vacuum metallization (Pd/Au, 10/30 nm and a lift-off process, to fabricate two-terminal FET','Device fabrication and analysis',31416,31507);
INSERT INTO "steps" VALUES(5214,4132,5,'anneal','Anneal the devices in vacuum to improve the electrode contact and remove oxygen-related groups from the MoS2 surface.','The devices were annealed at 150 °C for 2 h in 10−6 torr to improve the contact between the electrodes and MoS2, and also to remove any oxygen-related functional groups on the MoS2 surface.','Device fabrication and analysis',31509,31698);
INSERT INTO "steps" VALUES(5215,4136,1,'dissolve','Dissolve β-glucan in deionized water in a two-neck round-bottom flask at 65 °C, under stirring and nitrogen, with potassium persulfate as initiator.','The biopolymeric nanocomposites were prepared by dissolving 2 g β-glucan (BG) in deionized-water and transferred into round bottom two-neck flask heated at 65 °C with constant stirring under an inert nitrogen atmosphere with addition of 0.05 g potassium persulfate as initiator.','2.2. Bioactive Nanocomposite Scaffold Fabrication',7302,7580);
INSERT INTO "steps" VALUES(5216,4136,2,'add','Add acrylic acid (monomer) and the N,N''-methylene-bis-acrylamide crosslinker to the reaction medium.','After 30 min, 0.40 mL of AAc as monomer and N, N-MBA crosslinker (0.05 % of AAc) were added into reaction media.','2.2. Bioactive Nanocomposite Scaffold Fabrication',7581,7693);
INSERT INTO "steps" VALUES(5217,4136,3,'add','Add n-HAp powder gradually to the reaction medium.','After 45 min, (2.5 g) n-HAp powder was added gradually with continuous stirring for 3 h.','2.2. Bioactive Nanocomposite Scaffold Fabrication',7694,7782);
INSERT INTO "steps" VALUES(5218,4136,4,'stir','Stir continuously for 3 h (graft polymerization of AAc on β-glucan, HAp trapped in the polymer network).','After 45 min, (2.5 g) n-HAp powder was added gradually with continuous stirring for 3 h.','2.2. Bioactive Nanocomposite Scaffold Fabrication',7694,7782);
INSERT INTO "steps" VALUES(5219,4136,5,'cool','Remove N2 gas from the reaction medium and let it cool at ambient temperature.','N2 gas was removed from the reaction media, followed by cooling at ambient.','2.2. Bioactive Nanocomposite Scaffold Fabrication',7977,8052);
INSERT INTO "steps" VALUES(5220,4136,6,'filter','Filter the reaction suspension under vacuum to remove unreacted reactants.','The reaction suspension was filtered under vacuum to remove unreacted reactants and washed with deionized water later it dried at 55 °C overnight in the oven.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8053,8211);
INSERT INTO "steps" VALUES(5221,4136,7,'wash','Wash the filtered powder with deionized water.','The reaction suspension was filtered under vacuum to remove unreacted reactants and washed with deionized water later it dried at 55 °C overnight in the oven.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8053,8211);
INSERT INTO "steps" VALUES(5222,4136,8,'dry','Dry the washed powder in an oven overnight.','The reaction suspension was filtered under vacuum to remove unreacted reactants and washed with deionized water later it dried at 55 °C overnight in the oven.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8053,8211);
INSERT INTO "steps" VALUES(5223,4136,9,'mix','Homogenize the nanocomposite powder in deionized water to form a slurry.','The bioactive nanocomposite powder (5 g) was homogenized into deionized-water (10 mL) to form slurry.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8316,8417);
INSERT INTO "steps" VALUES(5224,4136,10,'freeze','Fill the slurry into cylindrical molds and keep it frozen.','Then slurry was filled into cylindrical molds (2 cm × 6 cm) and kept at −40 °C for 24 h.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8418,8506);
INSERT INTO "steps" VALUES(5225,4136,11,'freeze_dry','Obtain the porous scaffolds by freeze drying.','The porous bioactive nanocomposite scaffolds were obtained by and freeze drying method.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8507,8594);
INSERT INTO "steps" VALUES(5226,4136,12,'treat','Treat the scaffolds with aqueous NaOH, left at ambient.','The bioactive scaffolds were washed with deionized water after treating with 10 wt. % NaOHaq. The solution was kept at ambient for 5 min.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',8831,8968);
INSERT INTO "steps" VALUES(5227,4136,13,'wash','Wash the NaOH-treated scaffolds with deionized water.','The bioactive scaffolds were washed with deionized water after treating with 10 wt. % NaOHaq.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',8831,8924);
INSERT INTO "steps" VALUES(5228,4136,14,'dissolve','Prepare the silver nitrate solution; the concentration is the parameter varied between BNS1 to BNS4.','Initially, different concentrations of silver nitrate (AgNO3) solution was prepared from 0.15 to 0.60 M.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',8969,9073);
INSERT INTO "steps" VALUES(5229,4136,15,'add','Add aqua ammonia dropwise to the AgNO3 solution.','Dropwise aqua ammonia (25 wt. %) was added into AgNO3 solutions.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9074,9138);
INSERT INTO "steps" VALUES(5230,4136,16,'stir','Stir until a clear [Ag(NH3)2]+ solution is obtained.','It was stirred to obtain a clear [Ag(NH3)2]+ solution.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9139,9193);
INSERT INTO "steps" VALUES(5231,4136,17,'deposit','Dip the scaffolds into the [Ag(NH3)2]+ solution; the dip and drying cycle is repeated.','Then, scaffolds were dipped into the [Ag(NH3)2]+ solution for 20 s and oven-dried for 5 min at 100 °C.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9194,9296);
INSERT INTO "steps" VALUES(5232,4136,18,'dry','Oven-dry the scaffolds after each dipping.','Then, scaffolds were dipped into the [Ag(NH3)2]+ solution for 20 s and oven-dried for 5 min at 100 °C.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9194,9296);
INSERT INTO "steps" VALUES(5233,4136,19,'wash','Wash the Ag-coated scaffolds (solvent not specified).','Finally, Ag-coated bioactive nanocomposite scaffolds (BNS) were washed and dried as shown in the Figure 1.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9371,9477);
INSERT INTO "steps" VALUES(5234,4136,20,'dry','Dry the Ag-coated scaffolds (conditions not specified).','Finally, Ag-coated bioactive nanocomposite scaffolds (BNS) were washed and dried as shown in the Figure 1.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9371,9477);
INSERT INTO "steps" VALUES(5235,4140,1,'collect','Separate the oil from the walnut.','The oil was separated from walnut','Synthesis of Carbon Dots',4973,5006);
INSERT INTO "steps" VALUES(5236,4140,2,'filter','Pass the oil through Whatman filter paper to remove large particles.','passed through Whatman filter paper to eliminate large particles.','Synthesis of Carbon Dots',5011,5076);
INSERT INTO "steps" VALUES(5237,4140,3,'centrifuge','Centrifuge the filtered oil several times to clarify it.','The oil was then centrifuged for 15 min at 6000 rpm for five times.','Synthesis of Carbon Dots',5077,5144);
INSERT INTO "steps" VALUES(5238,4140,4,'heat','Hydrothermal treatment of the clear walnut oil in a Teflon-lined stainless steel autoclave heated in an oven.','Then, 30 ml of the clear walnut oil was transferred into a 100 mL Teflon-lined stainless steel laboratory autoclave and heated in an oven at temperature of 220°C for 24 h, and cooled to room temperature.','Synthesis of Carbon Dots',5145,5348);
INSERT INTO "steps" VALUES(5239,4140,5,'cool','Let the autoclave cool to room temperature.','and cooled to room temperature','Synthesis of Carbon Dots',5317,5347);
INSERT INTO "steps" VALUES(5240,4140,6,'centrifuge','Centrifuge the brownish solution to remove large or agglomerated particles and keep the supernatant containing the CQDs.','The brownish solution was centrifuged at 14000 rpm for 15 min for three times to remove large or agglomerated particles','Synthesis of Carbon Dots',5349,5468);
INSERT INTO "steps" VALUES(5241,4140,7,'filter','Purify the supernatant containing the CQDs through a membrane.','the supernatant containing CQDs was further purified using a 0.2 µm membrane','Synthesis of Carbon Dots',5473,5549);
INSERT INTO "steps" VALUES(5242,4141,1,'react','Culture of the Ganoderma neo-japonicum Imazeki KUM61076 mycelia on potato dextrose agar.','The mycelia were cultured on potato dextrose agar and incubated at 28°C ± 2°C for 7 days.','Culturing and maintenance of Ganoderma neo-japonicum',10147,10236);
INSERT INTO "steps" VALUES(5243,4141,2,'react','Transfer of the mycelia into glucose yeast malt peptone broth, incubation under agitation.','The inoculated medium was incubated at 28°C ± 2°C and agitated at 150 rpm for 10 days.','Culturing and maintenance of Ganoderma neo-japonicum',10308,10394);
INSERT INTO "steps" VALUES(5244,4141,3,'wash','Harvest the mycelia and wash them with distilled water.','After incubation, the mycelia were harvested and washed with distilled water.','Culturing and maintenance of Ganoderma neo-japonicum',10395,10472);
INSERT INTO "steps" VALUES(5245,4141,4,'dry','Freeze-dry the mycelia and store them at 4°C in air-tight containers.','The mycelia were freeze-dried and stored at 4°C in air-tight containers prior to use.','Culturing and maintenance of Ganoderma neo-japonicum',10473,10558);
INSERT INTO "steps" VALUES(5246,4141,5,'heat','Soak the freeze-dried mycelia in distilled water (ratio 1:20) and double-boil.','the freeze-dried mycelia were soaked in distilled water at a ratio of 1:20 and double-boiled for 30 minutes','Preparation of mycelia hot aqueous extract',10708,10815);
INSERT INTO "steps" VALUES(5247,4141,6,'cool','Leave the double-boiled mixture to cool.','left to cool and filtered through grade 4 Whatman filter paper','Preparation of mycelia hot aqueous extract',10817,10879);
INSERT INTO "steps" VALUES(5248,4141,7,'filter','Filter the cooled mixture through grade 4 Whatman filter paper.','left to cool and filtered through grade 4 Whatman filter paper','Preparation of mycelia hot aqueous extract',10817,10879);
INSERT INTO "steps" VALUES(5249,4141,8,'dry','Freeze-dry the hot aqueous extract and store it at 4°C in airtight containers.','The hot aqueous extract was then freeze-dried at −50°C ± 2°C for 48 hours and stored at 4°C in airtight containers.','Preparation of mycelia hot aqueous extract',10881,10996);
INSERT INTO "steps" VALUES(5250,4141,9,'mix','Mix the freeze-dried extract (1 mg/mL) with the aqueous 1 mM AgNO3 solution.','1 mg/mL of freeze-dried hot aqueous mushroom mycelia extract was mixed with an aqueous solution of 1 mM AgNO3 solution and kept at room temperature for 24 hours.','Synthesis of AgNPs',11250,11411);
INSERT INTO "steps" VALUES(5251,4141,10,'age','Keep the mixture at room temperature to reduce Ag+ to Ag0.','1 mg/mL of freeze-dried hot aqueous mushroom mycelia extract was mixed with an aqueous solution of 1 mM AgNO3 solution and kept at room temperature for 24 hours.','Synthesis of AgNPs',11250,11411);
INSERT INTO "steps" VALUES(5252,4142,1,'load','Place the silicon powder upstream and the carbon black powder downstream in an alumina boat, with a Si:C molar ratio of about 1:1.','The silicon powder was placed in the upstream and the carbon black powder in the downstream of an alumina boat (100 × 20 × 20 mm) with a silicon and carbon molar ratio of about 1:1.','Experimental Conditions',4988,5169);
INSERT INTO "steps" VALUES(5253,4142,2,'place','Put the boat in the center of the horizontal alumina tube of the furnace.','The alumina boat was then placed in the center of the reaction chamber (horizontal alumina tube).','Experimental Conditions',5170,5267);
INSERT INTO "steps" VALUES(5254,4142,3,'evacuate','Evacuate the chamber with a rotary vacuum pump before heating.','Before heating, the chamber was first evacuated to ~10 mTorr by a rotary vacuum pump.','Experimental Conditions',5268,5353);
INSERT INTO "steps" VALUES(5255,4142,4,'adjust','Bring the chamber to the working pressure with ultra pure argon and keep a continuous argon flow during the whole process.','Then, the chamber pressure was adjusted to the desired pressure level with ultra pure argon (Ar) gas (99.999%, Airgas, Radnor, PA).','Experimental Conditions',5354,5485);
INSERT INTO "steps" VALUES(5256,4142,5,'heat','Ramp the furnace from room temperature to the reaction temperature.','After that, the chamber was ramped from room temperature to 1,500°C (center position temperature) at a rate of 10°C/min','Experimental Conditions',5486,5605);
INSERT INTO "steps" VALUES(5257,4142,6,'react','Hold the chamber at the reaction temperature for the reaction duration.','and was maintained at this temperature for desired reaction duration','Experimental Conditions',5606,5674);
INSERT INTO "steps" VALUES(5258,4142,7,'cool','Cool the chamber back to room temperature.','Finally, the chamber was cooled down to room temperature at 10°C/min rate.','Experimental Conditions',5676,5750);
INSERT INTO "steps" VALUES(5259,4142,8,'collect','Collect the grey powder found in the carbon black section of the boat.','After the reaction, grey colored powder was found in the carbon black powder section of the alumina boat.','Experimental Conditions',5870,5975);
INSERT INTO "steps" VALUES(5260,4154,1,'dissolve','Dissolve zinc acetate dihydrate in DMF.','0.5268 g of Zinc acetate dihydrate (C4H6O4Zn·2H2O, AR, Sinopharm) was dissolved in 3 ml N, N-dimethylformamide (DMF, AR, Sinopharm).','Preparation of ZnSe@N-CNFs',5500,5632);
INSERT INTO "steps" VALUES(5261,4154,2,'dissolve','Dissolve PAN in DMF under magnetic stirring at 60 °C.','0.4534 g polyacrylonitrile (PAN, Mw 150000, Macklin) was dissolved in 3 ml DMF under magnetic stirring for 30 min at 60°C.','Preparation of ZnSe@N-CNFs',5633,5755);
INSERT INTO "steps" VALUES(5262,4154,3,'mix','Mix the two solutions and stir further.','The two solutions were mixed and stirred for another 12 h.','Preparation of ZnSe@N-CNFs',5756,5814);
INSERT INTO "steps" VALUES(5263,4154,4,'deposit','Electrospin the mixture from a syringe to obtain nanofibers.','Then the mixture was transferred into a syringe to electrospin with the distance 20 cm and voltage 13 kV, respectively.','Preparation of ZnSe@N-CNFs',5815,5934);
INSERT INTO "steps" VALUES(5264,4154,5,'calcine','Mix the nanofibers with selenium powder and calcine in a tube furnace under vacuum (selenization).','The obtained nanofibers were mixed with 1.3 g Selenium powder (99.9%, Aladdin) and calcined at 650°C for 2 h (a ramp rate of 10°C min−1) in a tube furnace under vacuum to produce the ZnSe@N-CNFs.','Preparation of ZnSe@N-CNFs',5935,6130);
INSERT INTO "steps" VALUES(5265,4156,1,'dissolve','Dissolve zinc acetate dihydrate in DMF (solution de précurseur, préparée comme pour ZnSe@N-CNFs).','0.5268 g of Zinc acetate dihydrate (C4H6O4Zn·2H2O, AR, Sinopharm) was dissolved in 3 ml N, N-dimethylformamide (DMF, AR, Sinopharm).','Preparation of ZnSe@N-CNFs',5500,5632);
INSERT INTO "steps" VALUES(5266,4156,2,'dissolve','Dissolve PAN in DMF under magnetic stirring at 60 °C (comme pour ZnSe@N-CNFs).','0.4534 g polyacrylonitrile (PAN, Mw 150000, Macklin) was dissolved in 3 ml DMF under magnetic stirring for 30 min at 60°C.','Preparation of ZnSe@N-CNFs',5633,5755);
INSERT INTO "steps" VALUES(5267,4156,3,'mix','Mix the two solutions and stir further (comme pour ZnSe@N-CNFs) to give the precursor solution.','The two solutions were mixed and stirred for another 12 h.','Preparation of ZnSe@N-CNFs',5756,5814);
INSERT INTO "steps" VALUES(5268,4156,4,'dry','Dry the precursor solution directly, without electrospinning.','The ZnSe@N-C was synthesized by precursor solution directly dried at 80°C overnight and calcined at the same way with Se powder.','Preparation of ZnSe@N-CNFs',6325,6453);
INSERT INTO "steps" VALUES(5269,4156,5,'calcine','Calcine with Se powder « at the same way » as ZnSe@N-CNFs : renvoi explicite à la calcination de la voie de base, dont les valeurs ne sont pas répétées ici.','The ZnSe@N-C was synthesized by precursor solution directly dried at 80°C overnight and calcined at the same way with Se powder.','Preparation of ZnSe@N-CNFs',6325,6453);
INSERT INTO "steps" VALUES(5270,4157,1,'mix','Make a slurry of the active material, acetylene black and CMC in deionized water and ethanol (3:2).','A slurry made of ZnSe@N-CNFs (80 wt.%), acetylene black (10 wt.%), and carboxymethyl cellulose sodium (10 wt.%) was dissolved in deionized water and ethanol (3:2)','Electrochemical Characterization',7358,7520);
INSERT INTO "steps" VALUES(5271,4157,2,'deposit','Spread the slurry onto Cu foil.','spread onto Cu foil and dried at 80°C for 12 h to prepare the anodes','Electrochemical Characterization',7522,7590);
INSERT INTO "steps" VALUES(5272,4157,3,'dry','Dry the coated foil.','spread onto Cu foil and dried at 80°C for 12 h to prepare the anodes','Electrochemical Characterization',7522,7590);
INSERT INTO "steps" VALUES(5273,4158,1,'assemble','Assemble the coin-type cell from the anode, lithium metal, electrolyte and separator in an argon-filled glove box.','The LIBs were assembled into 2,032 coin-type cells in an Argon-filled glove box with lithium metal as the reference electrode, LiPF6 (1M) in ethylene carbonate (EC) and dimethyl carbonate (DMC) at a 1:1 volume ratio as electrolyte and polypropylene film (Celgard 2400) as separator.','Electrochemical Characterization',7592,7874);
INSERT INTO "steps" VALUES(5274,4160,1,'dissolve','Mix TiOSO4 with water under magnetic stirring at 50 °C until the solution is colorless.','A concentration of 2.4 g TiOSO4 was mixed with 25 mL H2O under constant magnetic stirring until the mixed solution turned into colorless solution at 50°C','Experimental Section',5798,5951);
INSERT INTO "steps" VALUES(5275,4160,2,'add','Add the CTAB solution to the colorless TiOSO4 solution.','and then 25 mL CTAB (60 mM) was added into the colorless solution and hold statically for 12 h at 50°C','Experimental Section',5953,6055);
INSERT INTO "steps" VALUES(5276,4160,3,'age','Hold the mixture statically at 50 °C.','hold statically for 12 h at 50°C','Experimental Section',6023,6055);
INSERT INTO "steps" VALUES(5277,4160,4,'filter','Filter the product.','The product obtained was filtered, washed with distilled water for several times, and dried at 120°C overnight.','Experimental Section',6057,6168);
INSERT INTO "steps" VALUES(5278,4160,5,'wash','Wash the product with distilled water.','The product obtained was filtered, washed with distilled water for several times, and dried at 120°C overnight.','Experimental Section',6057,6168);
INSERT INTO "steps" VALUES(5279,4160,6,'dry','Dry the washed product.','The product obtained was filtered, washed with distilled water for several times, and dried at 120°C overnight.','Experimental Section',6057,6168);
INSERT INTO "steps" VALUES(5280,4161,1,'mix','Prepare HCl aqueous solutions of different concentrations by diluting concentrated HCl with distilled water.','Hydrochloric acid aqueous solutions with different concentrations were initially prepared from concentrated HCl with distilled H2O, including 0.1–8 M.','Experimental Section',6169,6319);
INSERT INTO "steps" VALUES(5281,4161,2,'mix','Disperse the nanoskeleton in the HCl solution with stirring.','0.5 g Hex-ncTiO2/CTAB nanoskeleton was dispersed in 30 mL of the HCl aqueous solutions with stirring for 0.5 h','Experimental Section',6334,6444);
INSERT INTO "steps" VALUES(5282,4161,3,'heat','Hydrothermal treatment in a Teflon-lined stainless steel autoclave.','The autoclave was heated and maintained at 150°C for 24 h','Experimental Section',6533,6590);
INSERT INTO "steps" VALUES(5283,4161,4,'cool','Cool the autoclave to room temperature.','then cooled to room temperature','Experimental Section',6595,6626);
INSERT INTO "steps" VALUES(5284,4161,5,'collect','Collect the precipitate.','The precipitate was collected, centrifuged, washed with distilled water for several times, and then dried in a vacuum oven overnight at 60°C.','Experimental Section',6628,6769);
INSERT INTO "steps" VALUES(5285,4161,6,'centrifuge','Centrifuge the precipitate.','The precipitate was collected, centrifuged, washed with distilled water for several times, and then dried in a vacuum oven overnight at 60°C.','Experimental Section',6628,6769);
INSERT INTO "steps" VALUES(5286,4161,7,'wash','Wash the precipitate with distilled water.','The precipitate was collected, centrifuged, washed with distilled water for several times, and then dried in a vacuum oven overnight at 60°C.','Experimental Section',6628,6769);
INSERT INTO "steps" VALUES(5287,4161,8,'dry','Dry in a vacuum oven.','dried in a vacuum oven overnight at 60°C','Experimental Section',6728,6768);
INSERT INTO "steps" VALUES(5288,4172,1,'dissolve','Dissolve aluminium nitrate nonahydrate in distilled water.','0.844 g of Al(NO3)3·9H2O (≥98%, Sigma-Aldrich) was dissolved in 15 mL of distilled water','Synthesis',5494,5582);
INSERT INTO "steps" VALUES(5289,4172,2,'dissolve','Dissolve trimesic acid and CTAB separately from the aluminium solution, in ethanol.','0.331 g of trimesic acid (H3BTC, ≥97%, Sigma-Aldrich) and 1.004 g of cetyltrimethylammonium bromide (CTAB, ≥98%, Sigma-Aldrich) were dissolved separately in 15 mL of EtOH (≥99%, Sigma-Aldrich)','Synthesis',5588,5780);
INSERT INTO "steps" VALUES(5290,4172,3,'mix','Pour the aqueous solution into the ethanolic solution and stir at room temperature; final CTAB/Al and H2O/EtOH ratios and pH of the synthesis solution.','Subsequently, the aqueous solution was poured into the ethanolic solution and stirred for 30 min at RT.','Synthesis',5782,5885);
INSERT INTO "steps" VALUES(5291,4172,4,'heat','Solvothermal treatment in a Teflon-lined stainless steel autoclave under static conditions.','The mixture was transferred to a Teflon®-lined stainless steel autoclave and heated at 120 °C for 12 h under static conditions.','Synthesis',6008,6135);
INSERT INTO "steps" VALUES(5292,4172,5,'cool','Cool the autoclave down.','After cooling down, the product was filtered off and washed with fresh EtOH.','Synthesis',6136,6212);
INSERT INTO "steps" VALUES(5293,4172,6,'filter','Filter off the product.','After cooling down, the product was filtered off and washed with fresh EtOH.','Synthesis',6136,6212);
INSERT INTO "steps" VALUES(5294,4172,7,'wash','Wash the product with fresh ethanol.','After cooling down, the product was filtered off and washed with fresh EtOH.','Synthesis',6136,6212);
INSERT INTO "steps" VALUES(5295,4172,8,'reflux','Activation: suspend 100 mg of MOF in 100 mL of ethanol and keep under reflux.','Finally, to activate the MOFs, 100 mg were suspended in 100 mL of EtOH and kept under reflux at 60 °C overnight','Synthesis',6213,6324);
INSERT INTO "steps" VALUES(5296,4172,9,'filter','Filter off the activated MOF.','filtered off and dried overnight at room temperature','Synthesis',6326,6378);
INSERT INTO "steps" VALUES(5297,4172,10,'dry','Dry the activated MOF overnight at room temperature.','filtered off and dried overnight at room temperature','Synthesis',6326,6378);
INSERT INTO "steps" VALUES(5298,4186,1,'dissolve','Dissolve PbBr2 and CsBr in DMF to make the precursor solution.','the precursor solution was made by dissolving PbBr2 (0.1 mmol) and CsBr (0.1 mmol) in DMF (2.5 mL)','Synthesis of CsPbX3 NCs',28178,28276);
INSERT INTO "steps" VALUES(5299,4186,2,'add','Stabilize the precursor solution by adding oleic acid and oleylamine.','stabilized by adding OA (0.25 mL) and OLAm (0.13 mL)','Synthesis of CsPbX3 NCs',28281,28333);
INSERT INTO "steps" VALUES(5300,4186,3,'add','Inject part of the precursor solution into toluene under vigorous stirring to precipitate the nanocrystals at room temperature.','1 mL precursor solution was added into toluene (10 mL) under vigorous stirring for 1 min at room temperature','Synthesis of CsPbX3 NCs',28335,28443);
INSERT INTO "steps" VALUES(5301,4187,1,'dissolve','Dissolve NdBr3, PbBr2 and CsBr in DMF to make the doped precursor solution.','the precursor solution of CsPbBr3:xNd3+ (x = 7.2%) NCs was prepared by dissolving NdBr3 (0.15 mmol), PbBr2 (0.1 mmol), and CsBr (0.1 mmol) in DMF (2.5 mL)','Synthesis of Nd3+‐Doped CsPbBr3 NCs',28889,29043);
INSERT INTO "steps" VALUES(5302,4187,2,'add','Stabilize the precursor solution by adding oleic acid and oleylamine.','stabilized by adding OA (0.25 mL) and OLAm (0.13 mL)','Synthesis of CsPbX3 NCs',28281,28333);
INSERT INTO "steps" VALUES(5303,4187,3,'add','Inject part of the precursor solution into toluene under vigorous stirring to precipitate the nanocrystals at room temperature.','1 mL precursor solution was added into toluene (10 mL) under vigorous stirring for 1 min at room temperature','Synthesis of CsPbX3 NCs',28335,28443);
INSERT INTO "steps" VALUES(5304,4187,4,'centrifuge','Centrifuge the crude toluene suspension.','The crude samples in toluene were separated by centrifugation at 10 000 rpm for 10 min.','Purification',29118,29205);
INSERT INTO "steps" VALUES(5305,4187,5,'collect','Keep the strongly luminescent supernatant and discard the precipitate.','The supernatant with strong luminescence was preserved and the precipitate was discarded','Purification',29206,29294);
INSERT INTO "steps" VALUES(5306,4187,6,'precipitate','Add methyl acetate to precipitate the doped nanocrystals and remove unreacted components and byproducts.','to remove the unreacted component and byproducts, methyl acetate was adopted to assist precipitation of the doped NCs','Purification',29332,29449);
INSERT INTO "steps" VALUES(5307,4187,7,'dissolve','Redissolve the precipitate in toluene.','the precipitate was then dissolved in toluene','Purification',29454,29499);
INSERT INTO "steps" VALUES(5308,4188,1,'dissolve','Dissolve NdBr3 (amount not stated), PbBr2 and CsBr in DMF to make the doped precursor solution.','The solution of Nd3+‐doped CsPbBr3 NCs was prepared by mixing a specific molar quantity of NdBr3 in the precursor solution without changing the other operation procedures.','Synthesis of Nd3+‐Doped CsPbBr3 NCs',28703,28874);
INSERT INTO "steps" VALUES(5309,4188,2,'add','Stabilize the precursor solution by adding oleic acid and oleylamine.','stabilized by adding OA (0.25 mL) and OLAm (0.13 mL)','Synthesis of CsPbX3 NCs',28281,28333);
INSERT INTO "steps" VALUES(5310,4188,3,'add','Inject part of the precursor solution into toluene under vigorous stirring to precipitate the nanocrystals at room temperature.','1 mL precursor solution was added into toluene (10 mL) under vigorous stirring for 1 min at room temperature','Synthesis of CsPbX3 NCs',28335,28443);
INSERT INTO "steps" VALUES(5311,4188,4,'centrifuge','Centrifuge the crude toluene suspension.','The crude samples in toluene were separated by centrifugation at 10 000 rpm for 10 min.','Purification',29118,29205);
INSERT INTO "steps" VALUES(5312,4188,5,'collect','Keep the strongly luminescent supernatant and discard the precipitate.','The supernatant with strong luminescence was preserved and the precipitate was discarded','Purification',29206,29294);
INSERT INTO "steps" VALUES(5313,4188,6,'precipitate','Add methyl acetate to precipitate the doped nanocrystals and remove unreacted components and byproducts.','to remove the unreacted component and byproducts, methyl acetate was adopted to assist precipitation of the doped NCs','Purification',29332,29449);
INSERT INTO "steps" VALUES(5314,4188,7,'dissolve','Redissolve the precipitate in toluene.','the precipitate was then dissolved in toluene','Purification',29454,29499);
INSERT INTO "steps" VALUES(5315,4189,1,'dissolve','Dissolve NdBr3 (amount not stated), PbBr2 and CsBr in DMF to make the doped precursor solution.','The solution of Nd3+‐doped CsPbBr3 NCs was prepared by mixing a specific molar quantity of NdBr3 in the precursor solution without changing the other operation procedures.','Synthesis of Nd3+‐Doped CsPbBr3 NCs',28703,28874);
INSERT INTO "steps" VALUES(5316,4189,2,'add','Stabilize the precursor solution by adding oleic acid and oleylamine.','stabilized by adding OA (0.25 mL) and OLAm (0.13 mL)','Synthesis of CsPbX3 NCs',28281,28333);
INSERT INTO "steps" VALUES(5317,4189,3,'add','Inject part of the precursor solution into toluene under vigorous stirring to precipitate the nanocrystals at room temperature.','1 mL precursor solution was added into toluene (10 mL) under vigorous stirring for 1 min at room temperature','Synthesis of CsPbX3 NCs',28335,28443);
INSERT INTO "steps" VALUES(5318,4189,4,'centrifuge','Centrifuge the crude toluene suspension.','The crude samples in toluene were separated by centrifugation at 10 000 rpm for 10 min.','Purification',29118,29205);
INSERT INTO "steps" VALUES(5319,4189,5,'collect','Keep the strongly luminescent supernatant and discard the precipitate.','The supernatant with strong luminescence was preserved and the precipitate was discarded','Purification',29206,29294);
INSERT INTO "steps" VALUES(5320,4189,6,'precipitate','Add methyl acetate to precipitate the doped nanocrystals and remove unreacted components and byproducts.','to remove the unreacted component and byproducts, methyl acetate was adopted to assist precipitation of the doped NCs','Purification',29332,29449);
INSERT INTO "steps" VALUES(5321,4189,7,'dissolve','Redissolve the precipitate in toluene.','the precipitate was then dissolved in toluene','Purification',29454,29499);
INSERT INTO "steps" VALUES(5322,4190,1,'dissolve','Dissolve NdBr3 (amount not stated), PbBr2 and CsBr in DMF to make the doped precursor solution.','The solution of Nd3+‐doped CsPbBr3 NCs was prepared by mixing a specific molar quantity of NdBr3 in the precursor solution without changing the other operation procedures.','Synthesis of Nd3+‐Doped CsPbBr3 NCs',28703,28874);
INSERT INTO "steps" VALUES(5323,4190,2,'add','Stabilize the precursor solution by adding oleic acid and oleylamine.','stabilized by adding OA (0.25 mL) and OLAm (0.13 mL)','Synthesis of CsPbX3 NCs',28281,28333);
INSERT INTO "steps" VALUES(5324,4190,3,'add','Inject part of the precursor solution into toluene under vigorous stirring to precipitate the nanocrystals at room temperature.','1 mL precursor solution was added into toluene (10 mL) under vigorous stirring for 1 min at room temperature','Synthesis of CsPbX3 NCs',28335,28443);
INSERT INTO "steps" VALUES(5325,4190,4,'centrifuge','Centrifuge the crude toluene suspension.','The crude samples in toluene were separated by centrifugation at 10 000 rpm for 10 min.','Purification',29118,29205);
INSERT INTO "steps" VALUES(5326,4190,5,'collect','Keep the strongly luminescent supernatant and discard the precipitate.','The supernatant with strong luminescence was preserved and the precipitate was discarded','Purification',29206,29294);
INSERT INTO "steps" VALUES(5327,4190,6,'precipitate','Add methyl acetate to precipitate the doped nanocrystals and remove unreacted components and byproducts.','to remove the unreacted component and byproducts, methyl acetate was adopted to assist precipitation of the doped NCs','Purification',29332,29449);
INSERT INTO "steps" VALUES(5328,4190,7,'dissolve','Redissolve the precipitate in toluene.','the precipitate was then dissolved in toluene','Purification',29454,29499);
INSERT INTO "steps" VALUES(5329,4191,1,'dissolve','Dissolve NdBr3 (amount not stated), PbBr2 and CsBr in DMF to make the doped precursor solution.','The solution of Nd3+‐doped CsPbBr3 NCs was prepared by mixing a specific molar quantity of NdBr3 in the precursor solution without changing the other operation procedures.','Synthesis of Nd3+‐Doped CsPbBr3 NCs',28703,28874);
INSERT INTO "steps" VALUES(5330,4191,2,'add','Stabilize the precursor solution by adding oleic acid and oleylamine.','stabilized by adding OA (0.25 mL) and OLAm (0.13 mL)','Synthesis of CsPbX3 NCs',28281,28333);
INSERT INTO "steps" VALUES(5331,4191,3,'add','Inject part of the precursor solution into toluene under vigorous stirring to precipitate the nanocrystals at room temperature.','1 mL precursor solution was added into toluene (10 mL) under vigorous stirring for 1 min at room temperature','Synthesis of CsPbX3 NCs',28335,28443);
INSERT INTO "steps" VALUES(5332,4191,4,'centrifuge','Centrifuge the crude toluene suspension.','The crude samples in toluene were separated by centrifugation at 10 000 rpm for 10 min.','Purification',29118,29205);
INSERT INTO "steps" VALUES(5333,4191,5,'collect','Keep the strongly luminescent supernatant and discard the precipitate.','The supernatant with strong luminescence was preserved and the precipitate was discarded','Purification',29206,29294);
INSERT INTO "steps" VALUES(5334,4191,6,'precipitate','Add methyl acetate to precipitate the doped nanocrystals and remove unreacted components and byproducts.','to remove the unreacted component and byproducts, methyl acetate was adopted to assist precipitation of the doped NCs','Purification',29332,29449);
INSERT INTO "steps" VALUES(5335,4191,7,'dissolve','Redissolve the precipitate in toluene.','the precipitate was then dissolved in toluene','Purification',29454,29499);
INSERT INTO "steps" VALUES(5336,4192,1,'mix','Prepare the product from mixed CsBr and NdBr3 precursors, with NdBr3 replacing PbBr2 and no PbBr2 added; quantities, solvent, ligands and procedure are not described.','nanocrystals prepared using NdBr3 to replace PbBr2 without adding any PbBr2.','Supporting Information — ADVS-7-2001698-s001.pdf',37787,37863);
INSERT INTO "steps" VALUES(5337,4194,1,'dissolve','Dissolve PMMA in toluene.','300 mg PMMA was dissolved in toluene with a concentration of 150 mg mL−1','Preparation of PMMA‐NCs Composite Films',29544,29616);
INSERT INTO "steps" VALUES(5338,4194,2,'add','Add the nanocrystal solution to the PMMA solution under vigorous stirring.','2 mL NCs was added into the PMMA solution under vigorous stirring','Preparation of PMMA‐NCs Composite Films',29621,29686);
INSERT INTO "steps" VALUES(5339,4194,3,'degas','Store the mixture under vacuum to remove bubbles.','The mixture was stored under vacuum at room temperature for 2 h to remove the bubbles in it.','Preparation of PMMA‐NCs Composite Films',29688,29780);
INSERT INTO "steps" VALUES(5340,4194,4,'deposit','Cast the mixed solution onto a quartz substrate.','the mixed solution (1.2 mL) was cast onto the surface of a 2 cm × 2 cm quartz substrate','Preparation of PMMA‐NCs Composite Films',29808,29895);
INSERT INTO "steps" VALUES(5341,4194,5,'dry','Let the film dry under vacuum.','the film was left to dry overnight under vacuum','Preparation of PMMA‐NCs Composite Films',29900,29947);
INSERT INTO "steps" VALUES(5342,4199,1,'encapsulate','Encapsulate both pristine CsPbBr3 NCs and CsPbBr3:Nd3+ (x = 7.2%) NCs in PMMA to make the dual-emission composite film; the text does not say that this follows the PMMA-NC-film protocol.','A dual‐emission composite film is prepared by encapsulating both CsPbBr3 NCs and CsPbBr3:xNd3+ (x = 7.2%) NCs in polymethyl methacrylate (PMMA)','Results and Discussion',25811,25954);
INSERT INTO "steps" VALUES(5343,4199,2,'deposit','Deposit the dual-emission composite film on the UV LED together with the red-emitting film.','then deposited on the UV‐LED together with a red‐emitting CsPbBr1.2I1.8/PMMA film','Results and Discussion',25959,26040);
INSERT INTO "steps" VALUES(5344,4200,1,'dissolve','Dissolve the P123 surfactant template in distilled water.','6 g from the surfactant template P123 was dissolved in 45 g of distilled water','Synthesis of SBA-15',5368,5446);
INSERT INTO "steps" VALUES(5345,4200,2,'add','Add 2 M HCl to the P123 solution at 35 °C until the surfactant is completely dissolved.','Then 180 g from 2M HCl was added to the previous solution at 35 °C until the surfactant was dissolved completely.','Synthesis of SBA-15',5448,5561);
INSERT INTO "steps" VALUES(5346,4200,3,'add','Add TEOS gradually to the surfactant solution.','Then 12.75 g of TEOS was gradually added to the surfactant solution and mixed for 20 h at 35 °C.','Synthesis of SBA-15',5562,5658);
INSERT INTO "steps" VALUES(5347,4200,4,'mix','Mix the TEOS and surfactant solution for 20 h at 35 °C.','Then 12.75 g of TEOS was gradually added to the surfactant solution and mixed for 20 h at 35 °C.','Synthesis of SBA-15',5562,5658);
INSERT INTO "steps" VALUES(5348,4200,5,'age','Age the precipitated solution in a sealed glass bottle under static conditions.','The precipitated solution was then aged in sealed glass bottle for 24 h at 100 °C under static conditions.','Synthesis of SBA-15',5659,5765);
INSERT INTO "steps" VALUES(5349,4200,6,'cool','Let the white precipitate cool to room temperature.','Then the white precipitate, which was allowed to cool to room temperature, was filtered','Synthesis of SBA-15',5766,5853);
INSERT INTO "steps" VALUES(5350,4200,7,'filter','Filter the white precipitate.','Then the white precipitate, which was allowed to cool to room temperature, was filtered','Synthesis of SBA-15',5766,5853);
INSERT INTO "steps" VALUES(5351,4200,8,'wash','Wash the solid with distilled water.','was filtered, washed with distilled water','Synthesis of SBA-15',5841,5882);
INSERT INTO "steps" VALUES(5352,4200,9,'dry','Dry the washed solid at standard conditions.','and then dried at standard conditions of 25 °C for 12 h','Synthesis of SBA-15',5884,5939);
INSERT INTO "steps" VALUES(5353,4200,10,'calcine','Remove the surfactant by calcination to obtain the white SBA-15 powder.','A white powder, SBA-15, was obtained when the surfactant was removed by calcinations for 6 h at 550 °C','Synthesis of SBA-15',5941,6043);
INSERT INTO "steps" VALUES(5354,4201,1,'dry','Dry the calcined SBA-15 before grafting.','At first, 1 g of calcined SBA-15 was dried for 3 hr at 100 °C.','Surface functionalization',6172,6234);
INSERT INTO "steps" VALUES(5355,4201,2,'reflux','Stir the dried SBA-15 under reflux with toluene and APTES.','Then it was stirred under reflux with 40 ml of toluene and 10 ml of 3-aminopropyltriethoxysilane (APTES) for approximately 6 h.','Surface functionalization',6235,6362);
INSERT INTO "steps" VALUES(5356,4201,3,'cool','Cool the suspension.','The suspension was then cooled, filtered, washed with toluene, and dried at 60 °C','Surface functionalization',6363,6444);
INSERT INTO "steps" VALUES(5357,4201,4,'filter','Filter the suspension.','The suspension was then cooled, filtered, washed with toluene, and dried at 60 °C','Surface functionalization',6363,6444);
INSERT INTO "steps" VALUES(5358,4201,5,'wash','Wash the solid with toluene.','The suspension was then cooled, filtered, washed with toluene, and dried at 60 °C','Surface functionalization',6363,6444);
INSERT INTO "steps" VALUES(5359,4201,6,'dry','Dry the solid to obtain the white amino-SBA-15 powder.','dried at 60 °C, resulting in the white powder amino-SBA-15','Surface functionalization',6430,6488);
INSERT INTO "steps" VALUES(5360,4202,1,'dissolve','Prepare the aqueous chloramphenicol solution.','Using 20 mg/l of chloramphenicol, a solution of chloramphenicol was manufactured.','Chloramphenicol loading',7897,7978);
INSERT INTO "steps" VALUES(5361,4202,2,'stir','Mix the drug solution with NH2-SBA-15 and stir (loading).','Then 50 mL of drug solution was mixed with 60 mg of NH2-SBA-15 and stirred for 72 h at room temperature.','Chloramphenicol loading',7979,8083);
INSERT INTO "steps" VALUES(5362,4202,3,'measure','Follow the loading by UV absorbance of the solution.','The change in concentration was measured at different time intervals: (4, 8, 12, 24, and 48), and 72 h.','Chloramphenicol loading',8150,8253);
INSERT INTO "steps" VALUES(5363,4202,4,'prepare','Prepare the phosphate buffer solution from K2HPO4 and KH2PO4 for the release test.','First, the phosphate buffer solution was prepared using two different phosphate salts (K2HPO4 and KH2PO4).','Chloramphenicol release',9353,9459);
INSERT INTO "steps" VALUES(5364,4202,5,'adjust_ph','Set the buffer to pH 7.4.','The pH was set to 7.4 for the prepared solution in order to obtain the PH desired.','Chloramphenicol release',9460,9542);
INSERT INTO "steps" VALUES(5365,4202,6,'mix','Mix the loaded NH2-SBA-15 with PBS at body temperature (release test).','After that, 200 mg of NH2-SBA-15 loaded with 124.08 mg/l of chloramphenicol was mixed with 500 mL of PBS solution at body temperature.','Chloramphenicol release',9543,9677);
INSERT INTO "steps" VALUES(5366,4202,7,'measure','Follow the release of chloramphenicol by UV analysis over 6 h.','The amount of the drug released from the NH2-SBA-15 molecules was determined by Eq. (2) within 6 h, according to change the concentration of the drug.','Chloramphenicol release',9678,9828);
INSERT INTO "steps" VALUES(5367,4203,1,'dissolve','Dissolve citric acid in deionized water in a glass beaker.','First, 100 g of citric acid was dissolved 100 mL of deionized water in a glass beaker.','Synthesis and Characterization of C-DOTS',7942,8028);
INSERT INTO "steps" VALUES(5368,4203,2,'react','Irradiate the solution in a common microwave (Panasonic, Brazil) at high potency in an open atmosphere; the liquid turns from colorless to pale yellow and strong yellow.','Then, this solution was irradiated in a common microwave (Panasonic, Brazil) at high potency, for 8 min in an open atmosphere.','Synthesis and Characterization of C-DOTS',8029,8155);
INSERT INTO "steps" VALUES(5369,4203,3,'dialyze','Purify the C-DOTS by repeated dialysis in ultrapure water using a double dialysis bag.','Then, C-DOTS were purified by repeated dialysis in ultrapure water for 2 days (double dialyses bag molecular weight 1,300 Da).','Synthesis and Characterization of C-DOTS',8276,8402);
INSERT INTO "steps" VALUES(5370,4203,4,'dry','Dry the dialyzed solution in a hot-air oven to obtain solid C-DOTS.','Finally, the solution was dried using a hot-air oven (Phoenix Luferco, Araraquara, Brazil) to produce solid structures of C-DOTS.','Synthesis and Characterization of C-DOTS',8403,8532);
INSERT INTO "steps" VALUES(5371,4204,1,'add','Add calcium hydroxide to the 3.7 wt% gelatin solution.','3.665 g of calcium hydroxide was added to 95 mL 3.7 wt% gelatin solution','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',22518,22590);
INSERT INTO "steps" VALUES(5372,4204,2,'add','Add the 0.15 M orthophosphoric acid solution drop-wise.','A stoichiometric quantity of 0.15 M orthophosphoric acid solution (1.95 mL, at 85 °C) was added drop-wise at a rate of 0.3 mL/min','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',22592,22721);
INSERT INTO "steps" VALUES(5373,4204,3,'stir','Magnetic stirring after the acid addition.','then magnetically stirred for 24 h','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',22726,22760);
INSERT INTO "steps" VALUES(5374,4204,4,'adjust_ph','Adjust the pH to 9 with 1 N NaOH, then to a neutral level.','the pH was then adjusted to 9 by using 1 N NaOH solution to ensure that pure nano-HAP precipitation can be formed with the desired morphology; then to a neutral level','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',22769,22935);
INSERT INTO "steps" VALUES(5375,4204,5,'quench','Form the microspheres by spattering the mixture into liquid hexane on an ice bath.','The microspheres were prepared by spattering into liquid hexane on an ice bath.','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',23076,23155);
INSERT INTO "steps" VALUES(5376,4204,6,'react','Crosslink the microspheres with microbial transglutaminase.','0.1% microbial transglutaminase (mTGase) was used as a cross-linking agent to crosslink the microspheres (GHM)','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',23165,23275);
INSERT INTO "steps" VALUES(5377,4204,7,'evaporate','Let the hexane evaporate from the specimens.','After evaporation of hexane, the specimens were moved to 4 °C for 24 h','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',23620,23690);
INSERT INTO "steps" VALUES(5378,4204,8,'age','Keep the specimens at 4 °C.','the specimens were moved to 4 °C for 24 h','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',23649,23690);
INSERT INTO "steps" VALUES(5379,4204,9,'cool','Freeze the specimens at −20 °C.','frozen at −20 °C for 24 h','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',23692,23717);
INSERT INTO "steps" VALUES(5380,4204,10,'cool','Freeze the specimens at −80 °C.','−80 °C 24 h','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',23719,23730);
INSERT INTO "steps" VALUES(5381,4204,11,'dry','Lyophilize the frozen specimens.','then lyophilized for 72 h','4.2. Fabrication of Gelatin/Hydroxyapatite Microsphere (GHM) and Biomimetic Hydroxyapatite Microspheres (GHM-S)',23736,23761);
INSERT INTO "steps" VALUES(5382,4206,1,'dissolve','Dissolve selenous acid (0.44 g) and silver nitrate (1.73 g) separately in deionized water at room temperature; the dissolution volumes are not written.','Selenous acid (0.44 g) and AgNO3 (1.73 g) were separately dissolved in DIW at room temperature (RT).','3.2. Green Synthesis of Silver Selenide NPs',21822,21922);
INSERT INTO "steps" VALUES(5383,4206,2,'add','Introduce the H2SeO3 and AgNO3 solutions into a glass beaker.','5 mL of 34 mM H2SeO3 and 10 mL of 34 mM AgNO3 were added into a 300 mL glass beaker','3.2. Green Synthesis of Silver Selenide NPs',22043,22126);
INSERT INTO "steps" VALUES(5384,4206,3,'add','Immediately after the H2SeO3 and AgNO3 solutions are in the beaker, add starch and fructose, then bring the volume to 100 mL with deionized water.','Immediately after, varying masses of starch and fructose were added to the reaction mixture and the total volume was brought to 100 mL by adding DIW','3.2. Green Synthesis of Silver Selenide NPs',22128,22276);
INSERT INTO "steps" VALUES(5385,4206,4,'sonicate','Ultrasound irradiation of the reaction medium with an immersed probe, in pulsed mode.','The operating condition was 59-s pulse ON and 5-s pulse OFF with an amplitude of 70% for 30 min.','3.2. Green Synthesis of Silver Selenide NPs',22503,22599);
INSERT INTO "steps" VALUES(5386,4213,1,'weigh','Weigh the V, Al and C powders in the molar ratio 2:1.2:1.','V, Al, and C powders were weighed according to the molar ratio of 2:1.2:1.','2.1. Syntheses of V2C MXene',5220,5294);
INSERT INTO "steps" VALUES(5387,4213,2,'add','Weigh NaCl powder in a 1:1 mass ratio to the V/Al/C mixture.','Then, sodium chloride (NaCl) powders (99.5 wt.%, Yongda Company, Tianjin, China) were weighed according to the mass ratio of (2V/1.2Al/C): NaCl = 1:1.','2.1. Syntheses of V2C MXene',5295,5445);
INSERT INTO "steps" VALUES(5388,4213,3,'mix','Mix all the powders in a ball mill.','All powders were mixed by a ball mill machine for 12 h.','2.1. Syntheses of V2C MXene',5446,5501);
INSERT INTO "steps" VALUES(5389,4213,4,'anneal','Anneal the powder mixture in an alumina crucible in a tube furnace under flowing argon.','The samples were annealed in flowing Ar atmosphere (99%) at 1400 °C for 2 h.','2.1. Syntheses of V2C MXene',5606,5682);
INSERT INTO "steps" VALUES(5390,4213,5,'grind','Crush the obtained sample and sieve it to obtain the powder.','The obtained sample was crushed and sieved through a 500-mesh sieve to yield powders.','2.1. Syntheses of V2C MXene',5683,5768);
INSERT INTO "steps" VALUES(5391,4214,1,'mix','Prepare the etching solution by ultrasonic mixing of NaF with HCl and distilled water (fluoride concentration 0.6 mol/L).','The fluoride (2.00 g NaF, 1.24 g LiF or 4.48 g KF·2H2O) was ultrasonic mixed with 40 mL HCl and 40 mL distilled water for 15 min, respectively.','2.1. Syntheses of V2C MXene',6124,6267);
INSERT INTO "steps" VALUES(5392,4214,2,'add','Immerse the V2AlC powders in the etching solution.','After that, 1.44 g V2AlC powders were immersed in the solutions','2.1. Syntheses of V2C MXene',6383,6446);
INSERT INTO "steps" VALUES(5393,4214,3,'react','Etch the V2AlC under magnetic stirring.','the solutions were then kept for 72 h at 90 °C with magnetic stirring','2.1. Syntheses of V2C MXene',6452,6521);
INSERT INTO "steps" VALUES(5394,4214,4,'centrifuge','Separate the V2C MXene powders from the etching solution by centrifugation.','V2C MXene powders were centrifugally separated from the etching solutions','2.1. Syntheses of V2C MXene',6535,6608);
INSERT INTO "steps" VALUES(5395,4214,5,'wash','Wash the powders repeatedly with deionized water and ethanol.','washed with deionized water and ethanol repeatedly to remove possible absorbed ions and remaining precursors','2.1. Syntheses of V2C MXene',6614,6722);
INSERT INTO "steps" VALUES(5396,4214,6,'dry','Dry the washed powders in vacuum.','the obtained powders were dried in vacuum at 80 °C for 24 h','2.1. Syntheses of V2C MXene',6749,6808);
INSERT INTO "steps" VALUES(5397,4217,1,'prepare','Etching solution without chloride, made of 1 mL HF, 99 mL distilled water and 0.50 g NaF.','This NaF + HF solution was composed of 1 mL HF (48 mol/L, Aladdin Co., Shanghai, China), 99 mL distilled water, and 0.50 g NaF.','3.1. Synthesis Process Analysis',11242,11369);
INSERT INTO "steps" VALUES(5398,4217,2,'soak','Soak the V2AlC powders in the NaF + HF solution; nothing else is written about this test.','1.44 g V2AlC powders were soaked in NaF + HF solution without Cl−.','3.1. Synthesis Process Analysis',11175,11241);
INSERT INTO "steps" VALUES(5399,4218,1,'heat','Heat the as-prepared V2C MXene powder to 375 °C in argon.','after heating at 375 °C in Ar, the sample’s main composition was still V2C MXene','(1) Thermal Stability in Ar',16921,17001);
INSERT INTO "steps" VALUES(5400,4223,1,'dissolve','Dissolve gelatin in water in a flask under stirring to obtain a clear solution.','2.0 g of gelatin was added to 190 mL of H2O in a flask, and the solution was stirred to obtain a clear solution.','Synthesis of gelatin-reduced Ag-NPs',5003,5115);
INSERT INTO "steps" VALUES(5401,4223,2,'add','Add the aqueous silver nitrate solution to the gelatin solution under continuous stirring to obtain the Ag+/gelatin sol.','Aqueous AgNO3 (10 mL, 1 M) was added to gelatin solution with continuous stirring to obtain Ag+/gel-sol.','Synthesis of gelatin-reduced Ag-NPs',5116,5220);
INSERT INTO "steps" VALUES(5402,4223,3,'react','Distribute the Ag+/gelatin solution into three cuvettes, then stir and keep each at its temperature for 48 hours.','The solution obtained was distributed into three cuvettes, and the prepared solutions were stirred and maintained for 48 hours at different temperatures, ie, 28 (AG28), 40 (AG40), and 60°C (AG60), respectively.','Synthesis of gelatin-reduced Ag-NPs',5221,5431);
INSERT INTO "steps" VALUES(5403,4226,1,'dissolve','Dissolve gelatin in water in a flask under stirring to obtain a clear solution.','2.0 g of gelatin was added to 190 mL of H2O in a flask, and the solution was stirred to obtain a clear solution. To obtain the Ag+/gelatin solution','Synthesis of gelatin–glucose-reduced Ag-NPs',5504,5651);
INSERT INTO "steps" VALUES(5404,4226,2,'add','Add the silver nitrate solution to the gelatin solution under continuous stirring to obtain the Ag+/gelatin solution.','To obtain the Ag+/gelatin solution, the silver solution (10 mL, 1 M) was added to the gelatin solution with continuous stirring.','Synthesis of gelatin–glucose-reduced Ag-NPs',5617,5745);
INSERT INTO "steps" VALUES(5405,4226,3,'add','Add the glucose solution to the Ag+/gelatin solution.','Then, 20 mL of glucose solution (2 M) was added to the Ag+/gelatin solution.','Synthesis of gelatin–glucose-reduced Ag-NPs',5746,5822);
INSERT INTO "steps" VALUES(5406,4226,4,'react','Distribute the solution into three cuvettes, then stir and keep each at its temperature for 48 hours, in the dark.','The solution obtained was distributed into three cuvettes, and the prepared solutions were stirred and maintained for 48 hours at different temperatures, ie, 28 (AGG28), 40 (AGG40), and 60°C (AGG60), respectively.','Synthesis of gelatin–glucose-reduced Ag-NPs',5823,6036);
INSERT INTO "steps" VALUES(5407,4229,1,'add','Add the ammonium hydrogen phosphate solution dropwise to the calcium nitrate tetrahydrate solution under stirring.','0.67 M ammonium hydrogen phosphate solution was added dropwise to a solution of 1 M of calcium nitrate tetrahydrate under an appropriate stirring for 1 hour','Sample preparation',7095,7251);
INSERT INTO "steps" VALUES(5408,4229,2,'adjust_ph','Adjust the pH of the reactants with ammonia solution and nitric acid.','The pH of reactants was adjusted to the range 1 to 13 using ammonia solution and nitric acid.','Sample preparation',7293,7386);
INSERT INTO "steps" VALUES(5409,4229,3,'heat','Hydrothermal treatment of the suspension in a Teflon vessel.','The hydrothermal synthesis involved transferring hydroxyapatite suspension to a Teflon vessel 150 ml and allowing reactions to proceed at different temperatures and times, as shown in Table 1.','Sample preparation',7387,7579);
INSERT INTO "steps" VALUES(5410,4229,4,'filter','Filter the white suspension.','Finally, the white suspension was filtered','Sample preparation',7580,7622);
INSERT INTO "steps" VALUES(5411,4229,5,'wash','Wash the powder three times with a 1:1 (by volume) mixture of deionized water and ethanol.','the hydroxyapatite powder was washed three times with deionized water and ethanol (volume ratio of 1:1) to remove impurities','Sample preparation',7628,7752);
INSERT INTO "steps" VALUES(5412,4229,6,'dry','Dry the powder.','The powder was dried at 60°C for 10 hours and crushed with a mortar and pestle.','Sample preparation',7754,7833);
INSERT INTO "steps" VALUES(5413,4229,7,'grind','Crush the dried powder with a mortar and pestle.','The powder was dried at 60°C for 10 hours and crushed with a mortar and pestle.','Sample preparation',7754,7833);
INSERT INTO "steps" VALUES(5414,4245,1,'dissolve','Dissolve KMnO4 and MnSO4 separately, each in 20 mL of deionized water.','Typically, 1 mmol of KMnO4 and 1.5 mmol of MnSO4 were adequately dissolved into 20 mL deionized water, separately.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',9156,9270);
INSERT INTO "steps" VALUES(5415,4245,2,'add','Add the MnSO4 solution dropwise into the KMnO4 solution.','Then, the MnSO4 solution was added dropwise into KMnO4 solution at a rate of 1 mL min−1, and agitated continuously at room temperature for 2 h.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',9271,9414);
INSERT INTO "steps" VALUES(5416,4245,3,'stir','Keep stirring the mixture at room temperature.','Then, the MnSO4 solution was added dropwise into KMnO4 solution at a rate of 1 mL min−1, and agitated continuously at room temperature for 2 h.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',9271,9414);
INSERT INTO "steps" VALUES(5417,4245,4,'centrifuge','Collect the product by centrifugation.','The resultant product was collected by centrifugation at 12,000 rpm, followed by cleaning alternately with absolute alcohol and deionized water three times, and dried at 60 °C in a vacuum oven overnight.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',9415,9618);
INSERT INTO "steps" VALUES(5418,4245,5,'wash','Wash alternately with absolute alcohol and deionized water.','The resultant product was collected by centrifugation at 12,000 rpm, followed by cleaning alternately with absolute alcohol and deionized water three times, and dried at 60 °C in a vacuum oven overnight.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',9415,9618);
INSERT INTO "steps" VALUES(5419,4245,6,'dry','Dry the MnO2 nanoflowers in a vacuum oven.','The resultant product was collected by centrifugation at 12,000 rpm, followed by cleaning alternately with absolute alcohol and deionized water three times, and dried at 60 °C in a vacuum oven overnight.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',9415,9618);
INSERT INTO "steps" VALUES(5420,4246,1,'disperse','Disperse the MnO2 nanoflowers in deionized water in an ultrasonic bath.','Firstly, 10 mg MnO2NFs were uniformly dispersed in 10 mL deionized water under an ultrasonication bath for 0.5 h.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',9783,9896);
INSERT INTO "steps" VALUES(5421,4246,2,'add','Add the NrGO nanosheets to the MnO2NFs dispersion.','Then 0.2 g NrGO nanosheets were added into the above MnO2NFs dispersion (1 mg mL−1) and dispersed under ultrasonication for 1 h.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',9897,10025);
INSERT INTO "steps" VALUES(5422,4246,3,'disperse','Disperse the NrGO and MnO2NFs mixture under ultrasonication.','Then 0.2 g NrGO nanosheets were added into the above MnO2NFs dispersion (1 mg mL−1) and dispersed under ultrasonication for 1 h.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',9897,10025);
INSERT INTO "steps" VALUES(5423,4246,4,'store','Store the composite dispersion in a refrigerator when not used.','The MnO2NFs/NrGO were stored at 4 °C in a refrigerator when not used.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',10026,10095);
INSERT INTO "steps" VALUES(5424,4247,1,'polish','Polish the bare glassy carbon electrode with 0.3 μm then 0.05 μm alumina slurry.','The bare glassy carbon electrodes (GCEs) were carefully polished using 0.3 μm and 0.05 μm alumina slurry, then alternately washed by anhydrous alcohol and deionized water several times, and allowed to dry under an infrared lamp.','2.4. Fabrication of MnO2NFs/NrGO Modified Electrodes',10271,10499);
INSERT INTO "steps" VALUES(5425,4247,2,'wash','Wash the polished electrode alternately with anhydrous alcohol and deionized water.','The bare glassy carbon electrodes (GCEs) were carefully polished using 0.3 μm and 0.05 μm alumina slurry, then alternately washed by anhydrous alcohol and deionized water several times, and allowed to dry under an infrared lamp.','2.4. Fabrication of MnO2NFs/NrGO Modified Electrodes',10271,10499);
INSERT INTO "steps" VALUES(5426,4247,3,'dry','Let the washed electrode dry under an infrared lamp.','The bare glassy carbon electrodes (GCEs) were carefully polished using 0.3 μm and 0.05 μm alumina slurry, then alternately washed by anhydrous alcohol and deionized water several times, and allowed to dry under an infrared lamp.','2.4. Fabrication of MnO2NFs/NrGO Modified Electrodes',10271,10499);
INSERT INTO "steps" VALUES(5427,4247,4,'sonicate','Sonicate the stored MnO2NFs/NrGO dispersion before each modification.','To ensure good reproducibility, the MnO2NFs/NrGO were subjected to ultrasonication for 0.5 h before each modification.','2.3. Synthsis of MnO2NFs/NNrGO Comoposites',10096,10214);
INSERT INTO "steps" VALUES(5428,4247,5,'deposit','Drop-cast 5 μL of the dispersion on the GCE surface with a micropipette.','Specifically, 5 μL MnO2NFs/NrGO dispersion was carefully dropped and casted on the GCE surface with a micropipette, then dried with an infrared lamp to form a sensing film.','2.4. Fabrication of MnO2NFs/NrGO Modified Electrodes',10598,10770);
INSERT INTO "steps" VALUES(5429,4247,6,'dry','Dry the drop-cast film under an infrared lamp to form the sensing film.','Specifically, 5 μL MnO2NFs/NrGO dispersion was carefully dropped and casted on the GCE surface with a micropipette, then dried with an infrared lamp to form a sensing film.','2.4. Fabrication of MnO2NFs/NrGO Modified Electrodes',10598,10770);
INSERT INTO "steps" VALUES(5430,4248,1,'polish','Polish the bare glassy carbon electrode with 0.3 μm then 0.05 μm alumina slurry.','The bare glassy carbon electrodes (GCEs) were carefully polished using 0.3 μm and 0.05 μm alumina slurry, then alternately washed by anhydrous alcohol and deionized water several times, and allowed to dry under an infrared lamp.','2.4. Fabrication of MnO2NFs/NrGO Modified Electrodes',10271,10499);
INSERT INTO "steps" VALUES(5431,4248,2,'wash','Wash the polished electrode alternately with anhydrous alcohol and deionized water.','The bare glassy carbon electrodes (GCEs) were carefully polished using 0.3 μm and 0.05 μm alumina slurry, then alternately washed by anhydrous alcohol and deionized water several times, and allowed to dry under an infrared lamp.','2.4. Fabrication of MnO2NFs/NrGO Modified Electrodes',10271,10499);
INSERT INTO "steps" VALUES(5432,4248,3,'dry','Let the washed electrode dry under an infrared lamp.','The bare glassy carbon electrodes (GCEs) were carefully polished using 0.3 μm and 0.05 μm alumina slurry, then alternately washed by anhydrous alcohol and deionized water several times, and allowed to dry under an infrared lamp.','2.4. Fabrication of MnO2NFs/NrGO Modified Electrodes',10271,10499);
INSERT INTO "steps" VALUES(5433,4251,1,'dissolve','Dissolve zinc acetate dihydrate in water, without rare earth nitrate (the pure sample is described only as prepared under conditions analogous to those of the doped samples, except for the dopants).','Pure ZnO was prepared under analogous conditions as mentioned above except the addition of dopants.','Preparation of rare earth metal (RE)-doped ZnO',8153,8252);
INSERT INTO "steps" VALUES(5434,4251,2,'stir','Stir vigorously to obtain a homogeneous suspension.','stirred vigorously for 30 min to get a homogenous suspension','Preparation of rare earth metal (RE)-doped ZnO',7560,7620);
INSERT INTO "steps" VALUES(5435,4251,3,'heat','Heat the mixture with vigorous stirring.','and then heated at 80 °C for 1 h with vigorous stirring','Preparation of rare earth metal (RE)-doped ZnO',7622,7677);
INSERT INTO "steps" VALUES(5436,4251,4,'adjust_ph','Add 1 M aqueous NaOH dropwise to maintain pH 11.','a freshly prepared 1 M aqueous NaOH solution was added dropwise to maintain the pH 11','Preparation of rare earth metal (RE)-doped ZnO',7724,7809);
INSERT INTO "steps" VALUES(5437,4251,5,'age','Let the solution hydrolyze at room temperature to form a gel.','The above solution was allowed to hydrolyze at room temperature to get a gel product.','Preparation of rare earth metal (RE)-doped ZnO',7811,7896);
INSERT INTO "steps" VALUES(5438,4251,6,'filter','Filter the gel product.','The obtained product was filtered and washed several times with water followed by ethanol to remove the impurities.','Preparation of rare earth metal (RE)-doped ZnO',7897,8012);
INSERT INTO "steps" VALUES(5439,4251,7,'wash','Wash the product with water, then ethanol.','The obtained product was filtered and washed several times with water followed by ethanol to remove the impurities.','Preparation of rare earth metal (RE)-doped ZnO',7897,8012);
INSERT INTO "steps" VALUES(5440,4251,8,'dry','Dry the washed product overnight at 100 °C.','The product was dried overnight at 100 °C','Preparation of rare earth metal (RE)-doped ZnO',8013,8054);
INSERT INTO "steps" VALUES(5441,4251,9,'calcine','Calcine the dried product to obtain the nanoparticles.','then calcined at 500 °C for 6 h','Preparation of rare earth metal (RE)-doped ZnO',8059,8090);
INSERT INTO "steps" VALUES(5442,4256,1,'add','Place 100 mL of HNO3 (15 mol L-1) in a round bottom flask.','100 mL HNO3 (15 mol L-1) was prepared and added into a round bottom flask','Functionalization of carbon nanotubes',9590,9663);
INSERT INTO "steps" VALUES(5443,4256,2,'mix','Disperse the pristine CNTs in the acid solution by ultrasonication.','100 mg of pristine carbon nanotubes were dispersed into the acid solution by ultrasonication for 30 min','Functionalization of carbon nanotubes',9671,9774);
INSERT INTO "steps" VALUES(5444,4256,3,'reflux','Reflux the CNT/acid mixture in an oil bath.','refluxed for 5 h in an oil bath at 120 ºC','Functionalization of carbon nanotubes',9784,9825);
INSERT INTO "steps" VALUES(5445,4256,4,'centrifuge','Recover the HNO3-treated CNTs by centrifugation.','After centrifugation at 5000 rpm for 10 min, the HNO3-treated CNTs were recovered','Functionalization of carbon nanotubes',9827,9908);
INSERT INTO "steps" VALUES(5446,4256,5,'wash','Wash the HNO3-treated CNTs with ultrapure water until the pH is near neutral.','washed with ultrapure water until the pH of the CNT solution neared neutral','Functionalization of carbon nanotubes',9913,9988);
INSERT INTO "steps" VALUES(5447,4256,6,'dry','Dry the functionalized CNTs in an oven.','the functionalized carbon nanotubes (CNTs) were dried in the oven at 120 ºC overnight','Functionalization of carbon nanotubes',9999,10084);
INSERT INTO "steps" VALUES(5448,4257,1,'mix','Suspend the dried CNTs in ultrapure water by sonication to obtain a homogeneous dispersion.','The 0.7 g of dried CNTs were suspended in 50 mL of ultrapure water by sonicating for 30 min','Synthesis of CuO-CNT nanocomposite',10213,10304);
INSERT INTO "steps" VALUES(5449,4257,2,'mix','Mix the CNT dispersion with the CuSO4 solution under constant stirring.','the resulting homogeneous dispersion of the CNTs was mixed with 50 mL of CuSO4.5H2O solution under constant stirring','Synthesis of CuO-CNT nanocomposite',10369,10485);
INSERT INTO "steps" VALUES(5450,4257,3,'add','Add the aqueous HMTA solution with continuous stirring.','5 mL of the aqueous solution of hexamethylenetetramine (HMTA) was added with continuous stirring','Synthesis of CuO-CNT nanocomposite',10493,10589);
INSERT INTO "steps" VALUES(5451,4257,4,'heat','Hydrothermal treatment of the CuSO4/HMTA/CNT mixture in a Teflon-lined stainless autoclave.','The homogenous solution was then transferred to a 100 mL stainless autoclave lined with Teflon and heated to 170 °C for 12 h','Synthesis of CuO-CNT nanocomposite',10591,10715);
INSERT INTO "steps" VALUES(5452,4257,5,'cool','Let the autoclave cool.','the autoclave was allowed to cool at room temperature','Synthesis of CuO-CNT nanocomposite',10729,10782);
INSERT INTO "steps" VALUES(5453,4257,6,'wash','Collect the black precipitate (CuO-CNT) and wash it with ethanol and ultrapure water.','black precipitates were collected and washed with ethanol and ultrapure water several times','Synthesis of CuO-CNT nanocomposite',10787,10878);
INSERT INTO "steps" VALUES(5454,4258,1,'dissolve','Dissolve zinc nitrate, thioacetamide and CTAB in water under magnetic stirring.','certain amounts of Zn(NO3)2⋅6H2O (2 mmol), thioacetamide (2 mmol), and CTAB (2 mmol) were dissolved in 50 mL of ultrapure under magnetic stirring','Synthesis of ZnS/CuO-CNT nanocomposite',11126,11271);
INSERT INTO "steps" VALUES(5455,4258,2,'add','Add the Zn/thioacetamide/CTAB solution to the CuO-CNT dispersion.','the obtained above solution was added to CuO-CNT dispersion solution and was stirred for 30 min','Synthesis of ZnS/CuO-CNT nanocomposite',11279,11374);
INSERT INTO "steps" VALUES(5456,4258,3,'stir','Stir the combined mixture.','the obtained above solution was added to CuO-CNT dispersion solution and was stirred for 30 min','Synthesis of ZnS/CuO-CNT nanocomposite',11279,11374);
INSERT INTO "steps" VALUES(5457,4258,4,'heat','Hydrothermal treatment of the mixture in a Teflon-lined stainless autoclave.','The solution was then transferred to a 100 mL stainless autoclave lined with Teflon and heated to 170 °C for 12 h','Synthesis of ZnS/CuO-CNT nanocomposite',11376,11489);
INSERT INTO "steps" VALUES(5458,4258,5,'calcine','Calcine the collected precipitate under argon to give ZnS/CuO-CNT.','the collected precipitate was calcined under an argon atmosphere at 400 °C for 1 h','Synthesis of ZnS/CuO-CNT nanocomposite',11500,11582);
INSERT INTO "steps" VALUES(5459,4259,1,'desorb','Desorb the dyes from the dye-loaded adsorbent with the NaOH/ethanol desorbing agent at ambient temperature.','the dye-loaded adsorbent was regenerated by using the desorbing agent of NaOH (0.1 mol L −1)/ethanol at ambient temperature','Adsorbent regeneration and reuse experiments',48138,48261);
INSERT INTO "steps" VALUES(5460,4259,2,'wash','Wash the regenerated adsorbent with ultrapure water.','washed with ultrapure water, and after being dried in the oven','Adsorbent regeneration and reuse experiments',48263,48325);
INSERT INTO "steps" VALUES(5461,4259,3,'dry','Dry the regenerated adsorbent in an oven before the next adsorption cycle.','after being dried in the oven (120 ºC for 1 h) was reused in the next cycle of adsorption experiments','Adsorbent regeneration and reuse experiments',48296,48397);
INSERT INTO "steps" VALUES(5462,4260,1,'grind','Grind the raw diatomite to a size smaller than 30 mesh.','It was grounded to a size smaller than 30 mesh and dried at 105 °C.','2.1. Materials',5144,5211);
INSERT INTO "steps" VALUES(5463,4260,2,'dry','Dry the ground diatomite.','It was grounded to a size smaller than 30 mesh and dried at 105 °C.','2.1. Materials',5144,5211);
INSERT INTO "steps" VALUES(5464,4260,3,'mix','Disperse diatomite and Al(OH)3 in NaOH solution under vigorous magnetic stirring to form a homogeneous dispersion (gel); the amounts follow the Si/Al, Na2O/SiO2 and H2O/Na2O molar ratios.','Initially, diatomite and Al(OH)3 were dispersed in NaOH solution under vigorous magnetic stirring to form a homogeneous dispersion.','2.2. Preparation of Zeolite X',5754,5885);
INSERT INTO "steps" VALUES(5465,4260,4,'age','Age the slurry.','Subsequently, the slurry was subjected to aging for 0–120 min at 30–60 °C.','2.2. Preparation of Zeolite X',6072,6146);
INSERT INTO "steps" VALUES(5466,4260,5,'heat','Crystallization in a closed Teflon-lined stainless steel autoclave.','Finally, the container was closed and crystallized at 90–120 °C for 3–9 h.','2.2. Preparation of Zeolite X',6227,6301);
INSERT INTO "steps" VALUES(5467,4260,6,'cool','Let the autoclave cool naturally.','After that, the autoclave was cooled to room temperature naturally','2.2. Preparation of Zeolite X',6302,6368);
INSERT INTO "steps" VALUES(5468,4260,7,'filter','Remove the samples from the reactor and filter them.','the samples were removed from the reactor, filtered, and washed with deionized water until the pH of the filtrate reached 6–7','2.2. Preparation of Zeolite X',6374,6499);
INSERT INTO "steps" VALUES(5469,4260,8,'wash','Wash with deionized water until the filtrate pH reaches 6–7.','the samples were removed from the reactor, filtered, and washed with deionized water until the pH of the filtrate reached 6–7','2.2. Preparation of Zeolite X',6374,6499);
INSERT INTO "steps" VALUES(5470,4260,9,'dry','Dry the wet washed solids overnight.','Finally, the wet washed solids were dried overnight at 105 °C before further measurement and characterization.','2.2. Preparation of Zeolite X',6501,6611);
INSERT INTO "steps" VALUES(5471,4300,1,'mix','Add n-hexane and HFS to 20 mL of ligand solution (2-methylimidazole in water) to form mixture-I.','Both n-hexane and HFS, at the aforementioned concentrations, were added to a fixed 20 mL volume of ligand solution (13 g 2-mim in 400 mL DI water) to form mixture-I (Figure 1).','Synthesis Procedures',10085,10261);
INSERT INTO "steps" VALUES(5472,4300,2,'sonicate','Hard sonication of mixture-I to form the oil-in-water emulsion (called microemulsion by the authors) used as soft template; in ZIF-8-Ins the metal solution of step 3 is added during the last 10 min of this sonication.','Subsequently, mixture-I was hard sonicated (2 L Digital Ultrasonic Cleaner Cavitek Professional, 100 W) for 2 h (as shown in Figure 1) before the addition of 20 mL metal solution (5.9 g of zinc nitrate hexahydrate in 400 mL DI water).','Synthesis Procedures',10422,10656);
INSERT INTO "steps" VALUES(5473,4300,3,'add','Add 20 mL of the metal solution dropwise to mixture-I during the last 10 min of the sonication of step 2 (ZIF-8-Ins), i.e. while the ultrasound is still running and not after the 2 h; mixture-II turns milky.','In ZIF-8-Ins, unlike ZIF-8-Out, the metal solution was added dropwise to mixture-I during the last 10 min of pre-synthesis ultrasonication.','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',27848,27987);
INSERT INTO "steps" VALUES(5474,4300,4,'react','Synthesis of the final mixture at 30 °C and 500 rpm in a water bath.','The final synthesis mixture was maintained at 30 °C and 500 rpm for a range of synthesis times (0.5, 1, 1.5, 2, 6, 14, and 24 h).','Synthesis Procedures',10776,10905);
INSERT INTO "steps" VALUES(5475,4300,5,'centrifuge','Centrifuge the resultant mixture.','After the synthesis, the resultant mixture was centrifuged (Thermo Scientific IEC CL40) at 6000–6500 rpm and repeatedly washed using methanol.','Synthesis Procedures',10906,11048);
INSERT INTO "steps" VALUES(5476,4300,6,'wash','Wash the solid repeatedly with methanol.','After the synthesis, the resultant mixture was centrifuged (Thermo Scientific IEC CL40) at 6000–6500 rpm and repeatedly washed using methanol.','Synthesis Procedures',10906,11048);
INSERT INTO "steps" VALUES(5477,4300,7,'dry','Dry the washed samples overnight in an air oven.','Finally, the samples were dried overnight using an air oven (Binder GmbH FD 115) at 60 °C.','Synthesis Procedures',11049,11139);
INSERT INTO "steps" VALUES(5478,4336,1,'dissolve','Prepare separately a metal solution (zinc nitrate in water) and a ligand solution (2-methylimidazole in water).','The ‘metal’ and ‘ligand’ solutions were prepared separately by adding 1.17 g of zinc nitrate hexahydrate (Zn(NO3)2.6H2O) in 8 g DI water and 22.7 g of 2-methylimidazole (2- mim) in 80 g DI water, respectively.','Supporting Information — am3c06502_si_001.pdf',63036,63245);
INSERT INTO "steps" VALUES(5479,4336,2,'add','Add the metal solution to the ligand solution instantly.','The ‘metal’ solution was added to the ‘ligand’ solution instantly','Supporting Information — am3c06502_si_001.pdf',63246,63311);
INSERT INTO "steps" VALUES(5480,4336,3,'react','Leave the mixture at room temperature and 500 rpm for 2 h (synthesis time increased to 2 h from the literature recipe).','instantly and the mixture was left at room temperature (22 ± 2 °C) and 500 rpm','Supporting Information — am3c06502_si_001.pdf',63302,63380);
INSERT INTO "steps" VALUES(5481,4336,4,'centrifuge','Separate the synthesized powder by centrifugation.','The synthesized powders were separated by centrifugation and washed several times using methanol.','Supporting Information — am3c06502_si_001.pdf',63538,63635);
INSERT INTO "steps" VALUES(5482,4336,5,'wash','Wash the powder several times with methanol.','The synthesized powders were separated by centrifugation and washed several times using methanol.','Supporting Information — am3c06502_si_001.pdf',63538,63635);
INSERT INTO "steps" VALUES(5483,4336,6,'dry','Dry the powder overnight in an air oven.','Finally, the obtained powder was dried overnight using an air oven at 60 °C.','Supporting Information — am3c06502_si_001.pdf',63636,63712);
INSERT INTO "steps" VALUES(5484,4337,1,'dissolve','Prepare separately a metal solution (zinc nitrate in 40 mL water) and a ligand solution (2-methylimidazole in 40 mL water).','Briefly, the ‘metal’ and ‘ligand’ solutions were prepared separately by adding 0.59 g of zinc nitrate hexahydrate (Zn(NO3)2.6H2O) and 1.3 g of 2-methylimidazole (2-min) in 40 mL of DI water each, respectively.','Supporting Information — am3c06502_si_001.pdf',62532,62741);
INSERT INTO "steps" VALUES(5485,4337,2,'add','Add the metal solution drop-wise to the ligand solution.','Later, the ‘metal solution’ was added drop-wise to the ligand solution','Supporting Information — am3c06502_si_001.pdf',62742,62812);
INSERT INTO "steps" VALUES(5486,4337,3,'react','Leave the mixture for 2 h at room temperature and 500 rpm.','the fabrication mixture was left for 2 h at room temperature (22 ± 2°C) and 500 rpm','Supporting Information — am3c06502_si_001.pdf',62817,62900);
INSERT INTO "steps" VALUES(5487,4337,4,'centrifuge','Separate the synthesized powder by centrifugation (sentence written after the ZIF-8Lit recipe for « the synthesized powders »).','The synthesized powders were separated by centrifugation and washed several times using methanol.','Supporting Information — am3c06502_si_001.pdf',63538,63635);
INSERT INTO "steps" VALUES(5488,4337,5,'wash','Wash the powder several times with methanol.','The synthesized powders were separated by centrifugation and washed several times using methanol.','Supporting Information — am3c06502_si_001.pdf',63538,63635);
INSERT INTO "steps" VALUES(5489,4337,6,'dry','Dry the powder overnight in an air oven.','Finally, the obtained powder was dried overnight using an air oven at 60 °C.','Supporting Information — am3c06502_si_001.pdf',63636,63712);
INSERT INTO "steps" VALUES(5490,4338,1,'anneal','Heat the hollow ZIF-8 spheres in a tube furnace at 250 °C (10 °C min-1) in a continuous flow of N2 for 2 h.','Later, the hollow ZIF-8 spheres were heated in a tube furnace at 250 °C at a heating rate of 10° min-1 in a continuous flow of N2 gas for 2 hours.','Supporting Information — am3c06502_si_001.pdf',68628,68774);
INSERT INTO "steps" VALUES(5491,4339,1,'dissolve','Prepare aqueous solutions of the three metal sulfates (Ni/Mn/Co = 6/2/2), of Na2CO3 and of NH3·H2O.','Nickel-manganese-cobalt carbonate was prepared by co-precipitation method from an aqueous solution of NiSO4∙7H2O, MnSO4∙H2O and CoSO4∙7H2O (Chempur, Piekary Śląskie, Poland) (Ni2+/Mn2+/Co2+ = 6/2/2 molar ratio, the concentration was 2 mol L−1) and an aqueous solution of Na2CO3 (Chempur, Piekary Śląskie, Poland) (2 mol L−1) and NH3∙H2O (Chempur, Piekary Śląskie, Poland) (0.2 mol L−1)','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',8140,8525);
INSERT INTO "steps" VALUES(5492,4339,2,'mix','Mix the solutions slowly in a reactor filled with distilled water containing PVP.','The solutions were mixed slowly in a reactor (capacity 2 L) filled with distilled water containing 1 wt% Polyvinylpyrrolidone (Sigma Aldrich, Saint Louis, MO, USA)','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',8527,8690);
INSERT INTO "steps" VALUES(5493,4339,3,'react','Co-precipitation of the carbonate under controlled pH, temperature and stirring.','The pH value was controlled in a range of 7.5–8.0; the temperature was set at 55 °C and stirring speed at 800 rpm during the precipitation process.','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',8691,8838);
INSERT INTO "steps" VALUES(5494,4339,4,'age','Age the slurry after precipitation.','After the precipitation, the slurry was aged, filtered, washed and dried at 120 °C for 18 h.','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',8839,8931);
INSERT INTO "steps" VALUES(5495,4339,5,'filter','Filter the aged slurry.','After the precipitation, the slurry was aged, filtered, washed and dried at 120 °C for 18 h.','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',8839,8931);
INSERT INTO "steps" VALUES(5496,4339,6,'wash','Wash the filtered solid.','After the precipitation, the slurry was aged, filtered, washed and dried at 120 °C for 18 h.','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',8839,8931);
INSERT INTO "steps" VALUES(5497,4339,7,'dry','Dry the Ni0.6Mn0.2Co0.2CO3 precursor.','After the precipitation, the slurry was aged, filtered, washed and dried at 120 °C for 18 h.','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',8839,8931);
INSERT INTO "steps" VALUES(5498,4340,1,'impregnate','Impregnate the carbonate precursor with an aqueous LiOH·H2O solution (Li/TM = 1.05).','was impregnated with an aqueous solution of LiOH∙H2O (Chempur, Piekary Śląskie, Poland) at a molar ratio Li/TM = 1.05 (TM—transition metals)','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',8994,9134);
INSERT INTO "steps" VALUES(5499,4340,2,'dry','Dry the impregnated powder.','The prepared samples (in the powder forms) were dried at 120 °C for 18 h and calcinated at 500 °C for 5 h','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',9232,9337);
INSERT INTO "steps" VALUES(5500,4340,3,'calcine','First calcination step.','calcinated at 500 °C for 5 h and then at temperatures ranging from 750 to 950 °C for 15 h','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',9309,9398);
INSERT INTO "steps" VALUES(5501,4340,4,'calcine','Second calcination step; temperature is the parameter varied in the series (900 °C for NMC-900).','calcinated at 500 °C for 5 h and then at temperatures ranging from 750 to 950 °C for 15 h','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',9309,9398);
INSERT INTO "steps" VALUES(5502,4345,1,'impregnate','Impregnate NiO with an aqueous LiOH·H2O solution (Li/TM = 1.05).','LiNiO2 samples were prepared by impregnation of NiO (Merck KGaA, Darmstadt, Germany) (SSA = 66.8 m2 g−1) with an aqueous solution of LiOH∙H2O (Li/TM = 1.05 molar ratio).','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',9400,9569);
INSERT INTO "steps" VALUES(5503,4345,2,'dry','Dry the impregnated powder.','The prepared samples (in powder form) were dried at 120 °C for 18 h and calcinated at 500 °C for 5 h','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',9570,9670);
INSERT INTO "steps" VALUES(5504,4345,3,'calcine','First calcination step.','calcinated at 500 °C for 5 h and then at temperatures ranging from 650 to 850 °C for 15 h','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',9642,9731);
INSERT INTO "steps" VALUES(5505,4345,4,'calcine','Second calcination step; temperature is the parameter varied in the series (700 °C for LNO-700).','calcinated at 500 °C for 5 h and then at temperatures ranging from 650 to 850 °C for 15 h','2.1. Preparation of LiNi0.6Mn0.2Co0.2O2 (NMC) and LiNiO2 (LNO) Cathode Materials',9642,9731);
INSERT INTO "steps" VALUES(5506,4350,1,'mix','Prepare a slurry of the cathode powder, carbon black and PVDF solution in NMP.','The electrodes were prepared by casting a slurry containing 0.5 g of the cathode powder, 0.05 g of carbon black (VULCAN® XC72R, Cabot Co., Boston, MA, USA) and 1 g of 5 wt% solution of poly(vinylidene fluoride) (Sigma Aldrich, Saint Louis, MO, USA) in ca. 500 µL of 1-Methyl-2-pyrrolidinone (Sigma Aldrich, Saint Louis, MO, USA)','2.3. Electrochemical Evaluation',13157,13485);
INSERT INTO "steps" VALUES(5507,4350,2,'deposit','Cast the slurry onto aluminum foil.','onto an aluminum foil (20 μm thick, Hohsen Corp., Tokyo, Japan)','2.3. Electrochemical Evaluation',13486,13549);
INSERT INTO "steps" VALUES(5508,4350,3,'dry','Pre-dry the cast electrode.','were pre-dried at 80 °C overnight','2.3. Electrochemical Evaluation',13554,13587);
INSERT INTO "steps" VALUES(5509,4350,4,'dry','Vacuum drying of the electrode.','then vacuum dried for 24 h (120 °C, < 1 mbar)','2.3. Electrochemical Evaluation',13592,13637);
INSERT INTO "steps" VALUES(5510,4350,5,'punch','Punch the dried electrode into discs.','After drying, the electrodes were punched into discs (12.8 mm in diameter)','2.3. Electrochemical Evaluation',13639,13713);
INSERT INTO "steps" VALUES(5511,4350,6,'press','Press the discs.','and pressed (6 t cm−2)','2.3. Electrochemical Evaluation',13714,13736);
INSERT INTO "steps" VALUES(5512,4351,1,'assemble','Assemble the CR2032 half-cell (cathode, lithium foil, LiPF6 electrolyte) in an argon-filled glovebox.','The electrochemical performances of the prepared cathode materials were measured using CR2032 coin-type half-cells (Lambda System, Warsaw, Poland) at room temperature assembled in an argon filled glovebox (< 1 ppm H2O, < 1 ppm O2).','2.3. Electrochemical Evaluation',12925,13156);
INSERT INTO "steps" VALUES(5513,4352,1,'dissolve','Dissolve TMLA and o-PD in ethanol.','TMLA (0.21 g, 1.00 mmol) and o‐PD (0.22 g, 2.00 mmol) were dissolved in 20 mL ethanol and ultrasound for 5 min.','Preparation of WCDs',27697,27808);
INSERT INTO "steps" VALUES(5514,4352,2,'sonicate','Sonicate the TMLA and o-PD ethanol solution for 5 min.','TMLA (0.21 g, 1.00 mmol) and o‐PD (0.22 g, 2.00 mmol) were dissolved in 20 mL ethanol and ultrasound for 5 min.','Preparation of WCDs',27697,27808);
INSERT INTO "steps" VALUES(5515,4352,3,'heat','Solvothermal reaction of the mixture in a Teflon-lined autoclave.','Then the mixture was transferred into a 50 mL Teflon‐lined autoclave and heated at 200 °C for 10 h.','Preparation of WCDs',27809,27908);
INSERT INTO "steps" VALUES(5516,4352,4,'cool','Cool the autoclave to room temperature.','After cooling to room temperature, the products were filtered through a 0.22 µm microporous membrane to obtain the WCDs solution.','Preparation of WCDs',27909,28038);
INSERT INTO "steps" VALUES(5517,4352,5,'filter','Filter the reaction products through a microporous membrane to obtain the WCDs solution.','After cooling to room temperature, the products were filtered through a 0.22 µm microporous membrane to obtain the WCDs solution.','Preparation of WCDs',27909,28038);
INSERT INTO "steps" VALUES(5518,4352,6,'precipitate','Precipitate the hydrophobic WCDs as a solid powder in excess deionized water.','Finally, the solid WCDs powder was precipitated in excess deionized water, filtered, and dried at 40 °C under vacuum to a constant weight.','Preparation of WCDs',28115,28253);
INSERT INTO "steps" VALUES(5519,4352,7,'filter','Filter off the precipitated WCDs powder.','Finally, the solid WCDs powder was precipitated in excess deionized water, filtered, and dried at 40 °C under vacuum to a constant weight.','Preparation of WCDs',28115,28253);
INSERT INTO "steps" VALUES(5520,4352,8,'dry','Dry the solid WCDs powder under vacuum to constant weight.','Finally, the solid WCDs powder was precipitated in excess deionized water, filtered, and dried at 40 °C under vacuum to a constant weight.','Preparation of WCDs',28115,28253);
INSERT INTO "steps" VALUES(5521,4359,1,'analyze','Thin-layer chromatography to check the components of WCDs and choose the eluents.','Thin‐layer chromatography was used to verify the components of WCDs and to determine the type and proportion of eluents.','Preparation of Multicolor CDs',28354,28474);
INSERT INTO "steps" VALUES(5522,4359,2,'elute','Column chromatography of WCDs with a gradient of ethyl acetate and ethanol.','Then, the WCDs were eluted with a gradient of ethyl acetate and ethanol as elutes.','Preparation of Multicolor CDs',28475,28557);
INSERT INTO "steps" VALUES(5523,4359,3,'evaporate','Remove ethyl acetate and ethanol by vacuum distillation.','The solid multicolor CDs were prepared by vacuum distillation to remove ethyl acetate and ethanol and dried at 40 °C under vacuum to a constant weight.','Preparation of Multicolor CDs',28558,28709);
INSERT INTO "steps" VALUES(5524,4359,4,'dry','Dry the solid multicolor CDs under vacuum to constant weight.','The solid multicolor CDs were prepared by vacuum distillation to remove ethyl acetate and ethanol and dried at 40 °C under vacuum to a constant weight.','Preparation of Multicolor CDs',28558,28709);
INSERT INTO "steps" VALUES(5525,4364,1,'mix','Mix the WCDs into the PVP ethanol solution under ultrasonic treatment to obtain the WCDs/PVP mixed solution.','WCDs (0.30 mg) were mixed in PVP ethanol solution (0.25 g mL−1, 120 µL) under ultrasonic treatment for 5 min to obtain WCDs/PVP mixed solution.','Preparation of CDs/PVP Complex Solution',28897,29040);
INSERT INTO "steps" VALUES(5526,4364,2,'deposit','Drop 40 µL portions of the WCDs/PVP solution into the LED lamp cup, drying naturally between drops, until 120 µL has been added.','Specifically, WCDs/PVP mixed solution (40 µL) was dropped into the LED lamp cup, and after natural drying, continued to drop and dry until 120 µL WCDs/PVP complex solution was dropped into the LED lamp cup.','Fabrication of WLEDs and Multicolor LEDs',29649,29855);
INSERT INTO "steps" VALUES(5527,4364,3,'dry','Dry the deposited phosphor completely.','After completely drying, the lamp cup was installed on the LED chip (380 nm), and assembled into WLEDs.','Fabrication of WLEDs and Multicolor LEDs',29856,29959);
INSERT INTO "steps" VALUES(5528,4364,4,'assemble','Install the lamp cup on the 380 nm LED chip to obtain the WLED.','After completely drying, the lamp cup was installed on the LED chip (380 nm), and assembled into WLEDs.','Fabrication of WLEDs and Multicolor LEDs',29856,29959);
INSERT INTO "steps" VALUES(5529,4370,1,'dissolve','Dissolve CsBr and PbBr2 (1:1) in DMF in a reagent bottle to make the precursor solution.','In a 20 mL reagent bottle 0.15 mmol CsBr and 0.15 mmol PbBr2 was dissolved in 4 mL of DMF.','Preparation of the precursor solution',16543,16633);
INSERT INTO "steps" VALUES(5530,4370,2,'mix','Load the anti-solvent with the desired amounts of OLA and OA in a round bottom flask under vigorous stirring.','In a 50 mL round bottom flask 4 mL anti-solvent (less polar solvents) was loaded with desired amount of OLA and OA as the capping ligand and kept in a vigorously stirring condition.','Synthesis of CsPbBr3 nanocrystals (NCs)',16677,16858);
INSERT INTO "steps" VALUES(5531,4370,3,'add','Add the precursor solution drop wise into the stirring ligand/anti-solvent solution.','200 μL of precursor solution was added drop wise into the stirring solution.','Synthesis of CsPbBr3 nanocrystals (NCs)',16859,16935);
INSERT INTO "steps" VALUES(5532,4370,4,'react','Nanocrystals form in the open air at room temperature; in ethyl acetate the quantum dots appear immediately.','2.6 ± 0.9 nm sized quasi-cubic CsPbBr3 QDs are formed immediately on addition of the precursor solution','Quantum Dots',4678,4781);
INSERT INTO "steps" VALUES(5533,4370,5,'centrifuge','Centrifuge the crude solution collected at the chosen stage of the reaction.','The crude solutions collected at different stages of the reaction were centrifuged at 5000 rpm for 6 minutes.','Separation and purification of the NCs',17340,17449);
INSERT INTO "steps" VALUES(5534,4370,6,'wash','Discard the supernatant and wash the precipitate with ethyl acetate.','Following the centrifugation, the supernatant liquid was discarded, the precipitate was washed with ethyl acetate and then dispersed in toluene or hexane.','Separation and purification of the NCs',17546,17700);
INSERT INTO "steps" VALUES(5535,4370,7,'disperse','Redisperse the washed precipitate in toluene or hexane.','the precipitate was washed with ethyl acetate and then dispersed in toluene or hexane','Separation and purification of the NCs',17614,17699);
INSERT INTO "steps" VALUES(5536,4370,8,'separate','When several populations coexist, separate them from each other by size-selective precipitation (no detail given).','Different NC population was separated from each other by the use of size-selective precipitation method.','Effect of Other Solvents',12665,12769);
INSERT INTO "steps" VALUES(5537,4383,1,'dissolve','Dissolve the lead halide in DMF.','0.15 mmol PbX2 (X = Cl, I) was dissolved in 5 mL of DMF','Anion exchange process',17727,17782);
INSERT INTO "steps" VALUES(5538,4383,2,'add','Add the PbX2 solution drop wise to the stirring CsPbBr3 NC solution; the amount added sets the emission properties.','added drop wise to the stirring CsPbBr3 NC solution. By controlling the amount of added PbX2 solution we can easily tune the emission properties of these NCs.','Anion exchange process',17787,17945);
INSERT INTO "steps" VALUES(5539,4383,3,'age','Let the mixture reach equilibrium.','The reaction reaches to equilibrium after allowing it for some time','Anion exchange process',17946,18013);
INSERT INTO "steps" VALUES(5540,4383,4,'centrifuge','Separate the exchanged nanocrystals by centrifugation.','then the NCs were separated by centrifugation for further studies','Anion exchange process',18014,18079);
INSERT INTO "steps" VALUES(5541,4401,1,'dissolve','Prepare a 0.12 M oxalic acid solution (30 mL) in deionized water.','0.12 M solution (30 mL) was prepared using H2C2O4·2H2O and deionized water','Synthesis of Materials',5463,5537);
INSERT INTO "steps" VALUES(5542,4401,2,'add','Add NH4VO3 and NaH2PO4 to the oxalic acid solution and mix at 70°C to obtain a green solution (Solution I).','NH4VO3 and NaH2PO4 (V: Na = 2:3, molar ratio) were added into the above solution, and a green solution (Solution I) was got after mixing at 70°C for 2 h.','Synthesis of Materials',5546,5699);
INSERT INTO "steps" VALUES(5543,4401,3,'dissolve','Dissolve PVP K90 in deionized water at room temperature to obtain Solution II (30 mL).','After stirring for 2 h at room temperature, 1.5 g mL−1 PVP solution (Solution II, 30 mL) was obtained.','Synthesis of Materials',5787,5889);
INSERT INTO "steps" VALUES(5544,4401,4,'mix','Mix Solution I with Solution II under stirring to obtain the spinning solution (Solution III).','Solution I was mixed with solution II under stirring, and then the final spinning solution (Solution III) was obtained after 2 h.','Synthesis of Materials',5894,6023);
INSERT INTO "steps" VALUES(5545,4401,5,'deposit','Electrospin Solution III onto an Al-foil collector.','Solution III was pumped into an injector with a stainless steel needle pipe (inside diameter: 0.6 mm).','Synthesis of Materials',6028,6130);
INSERT INTO "steps" VALUES(5546,4401,6,'dry','Collect the precursor nanofibers and dry them in an oven.','Then the nanofibers of precursor were collected and dried at 120°C in oven for 12 h.','Synthesis of Materials',6313,6397);
INSERT INTO "steps" VALUES(5547,4401,7,'calcine','Calcine the precursor nanofibers under Ar (conditions of the optimal sample, 800°C, 10 h, 2.5°C min−1).','calcine at 800°C for 10 h with a heating rate of 2.5°C min−1','Results and Discussion',16227,16287);
INSERT INTO "steps" VALUES(5548,4401,8,'cool','Cool the calcined nanofibers to ambient temperature.','And a series of Na3V2(PO4)3/C composite nanofibers were obtained after cooling to ambient temperature.','Synthesis of Materials',6533,6635);
INSERT INTO "steps" VALUES(5549,4410,1,'mix','Mix the Na3V2(PO4)3/C sample, acetylene black and PVDF in the weight ratio 8:1:1 in NMP.','The positive electrode plate was prepared with the Na3V2(PO4)3/C samples, acetylene black and PVDF (8:1:1, weight ratio) by using N-methylpyrrolidone (NMP) solvent with an Al-foil as current collector.','Electrochemical Measurements',7011,7212);
INSERT INTO "steps" VALUES(5550,4411,1,'assemble','Assemble the CR2025 button cell (positive electrode, glass fiber separator, Na-foil negative electrode, NaClO4 electrolyte) in an Ar-filled glove box.','The button batteries (CR2025) were assembled in an Ar-filled glove box.','Electrochemical Measurements',7265,7336);
INSERT INTO "steps" VALUES(5551,4412,1,'dissolve','Dissolve copper nitrate trihydrate and H3BTC in the DMF:EtOH mixture under ultrasonication and magnetic stirring.','Cu(NO3)2·3H2O (0.7248 g) and H3BTC (0.4242 g) were dissolved in 12 mL of 9:3 (v/v) dimethylformamide:ethanol (DMF:EtOH) under ultrasonication and magnetic stirring for 40 min, respectively.','2.2. Synthesis of the CuS/C-80/120/160 Materials',8490,8679);
INSERT INTO "steps" VALUES(5552,4412,2,'add','Add the BTC solution dropwise to the Cu2+ solution under rapid stirring.','Then, the BTC solution was added dropwise to the Cu2+ solution under rapid stirring.','2.2. Synthesis of the CuS/C-80/120/160 Materials',8680,8764);
INSERT INTO "steps" VALUES(5553,4412,3,'add','Add PVP dropwise to the mixed solution as a surface stabilizer.','Once the two solutions were mixed, 0.1 g of polyvinyl pyrrolidone (PVP) was added dropwise to the solution as a surface stabilizer.','2.2. Synthesis of the CuS/C-80/120/160 Materials',8765,8896);
INSERT INTO "steps" VALUES(5554,4412,4,'heat','Solvothermal treatment of the reaction mixture in a sealed autoclave to form the Cu-MOF.','Subsequently, the reaction mixture was sealed in a 100 mL Teflon-lined stainless steel autoclave and heated in a water bath at 140 °C for 24 h.','2.2. Synthesis of the CuS/C-80/120/160 Materials',8897,9040);
INSERT INTO "steps" VALUES(5555,4412,5,'cool','Let the autoclave cool naturally to room temperature.','After the completion of the reaction, the sample was allowed to naturally cool to room temperature and subsequently washed thrice using EtOH.','2.2. Synthesis of the CuS/C-80/120/160 Materials',9041,9182);
INSERT INTO "steps" VALUES(5556,4412,6,'wash','Wash the Cu-MOF three times with ethanol.','After the completion of the reaction, the sample was allowed to naturally cool to room temperature and subsequently washed thrice using EtOH.','2.2. Synthesis of the CuS/C-80/120/160 Materials',9041,9182);
INSERT INTO "steps" VALUES(5557,4412,7,'anneal','Anneal the resulting solid powder under argon to obtain a black powder (the Cu-MOF-derived precursor).','Finally, the resulting solid powder was annealed under argon atmosphere at 350 °C for 12 h to obtain a black powder.','2.2. Synthesis of the CuS/C-80/120/160 Materials',9183,9299);
INSERT INTO "steps" VALUES(5558,4413,1,'dissolve','Weigh the Cu-MOF and thioacetamide and dissolve them in ethylene glycol.','Three sets of the synthesized Cu–MOF (0.0800 g) and thioacetamide (0.1800 g) of equal mass were weighed and dissolved in 20 mL of ethylene glycol.','2.2. Synthesis of the CuS/C-80/120/160 Materials',9361,9507);
INSERT INTO "steps" VALUES(5559,4413,2,'disperse','Disperse the particles with an ultrasonic oscillator.','The particles were subsequently dispersed using an ultrasonic oscillator to obtain homogeneous aqueous solutions.','2.2. Synthesis of the CuS/C-80/120/160 Materials',9508,9621);
INSERT INTO "steps" VALUES(5560,4413,3,'mix','Mix the two solutions and stir; a bluish-green precipitate appears immediately.','Furthermore, the two solutions were mixed together and evenly stirred, resulting in the immediate appearance of a bluish-green precipitate.','2.2. Synthesis of the CuS/C-80/120/160 Materials',9622,9761);
INSERT INTO "steps" VALUES(5561,4413,4,'heat','Sulfidation (vulcanization) in Teflon-lined stainless steel autoclaves placed in vacuum drying ovens set to a temperature gradient.','they were transferred to Teflon-lined stainless steel autoclaves and placed in three identical vacuum drying ovens set to a temperature gradient to heat for 12 h.','2.2. Synthesis of the CuS/C-80/120/160 Materials',9806,9968);
INSERT INTO "steps" VALUES(5562,4413,5,'cool','Let the samples cool to room temperature.','After the vulcanization reaction, the samples were allowed to cool to room temperature, and they were subsequently washed thrice using EtOH.','2.2. Synthesis of the CuS/C-80/120/160 Materials',10031,10171);
INSERT INTO "steps" VALUES(5563,4413,6,'wash','Wash the black CuS/C product three times with ethanol.','After the vulcanization reaction, the samples were allowed to cool to room temperature, and they were subsequently washed thrice using EtOH.','2.2. Synthesis of the CuS/C-80/120/160 Materials',10031,10171);
INSERT INTO "steps" VALUES(5564,4416,1,'mix','Mix the CuS/C-120 active material, PVDF and acetylene black, then add NMP dropwise under stirring to make a slurry.','The working electrodes were prepared by mixing 80% active materials, 15% polyvinylidene fluoride, and 5% acetylene black. Then, NMP was added dropwise and stirred to prepare slurry.','2.5. Electrochemical Analysis',12203,12384);
INSERT INTO "steps" VALUES(5565,4416,2,'deposit','Coat the slurry onto the carbon cloth.','The resulting slurry was coated onto the CC, which was followed by drying at 60 °C for 12 h in a vacuum oven.','2.5. Electrochemical Analysis',12385,12494);
INSERT INTO "steps" VALUES(5566,4416,3,'dry','Dry the coated carbon cloth in a vacuum oven.','The resulting slurry was coated onto the CC, which was followed by drying at 60 °C for 12 h in a vacuum oven.','2.5. Electrochemical Analysis',12385,12494);
INSERT INTO "steps" VALUES(5567,4416,4,'deposit','Cyclic voltammetric electrodeposition of PANI on the CuS/C-120 electrode in 3 M KCl containing 0.1 M aniline, in a three-electrode system.','which was performed in a three-electrode system from −0.3 to 0.6 V at 10 mV−1 for 20 cycles.','2.3. Fabrication of the CuS/C-120@PANI Electrode Electrodes',10797,10889);
INSERT INTO "steps" VALUES(5568,4416,5,'wash','Gently rinse the electrode with distilled water.','When the deposition was completed, the electrode was gently rinsed using distilled water and dried prior to use.','2.3. Fabrication of the CuS/C-120@PANI Electrode Electrodes',10983,11095);
INSERT INTO "steps" VALUES(5569,4416,6,'dry','Dry the electrode before use.','When the deposition was completed, the electrode was gently rinsed using distilled water and dried prior to use.','2.3. Fabrication of the CuS/C-120@PANI Electrode Electrodes',10983,11095);
INSERT INTO "steps" VALUES(5570,4417,1,'dissolve','Dissolve BTC and ZrOCl2·8H2O in water in a round-bottom flask.','182 mL H2O was used to dissolve 5.08 g (24.2 mmol) BTC and 23.4 g (72.8 mmol) ZrOCl2·8H2O in a 500 mL round-bottom flask','2.2. MOF Synthesis',7066,7186);
INSERT INTO "steps" VALUES(5571,4417,2,'add','Add formic acid to the solution.','subsequently 26.8 mL (712 mmol) FA was added','2.2. MOF Synthesis',7191,7235);
INSERT INTO "steps" VALUES(5572,4417,3,'stir','Stir the mixture before heating.','After 15 min of stirring, the mixture was heated to 100 °C under reflux for 5 h in an oil bath.','2.2. MOF Synthesis',7237,7332);
INSERT INTO "steps" VALUES(5573,4417,4,'reflux','Heat the mixture under reflux in an oil bath.','the mixture was heated to 100 °C under reflux for 5 h in an oil bath','2.2. MOF Synthesis',7263,7331);
INSERT INTO "steps" VALUES(5574,4417,5,'wash','Wash the MOF sludge with demi water then ethanol.','The resulting MOF sludge was washed four times with demi water and three times with ethanol.','2.2. MOF Synthesis',7333,7425);
INSERT INTO "steps" VALUES(5575,4417,6,'centrifuge','Centrifuge between washing steps and decant the supernatant.','In between washing steps, the samples were centrifuged (4000 rpm, 10 min) and the supernatant was decanted.','2.2. MOF Synthesis',7426,7533);
INSERT INTO "steps" VALUES(5576,4417,7,'dry','Dry the washed MOF in a vacuum oven.','Finally, the washed MOF was dried in a vacuum oven at 70 °C overnight.','2.2. MOF Synthesis',7534,7604);
INSERT INTO "steps" VALUES(5577,4418,1,'mix','Disperse MOF-808 in the solvent in an ultrasonic bath.','a prescribed amount of MOF-808 was dispersed in the respective solvent in an ultrasonic bath for 30 min','2.3. Membrane Synthesis',8660,8763);
INSERT INTO "steps" VALUES(5578,4418,2,'add','Add the polymer in three equal portions, two hours apart, following a priming protocol.','then the polymer was added in three steps (in equal amounts at 2 h intervals) according to a priming protocol','2.3. Membrane Synthesis',8768,8877);
INSERT INTO "steps" VALUES(5579,4418,3,'dissolve','Dissolve the polymer by stirring overnight to the target polymer concentration.','6FDD co-polyimide was dissolved in a respective solvent (THF, chloroform, DCM, or MEK) by stirring overnight to produce 3, 4, 5, 7, 10, or 15 wt.% polymer solutions','2.3. Membrane Synthesis',7632,7796);
INSERT INTO "steps" VALUES(5580,4418,4,'deposit','Pour the solution into Teflon Petri dishes in a N2-filled glove bag; 4 g of solution gives the S-version.','The solutions were then poured into Teflon Petri dishes (diameter 6 cm) in a N2-filled glove bag.','2.3. Membrane Synthesis',8066,8163);
INSERT INTO "steps" VALUES(5581,4418,5,'evaporate','Solvent evaporation after casting. Slow rate (this route): funnel placed upside-down over the dish with its outlet covered with alumina foil; medium rate: funnel only; fast rate: no cover (section 2.3).','(ii) solvent evaporation was slowed down by placing a funnel upside-down (with volume of 200 mL, bottom diameter of 10 cm, and top diameter of 1.5 cm) over the dishes, and (iii) evaporation was further slowed down by covering this funnel outlet with alumina foil','2.3. Membrane Synthesis',8367,8629);
INSERT INTO "steps" VALUES(5582,4418,6,'anneal','First annealing stage at 100 °C.','the solidified membranes were heated to 100 °C at a rate of 5 °C/min and an isothermal condition was maintained for 1 h','2.3. Membrane Synthesis',9425,9544);
INSERT INTO "steps" VALUES(5583,4418,7,'anneal','Second annealing stage at 180 °C.','The temperature was then increased till 180 °C using a heating rate of 5 °C/min. Subsequently, it was held for 6 h at this temperature','2.3. Membrane Synthesis',9546,9680);
INSERT INTO "steps" VALUES(5584,4418,8,'cool','Natural cooling to room temperature overnight.','then cooled overnight to room temperature naturally','2.3. Membrane Synthesis',9685,9736);
INSERT INTO "steps" VALUES(5585,4418,9,'cut','Cut coupons from the dried membranes.','Coupons with a diameter of 20 mm were cut from dried membranes','2.3. Membrane Synthesis',9738,9800);
INSERT INTO "steps" VALUES(5586,4457,1,'dissolve','Prepare the 20 wt.% 6FDD solution in THF (the article lists dissolution by overnight stirring only for 3 to 15 wt.%).','attempts to prepare membranes from 20 wt.% polymer solutions failed due to the very high viscosity of the solution','3.1.1. Visual Assessment',17023,17137);
INSERT INTO "steps" VALUES(5587,4457,2,'deposit','Attempted membrane preparation from the 20 wt.% solution: failed because of the very high viscosity of the solution.','attempts to prepare membranes from 20 wt.% polymer solutions failed due to the very high viscosity of the solution','3.1.1. Visual Assessment',17023,17137);
INSERT INTO "steps" VALUES(5588,4458,1,'dissolve','Dissolve the 6FDD co-polyimide in THF by stirring overnight to the target polymer concentration; no MOF is dispersed.','6FDD co-polyimide was dissolved in a respective solvent (THF, chloroform, DCM, or MEK) by stirring overnight to produce 3, 4, 5, 7, 10, or 15 wt.% polymer solutions','2.3. Membrane Synthesis',7632,7796);
INSERT INTO "steps" VALUES(5589,4458,2,'deposit','Pour the solution into Teflon Petri dishes in a N2-filled glove bag; 4 g of solution gives the S-version.','The solutions were then poured into Teflon Petri dishes (diameter 6 cm) in a N2-filled glove bag.','2.3. Membrane Synthesis',8066,8163);
INSERT INTO "steps" VALUES(5590,4458,3,'evaporate','Solvent evaporation after casting. Slow rate (this route): funnel placed upside-down over the dish with its outlet covered with alumina foil; medium rate: funnel only; fast rate: no cover (section 2.3).','(ii) solvent evaporation was slowed down by placing a funnel upside-down (with volume of 200 mL, bottom diameter of 10 cm, and top diameter of 1.5 cm) over the dishes, and (iii) evaporation was further slowed down by covering this funnel outlet with alumina foil','2.3. Membrane Synthesis',8367,8629);
INSERT INTO "steps" VALUES(5591,4458,4,'anneal','First annealing stage at 100 °C.','the solidified membranes were heated to 100 °C at a rate of 5 °C/min and an isothermal condition was maintained for 1 h','2.3. Membrane Synthesis',9425,9544);
INSERT INTO "steps" VALUES(5592,4458,5,'anneal','Second annealing stage at 180 °C.','The temperature was then increased till 180 °C using a heating rate of 5 °C/min. Subsequently, it was held for 6 h at this temperature','2.3. Membrane Synthesis',9546,9680);
INSERT INTO "steps" VALUES(5593,4458,6,'cool','Natural cooling to room temperature overnight.','then cooled overnight to room temperature naturally','2.3. Membrane Synthesis',9685,9736);
INSERT INTO "steps" VALUES(5594,4458,7,'cut','Cut coupons from the dried membranes.','Coupons with a diameter of 20 mm were cut from dried membranes','2.3. Membrane Synthesis',9738,9800);
INSERT INTO "steps" VALUES(5595,4498,1,'dissolve','Dissolve sodium alginate in ultrapure water under magnetic stirring.','Sodium alginate was added to ultrapure water at 1–4 wt% concentrations and mixed for 2 h using a magnetic stirrer (C-MAG HS7, IKA, Staufen, Germany).','4.2. Fabrication of Alginate Gel Beads',26391,26540);
INSERT INTO "steps" VALUES(5596,4498,2,'deposit','Add the alginate solution dropwise with a syringe into the CaCl2 aqueous solution.','Beads were produced using the extrusion-dripping method, where the prepared alginate solutions (1, 2, and 4 wt%) were added dropwise using a 1 mL syringe into a CaCl2 aqueous solution.','4.2. Fabrication of Alginate Gel Beads',26541,26725);
INSERT INTO "steps" VALUES(5597,4498,3,'react','Cross-link the beads in the CaCl2 bath without stirring.','The crosslinking time was set at 30 min, followed by rinsing the beads three times in deionized water and placing them in a beaker containing ultrapure water.','4.2. Fabrication of Alginate Gel Beads',26726,26884);
INSERT INTO "steps" VALUES(5598,4498,4,'wash','Rinse the beads in deionized water and keep them in ultrapure water.','followed by rinsing the beads three times in deionized water and placing them in a beaker containing ultrapure water','4.2. Fabrication of Alginate Gel Beads',26767,26883);
INSERT INTO "steps" VALUES(5599,4515,1,'dissolve','Dissolve sodium alginate in ultrapure water under magnetic stirring.','Sodium alginate was added to ultrapure water at 1–4 wt% concentrations and mixed for 2 h using a magnetic stirrer (C-MAG HS7, IKA, Staufen, Germany).','4.2. Fabrication of Alginate Gel Beads',26391,26540);
INSERT INTO "steps" VALUES(5600,4515,2,'deposit','Add the alginate solution dropwise with a syringe into the CaCl2 aqueous solution.','Beads were produced using the extrusion-dripping method, where the prepared alginate solutions (1, 2, and 4 wt%) were added dropwise using a 1 mL syringe into a CaCl2 aqueous solution.','4.2. Fabrication of Alginate Gel Beads',26541,26725);
INSERT INTO "steps" VALUES(5601,4515,3,'react','Cross-link the beads in the CaCl2 bath without stirring.','The crosslinking time was set at 30 min, followed by rinsing the beads three times in deionized water and placing them in a beaker containing ultrapure water.','4.2. Fabrication of Alginate Gel Beads',26726,26884);
INSERT INTO "steps" VALUES(5602,4515,4,'wash','Rinse the beads in deionized water and keep them in ultrapure water.','followed by rinsing the beads three times in deionized water and placing them in a beaker containing ultrapure water','4.2. Fabrication of Alginate Gel Beads',26767,26883);
INSERT INTO "steps" VALUES(5603,4515,5,'deposit','Coat the beads by vortex mixing them in the chitosan solution.','The chitosan-coated beads were prepared by vortex mixing in a 0.5 wt% chitosan solution for 30 min, then rinsed and stored in deionized water.','4.2. Fabrication of Alginate Gel Beads',27136,27278);
INSERT INTO "steps" VALUES(5604,4515,6,'wash','Rinse the coated beads and store them in deionized water.','then rinsed and stored in deionized water','4.2. Fabrication of Alginate Gel Beads',27236,27277);
INSERT INTO "steps" VALUES(5605,4518,1,'grind','Grind zeolite 5A into powder.','0.25 g of 5A zeolites (Z5A) were ground into powder using a ceramic mortar','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',27540,27614);
INSERT INTO "steps" VALUES(5606,4518,2,'dry','Dehydrate the zeolite powder in an oven to remove pore water.','The resulting powder was then dehydrated by placing it in an oven at 120 °C overnight.','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',27616,27702);
INSERT INTO "steps" VALUES(5607,4518,3,'stir','Incubate the dehydrated zeolite with a curcumin solution in ethanol under stirring.','Subsequently, the zeolites were incubated with a solution of curcumin in ethanol (0.05 mol/L) and stirred for 48 h.','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',27812,27927);
INSERT INTO "steps" VALUES(5608,4518,4,'centrifuge','Centrifuge the ethanol/Z5A/Cur suspension.','The ethanol/Z5A/Cur solution was then centrifuged for 10 min at 6000 rpm','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',27928,28000);
INSERT INTO "steps" VALUES(5609,4518,5,'dry','Dry the solid in an oven to remove residual solvent.','dried in an oven at 60 °C for 12 h to remove any residual solvent','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',28005,28070);
INSERT INTO "steps" VALUES(5610,4519,1,'dissolve','Prepare the alginate solution in ultrapure water under magnetic stirring.','Sodium alginate was added to ultrapure water at 1–4 wt% concentrations and mixed for 2 h using a magnetic stirrer (C-MAG HS7, IKA, Staufen, Germany).','4.2. Fabrication of Alginate Gel Beads',26391,26540);
INSERT INTO "steps" VALUES(5611,4519,2,'add','Add Z5A-Cur to the alginate solution.','An amount of 0.2 g of Z5A-Cur was added to 10 mL of alginate solution to prepare the composite beads.','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',28271,28372);
INSERT INTO "steps" VALUES(5612,4519,3,'stir','Stir the Alg/Z5A/Cur solution.','The Alg/Z5A/Cur solution was stirred for 15 min and then sonicated for 45 min to achieve a homogeneous solution.','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',28373,28485);
INSERT INTO "steps" VALUES(5613,4519,4,'sonicate','Sonicate the suspension to homogenize it.','then sonicated for 45 min to achieve a homogeneous solution','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',28425,28484);
INSERT INTO "steps" VALUES(5614,4519,5,'deposit','Add the suspension dropwise into the CaCl2 aqueous solution with the optimized parameters.','Composite beads were fabricated using the extrusion-dripping method, where the Alg/Z5A/Cur solution was added dropwise into a CaCl2 aqueous solution, following the parameters optimized in the initial steps of the work.','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',28486,28704);
INSERT INTO "steps" VALUES(5615,4519,6,'react','Cross-link the beads in the CaCl2 bath.','The crosslinking time was set at 30 min, followed by rinsing the beads three times in deionized water and placing them in a beaker containing ultrapure water.','4.2. Fabrication of Alginate Gel Beads',26726,26884);
INSERT INTO "steps" VALUES(5616,4519,7,'wash','Rinse the beads in deionized water and keep them in ultrapure water.','followed by rinsing the beads three times in deionized water and placing them in a beaker containing ultrapure water','4.2. Fabrication of Alginate Gel Beads',26767,26883);
INSERT INTO "steps" VALUES(5617,4520,1,'dissolve','Prepare the alginate solution in ultrapure water under magnetic stirring.','Sodium alginate was added to ultrapure water at 1–4 wt% concentrations and mixed for 2 h using a magnetic stirrer (C-MAG HS7, IKA, Staufen, Germany).','4.2. Fabrication of Alginate Gel Beads',26391,26540);
INSERT INTO "steps" VALUES(5618,4520,2,'add','Add Z5A-Cur to the alginate solution.','An amount of 0.2 g of Z5A-Cur was added to 10 mL of alginate solution to prepare the composite beads.','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',28271,28372);
INSERT INTO "steps" VALUES(5619,4520,3,'stir','Stir the Alg/Z5A/Cur solution.','The Alg/Z5A/Cur solution was stirred for 15 min and then sonicated for 45 min to achieve a homogeneous solution.','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',28373,28485);
INSERT INTO "steps" VALUES(5620,4520,4,'sonicate','Sonicate the suspension to homogenize it.','then sonicated for 45 min to achieve a homogeneous solution','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',28425,28484);
INSERT INTO "steps" VALUES(5621,4520,5,'deposit','Add the suspension dropwise into the CaCl2 aqueous solution with the optimized parameters.','Composite beads were fabricated using the extrusion-dripping method, where the Alg/Z5A/Cur solution was added dropwise into a CaCl2 aqueous solution, following the parameters optimized in the initial steps of the work.','4.3. Preparation of Chitosan Coated Alg/Z5A/Cur Gel Beads',28486,28704);
INSERT INTO "steps" VALUES(5622,4520,6,'react','Cross-link the beads in the CaCl2 bath.','The crosslinking time was set at 30 min, followed by rinsing the beads three times in deionized water and placing them in a beaker containing ultrapure water.','4.2. Fabrication of Alginate Gel Beads',26726,26884);
INSERT INTO "steps" VALUES(5623,4520,7,'wash','Rinse the beads in deionized water and keep them in ultrapure water.','followed by rinsing the beads three times in deionized water and placing them in a beaker containing ultrapure water','4.2. Fabrication of Alginate Gel Beads',26767,26883);
INSERT INTO "steps" VALUES(5624,4520,8,'deposit','Coat the beads by vortex mixing them in the chitosan solution.','The chitosan-coated beads were prepared by vortex mixing in a 0.5 wt% chitosan solution for 30 min, then rinsed and stored in deionized water.','4.2. Fabrication of Alginate Gel Beads',27136,27278);
INSERT INTO "steps" VALUES(5625,4520,9,'wash','Rinse the coated beads and store them in deionized water.','then rinsed and stored in deionized water','4.2. Fabrication of Alginate Gel Beads',27236,27277);
INSERT INTO "steps" VALUES(5626,4521,1,'dissolve','Dissolve the transition metal nitrate (here Ni(NO3)2) in deionized water to a theoretical concentration of 0.75 mol/L.','Transition metal nitrates [Fe(NO3)2, Co(NO3)2, Mo(NO3)3, Mn(NO3)2 and Ni(NO3)2 ] were dissolved into deionized water to the setting theoretical concentration of 0.75 mol/L.','Preparation and characterization of the catalyst',5454,5626);
INSERT INTO "steps" VALUES(5627,4521,2,'add','Add the impregnation solution dropwise onto the TiO2 powder under continuous stirring at room temperature.','Then the impregnation solution (100 mL) was dropped onto TiO2 powder (20 g) with continuous stirring in a 250 mL beaker at room temperature (25 °C).','Preparation and characterization of the catalyst',5627,5775);
INSERT INTO "steps" VALUES(5628,4521,3,'age','Let the metal permeate into the support at room temperature.','After the metal permeated into the support for 24 h at room temperature, the impregnation liquid was separated out by decantation','Preparation and characterization of the catalyst',5776,5905);
INSERT INTO "steps" VALUES(5629,4521,4,'decant','Separate the excess impregnation liquid from the solid by decantation.','the impregnation liquid was separated out by decantation','Preparation and characterization of the catalyst',5849,5905);
INSERT INTO "steps" VALUES(5630,4521,5,'dry','Dry the impregnation product.','the impregnation product was dried at 110 °C for 12 h','Preparation and characterization of the catalyst',5916,5969);
INSERT INTO "steps" VALUES(5631,4521,6,'calcine','Calcine the dried product in a muffle oven.','a calcination process in a muffle oven at 600 °C for 4 h','Preparation and characterization of the catalyst',5983,6039);
INSERT INTO "steps" VALUES(5632,4521,7,'sieve','Sieve the calcined catalyst and store it in a drying vessel until the HTL experiments.','The calcinated catalyst was sieved at 80-mesh sieve and stored in a drying vessel before HTL experiments.','Preparation and characterization of the catalyst',6041,6146);
INSERT INTO "steps" VALUES(5633,4526,1,'add','Introduit d''abord le 2,7-dihydroxylnaphthalène dans un autoclave en Téflon et acier inoxydable de 100 mL (ajouts successifs : précurseur, EDA, H2O2, éthanol).','2,7-dihydroxylnaphthalene (0.4 g), EDA (0, 2, 4 or 8 mL), H2O2 (2 mL), and anhydrous ethanol (40 mL) were added into a 100 mL Teflon stainless steel autoclave in turn','2.2. Synthesis of Green Carbon Quantum Dots (g-CQDs)',5412,5578);
INSERT INTO "steps" VALUES(5634,4526,2,'add','Ajoute l''éthylènediamine au précurseur ; les auteurs n''observent pas de réaction évidente à ce stade.','There was no obvious reaction observed after 2,7-dihydroxylnaphthalene and EDA was added.','3.1. Influence of Reaction Conditions on PY and QY',9897,9986);
INSERT INTO "steps" VALUES(5635,4526,3,'add','Ajoute le H2O2 : réaction violente avec dégagement de chaleur et formation de bulles. Les auteurs ne disent pas si l''autoclave est alors ouvert ou fermé, ni à quelle vitesse H2O2 est ajouté.','With the introduction of H2O2 into the solution, a violent reaction occurred and a large amount of heat was released while bubbling.','3.1. Influence of Reaction Conditions on PY and QY',9987,10119);
INSERT INTO "steps" VALUES(5636,4526,4,'add','Ajoute l''éthanol anhydre ; selon la section 3.1, la solution devient alors rouge vin foncé (voir le doute sur le moment du changement de couleur).','The solution turned dark wine red when anhydrous ethanol was added.','3.1. Influence of Reaction Conditions on PY and QY',10120,10187);
INSERT INTO "steps" VALUES(5637,4526,5,'heat','Traitement solvothermal de l''autoclave fermé à la température et pendant la durée optimales.','which was heated to the temperatures of 160, 180, or 200 °C, respectively, for a period of time (10, 12, or 14 h)','2.2. Synthesis of Green Carbon Quantum Dots (g-CQDs)',5580,5693);
INSERT INTO "steps" VALUES(5638,4526,6,'cool','Refroidissement de l''autoclave après réaction ; la solution passe d''incolore à rouge vin foncé.','After the reaction, it was cooled to the room temperature, and the colour of the solution appeared from colourless to dark wine red.','2.2. Synthesis of Green Carbon Quantum Dots (g-CQDs)',5695,5827);
INSERT INTO "steps" VALUES(5639,4526,7,'evaporate','Évaporation rotative, citée uniquement dans la méthode de mesure du PY (section 2.6) ; l''ordre par rapport à la centrifugation est repris du texte de 2.6 (évaporation puis centrifugation) mais n''apparaît pas dans le protocole 2.2.','The g-CQD solid was obtained after rotary evaporation and centrifugation, and then was weighed on a tray balance.','2.6. Calculation of Product Yield (PY)',9405,9518);
INSERT INTO "steps" VALUES(5640,4526,8,'centrifuge','Centrifugation avec de l''acétate d''éthyle, répétée trois fois.','It was then centrifuged with ethyl acetate for 5 min at the rotation speed of 8000 rpm, and repeated three times.','2.2. Synthesis of Green Carbon Quantum Dots (g-CQDs)',5828,5941);
INSERT INTO "steps" VALUES(5641,4526,9,'dry','Séchage en étuve pour obtenir la poudre de g-CQDs.','Finally, it was dried at 50 °C for 6 h in an oven to obtain g-CQDs powder for later characterisation.','2.2. Synthesis of Green Carbon Quantum Dots (g-CQDs)',5942,6043);
INSERT INTO "steps" VALUES(5642,4534,1,'fix','Fixe la puce LED bleue au fond de la base de la LED.','its emission wavelength centre is 460 nm, which is fixed at the bottom of the LED base.','2.3. Preparation of White Light Emitting Diodes (White LEDs)',6473,6560);
INSERT INTO "steps" VALUES(5643,4534,2,'connect','Raccorde l''alimentation externe à la LED par deux fils.','Two threads on the LED were used to connect the external power supply.','2.3. Preparation of White Light Emitting Diodes (White LEDs)',6561,6631);
INSERT INTO "steps" VALUES(5644,4534,3,'deposit','Dépose doucement la solution de g-CQDs sur la paroi interne de la lentille optique.','Then, the g-CQD solution was gently dropped onto the inner wall of the optical lens','2.3. Preparation of White Light Emitting Diodes (White LEDs)',6632,6715);
INSERT INTO "steps" VALUES(5645,4534,4,'dry','Séchage de la lentille revêtue en étuve.','which was then dried in the oven at 80 °C for three hours','2.3. Preparation of White Light Emitting Diodes (White LEDs)',6717,6774);
INSERT INTO "steps" VALUES(5646,4534,5,'assemble','Fixe fermement la lentille optique sur le dessus de la puce LED pour obtenir la LED blanche.','Finally, the optical lens was firmly fixed on the top of the LED chip to realize the fabrication of white LEDs.','2.3. Preparation of White Light Emitting Diodes (White LEDs)',6776,6887);
INSERT INTO "steps" VALUES(5647,4535,1,'dissolve','Dissolve Cs2CO3 in ODE and OA in a three-neck flask by heating under vacuum, which also dries the solution.','Cs2CO3 (0.815 g), ODE (40 mL) and OA (2 mL) were loaded in a 100 ml three-neck flask, dried at 120 °C under vacuum for 2 h to dissolve the cesium salt and to dry the solution.','Preparation of Cesium oleate',31996,32171);
INSERT INTO "steps" VALUES(5648,4535,2,'cool','Cool the cesium oleate solution, store it in a bottle and draw it into glass syringe P1.','The solution was then cooled, stored in bottle and collected with glass syringe P1 through PTFE tube.','Preparation of Cesium oleate',32172,32273);
INSERT INTO "steps" VALUES(5649,4535,3,'dry','Dry PbBr2 powder in ODE under vacuum.','PbBr2 (0.089 g) powder were added in a 20-mL flask together with dried ODE (5 mL). The mixture was then dried under vacuum for 2 h at 120 °C.','Preparation of lead precursors',32308,32449);
INSERT INTO "steps" VALUES(5650,4535,4,'add','Add dried OA and dried OLA under argon until PbBr2 is fully dissolved.','After 2 h, 1 mL of dried OA and dried OLA were added under argon until all PbBr2 dissolved completely.','Preparation of lead precursors',32450,32552);
INSERT INTO "steps" VALUES(5651,4535,5,'cool','Cool the lead precursor solution, store it in a bottle and draw it into glass syringe P2.','The solution was then cooled, stored in bottle and collected with glass syringe P2 through PTFE tube.','Preparation of lead precursors',32553,32654);
INSERT INTO "steps" VALUES(5652,4535,6,'mix','Inject Cs precursor (P1), Pb precursor (P2) and ODE (P3) with syringe pumps into a PEEK cross-junction. The concentration C of Cs+ is set by the pump injection rates; P1/P2 is fixed (lead-rich); the sum of the three flow rates is kept constant so the reaction time is the same in all loops.','OEM (Original Equipment Manufacturer) syringe pumps (MSP1-C2, Longer, China) were used to inject the dispersed phase (Cs precursors, Pb precursor, and ODE) toward a polyether ether ketone (PEEK) cross-junction to mix and into the heating region.','Robotic and microfluidic platform',31280,31525);
INSERT INTO "steps" VALUES(5653,4535,7,'heat','The mixed precursor solution flows through PTFE tubing coiled around the heated copper pipe; temperature T set by the optimization algorithm. The reaction time is not given.','The mixed precursor solution flows through PTFE tubing','Robotic and microfluidic platform',31728,31782);
INSERT INTO "steps" VALUES(5654,4535,8,'centrifuge','Purification and TEM sample (paragraph title in the article): mix with ethyl acetate (1:1 ratio, basis not stated) and centrifuge. Not shown to be part of the synthesis itself.','The purification and TEM sample: Mix with ethyl acetate with 1:1 ratio and centrifuge at 8000 rmp for 4 min.','Crystalline characterization',34729,34837);
INSERT INTO "steps" VALUES(5655,4535,9,'dissolve','Redisperse the deposit in n-hexane (TEM sample preparation, same paragraph).','Take the deposit sample and dissolved in 5-ml n-hexane.','Crystalline characterization',34838,34893);
INSERT INTO "steps" VALUES(5656,4535,10,'centrifuge','Second centrifugation of the hexane dispersion (TEM sample preparation, same paragraph).','Centrifuge for 2 min at 4000 rpm.','Crystalline characterization',34894,34927);
INSERT INTO "steps" VALUES(5657,4535,11,'deposit','Deposit the solution on an ultrathin carbon grid and let the solvent evaporate naturally (TEM sample preparation only).','Deposit the solution on ultrathin carbon grid for natural volatilization.','Crystalline characterization',34928,35001);
INSERT INTO "steps" VALUES(5658,4538,1,'irradiate','Irradiate the nanocrystal solution with a femtosecond pulse laser (800 nm, 1000 Hz, 150 fs pulse width) for 300 s.','We applied a femtosecond pulse laser (800 nm, 1000 Hz, 150 fs pulse width) to introduce thermal vibration in IPNCs','Inversion of CD signal',16366,16480);
INSERT INTO "steps" VALUES(5659,4539,1,'irradiate','Irradiate the nanocrystal solution with a femtosecond pulse laser (800 nm, 1000 Hz, 150 fs pulse width); the irradiation time for this sample is not given.','We applied a femtosecond pulse laser (800 nm, 1000 Hz, 150 fs pulse width) to introduce thermal vibration in IPNCs','Inversion of CD signal',16366,16480);
INSERT INTO "steps" VALUES(5660,4540,1,'irradiate','Irradiate the nanocrystal solutions with a 300 nm femtosecond laser, a treatment described only as similar to the 800 nm one.','Similar treatment under a 300 nm wavelength femtosecond laser was also applied to both samples.','Inversion of CD signal',17955,18050);
INSERT INTO "steps" VALUES(5661,4541,1,'dissolve','Dissolve the nickel nitrate, manganese nitrate and citric acid in distilled water.','5 mmol of Ni(NO3)2·6H2O, 10 mmol of Mn(NO3)2·4H2O, and 50 mmol of citric acid were dissolved into 20 mL of distilled water','Synthesis of NixMn3‐xO4 Solid Solution',25481,25603);
INSERT INTO "steps" VALUES(5662,4541,2,'adjust_ph','Add NH3·H2O dropwise to the solution kept in an ice-water bath until pH 8.','the NH3·H2O was added dropwise into the above solution that was placed in an ice‐water bath until the pH reached 8','Synthesis of NixMn3‐xO4 Solid Solution',25619,25733);
INSERT INTO "steps" VALUES(5663,4541,3,'heat','Thermal treatment of the mixture to obtain a dry gel.','Then, the above mixture was thermally treated at 60 °C for 12 h to get a dry gel.','Synthesis of NixMn3‐xO4 Solid Solution',25735,25816);
INSERT INTO "steps" VALUES(5664,4541,4,'calcine','Calcine the dry gel in a muffle furnace.','Finally, the dry gel was transferred to the muffle furnace and heated at 800 °C for 4 h with a heating rate of 5 °C·min–1.','Synthesis of NixMn3‐xO4 Solid Solution',25817,25939);
INSERT INTO "steps" VALUES(5665,4543,1,'mix','Disperse Ni1.6Mn1.4O4 in ethanol by ultrasonic treatment.','Typically, 0.5 g of Ni1.6Mn1.4O4 was added into 10 mL ethanol solution with ultrasonic treatment for 5 min to obtain a well‐dispersed mixture.','Synthesis of Ir1/Ni1.6Mn1.4O4 Nanocrystals',26082,26224);
INSERT INTO "steps" VALUES(5666,4543,2,'add','Add the IrCl3 solution dropwise to the dispersion under magnetic stirring.','Then, 114.6 µL IrCl3 solution (50 mg mL–1) was added into the above dispersion dropwise under magnetic stirring and heated at 50 °C to completely volatilize the ethanol.','Synthesis of Ir1/Ni1.6Mn1.4O4 Nanocrystals',26225,26394);
INSERT INTO "steps" VALUES(5667,4543,3,'heat','Heat the mixture to completely volatilize the ethanol.','Then, 114.6 µL IrCl3 solution (50 mg mL–1) was added into the above dispersion dropwise under magnetic stirring and heated at 50 °C to completely volatilize the ethanol.','Synthesis of Ir1/Ni1.6Mn1.4O4 Nanocrystals',26225,26394);
INSERT INTO "steps" VALUES(5668,4543,4,'anneal','Thermal treatment of the black powder in a ceramic boat under argon.','The obtained black powder was then transferred into a ceramic boat and thermal‐treated at 400 °C for 2 h under an Ar atmosphere.','Synthesis of Ir1/Ni1.6Mn1.4O4 Nanocrystals',26395,26523);
INSERT INTO "steps" VALUES(5669,4543,5,'cool','Cool naturally to room temperature and collect the powder.','After cooling down to room temperature naturally, the powders were collected and denoted as Ir1/Ni1.6Mn1.4O4.','Synthesis of Ir1/Ni1.6Mn1.4O4 Nanocrystals',26524,26633);
INSERT INTO "steps" VALUES(5670,4544,1,'add','Place the catalyst and the acetylene black in a mortar.','Typically, 80 mg of catalyst and 10 mg of acetylene black were placed in a mortar.','Preparation of Ir1/Ni1.6Mn1.4O4 and Pt–C Electrodes',26689,26771);
INSERT INTO "steps" VALUES(5671,4544,2,'add','Add the Nafion solution and the N-methylpyrrolidone dropwise.','Subsequently, 50 µL of 5 wt.% Nafion and 25 µL of N‐methylpyrrolidone were added dropwise.','Preparation of Ir1/Ni1.6Mn1.4O4 and Pt–C Electrodes',26772,26862);
INSERT INTO "steps" VALUES(5672,4544,3,'grind','Grind the mixture to obtain a uniform ink.','Then, a uniform ink was obtained after grinding for 30 min.','Preparation of Ir1/Ni1.6Mn1.4O4 and Pt–C Electrodes',26863,26922);
INSERT INTO "steps" VALUES(5673,4544,4,'deposit','Spread the suspension on the Ti net.','The above suspension was spread on the Ti net and dried at 60 °C.','Preparation of Ir1/Ni1.6Mn1.4O4 and Pt–C Electrodes',26923,26988);
INSERT INTO "steps" VALUES(5674,4544,5,'dry','Dry the coated Ti net at 60 °C.','The above suspension was spread on the Ti net and dried at 60 °C.','Preparation of Ir1/Ni1.6Mn1.4O4 and Pt–C Electrodes',26923,26988);
INSERT INTO "steps" VALUES(5675,4545,1,'dissolve','Disperse ZnCl2 in methanol and stir vigorously until completely dissolved.','Firstly, 10 mmol ZnCl2 was dispersed in 100 mL methanol and kept stirring vigorously for 30 min until it was dissolved absolutely.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6613,6743);
INSERT INTO "steps" VALUES(5676,4545,2,'add','Add dropwise the methanol solution of 2-methylimidazole to the ZnCl2 solution.','Then, 100 mL methanol, containing 80 mmol 2-methylimidazole, was added dropwise into the above solution','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6744,6847);
INSERT INTO "steps" VALUES(5677,4545,3,'stir','Stir intensively to form a homogeneous milky suspension.','intensively stirred for 30 min to form a homogeneous milky suspension.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6852,6922);
INSERT INTO "steps" VALUES(5678,4545,4,'add','Inject slowly the methanol solution containing water and AgNO3 into the milky suspension.','Then, 40 mL of methanol, containing 3 mL of H2O and X mmol of AgNO3 (X is 5, 10, 15 and 20, respectively), was injected slowly into the above milky solution','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6923,7079);
INSERT INTO "steps" VALUES(5679,4545,5,'stir','Keep stirring for 24 h in the dark.','kept stirring for 24 h under dark conditions.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7084,7129);
INSERT INTO "steps" VALUES(5680,4545,6,'centrifuge','Centrifuge the suspension to collect the AgCl(x)@ZIF-8 composites.','After that, it was centrifuged and washed with ethanol and distilled water to obtain the AgCl(x)@ZIF-8 composites.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7130,7244);
INSERT INTO "steps" VALUES(5681,4545,7,'wash','Wash the solid with ethanol and distilled water to obtain the AgCl(x)@ZIF-8 composites.','After that, it was centrifuged and washed with ethanol and distilled water to obtain the AgCl(x)@ZIF-8 composites.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7130,7244);
INSERT INTO "steps" VALUES(5682,4545,8,'react','Photoreduction: disperse the AgCl(x)@ZIF-8 composites in distilled water and stir vigorously under UV light from a mercury lamp to reduce part of the AgCl to Ag0.','Finally, 1 g of the AgCl(x)@ZIF-8 composites was dispersed in 100 mL of distilled water and kept stirring vigorously for 30 min under UV light (λ ≤ 400 nm, from a 500 W mercury lamp) to prepare Ag/AgCl(x)@ZIF-8 hybrid photocatalysts.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7245,7478);
INSERT INTO "steps" VALUES(5683,4545,9,'centrifuge','Centrifuge the irradiated suspension to collect Ag/AgCl@ZIF-8.','Ag/AgCl@ZIF-8 was centrifuged and dried in air at 60 °C.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7479,7535);
INSERT INTO "steps" VALUES(5684,4545,10,'dry','Dry the product in air at 60 °C.','Ag/AgCl@ZIF-8 was centrifuged and dried in air at 60 °C.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7479,7535);
INSERT INTO "steps" VALUES(5685,4549,1,'react','préparation non décrite par l''article','Fig. 1b is the XRD pattern of the as-synthesized ZIF-8.','Results and discussion',10238,10293);
INSERT INTO "steps" VALUES(5686,4550,1,'react','préparation non décrite par l''article','Fig. 1a is the XRD pattern of the as-synthesized Ag/AgCl.','Results and discussion',9699,9756);
INSERT INTO "steps" VALUES(5687,4551,1,'add','Ajout de la solution H2SO4/H3PO4 (9 : 1) au mélange de graphite et de KMnO4.','a solution of H2SO4 and H3PO4 (9 : 1) was added to a mixture of graphite flakes (2 g) and KMnO4 (15 g)','Synthesis of GO',10691,10793);
INSERT INTO "steps" VALUES(5688,4551,2,'react','Oxydation du graphite sous agitation à 50 °C.','The temperature of the mixture was fixed at 50 °C and stirred for 12 h.','Synthesis of GO',10795,10866);
INSERT INTO "steps" VALUES(5689,4551,3,'cool','Refroidissement du mélange à 0 °C.','Afterward, the mixture was cooled to 0 °C','Synthesis of GO',10867,10908);
INSERT INTO "steps" VALUES(5690,4551,4,'add','Ajout d''eau puis de H2O2.','followed by the addition of water (200 mL) and H2O2 (3 mL)','Synthesis of GO',10909,10967);
INSERT INTO "steps" VALUES(5691,4551,5,'centrifuge','Séparation du produit par centrifugation.','Finally, the product was centrifuged and washed with HCl (5%) and distilled water several times.','Synthesis of GO',10969,11065);
INSERT INTO "steps" VALUES(5692,4551,6,'wash','Lavage à l''HCl (5 %) puis à l''eau distillée.','washed with HCl (5%) and distilled water several times','Synthesis of GO',11010,11064);
INSERT INTO "steps" VALUES(5693,4552,1,'mix','Dispersion de GO aux ultrasons dans un excès de chlorure de thionyle.','GO (0.2 g) was dispersed ultrasonically for 2 h in an excess amount of thionyl chloride (SOCl2, 100 mL)','Synthesis of melamine functionalized GO (AGO)',11122,11225);
INSERT INTO "steps" VALUES(5694,4552,2,'heat','Chauffage pour transformer les groupes carboxyle de GO en chlorure d''acyle.','followed by heating at 80 °C for 24 h to transform the carboxyl functional group of GO to acyl chloride','Synthesis of melamine functionalized GO (AGO)',11226,11329);
INSERT INTO "steps" VALUES(5695,4552,3,'centrifuge','Séparation du chlorure d''acyle de GO par centrifugation.','The product was separated via centrifugation at 7000 rpm, dried at 50 °C, washed with ethanol, and then dried again at 60 °C.','Synthesis of melamine functionalized GO (AGO)',11331,11456);
INSERT INTO "steps" VALUES(5696,4552,4,'dry','Premier séchage à 50 °C.','The product was separated via centrifugation at 7000 rpm, dried at 50 °C, washed with ethanol, and then dried again at 60 °C.','Synthesis of melamine functionalized GO (AGO)',11331,11456);
INSERT INTO "steps" VALUES(5697,4552,5,'wash','Lavage à l''éthanol.','The product was separated via centrifugation at 7000 rpm, dried at 50 °C, washed with ethanol, and then dried again at 60 °C.','Synthesis of melamine functionalized GO (AGO)',11331,11456);
INSERT INTO "steps" VALUES(5698,4552,6,'dry','Second séchage à 60 °C.','The product was separated via centrifugation at 7000 rpm, dried at 50 °C, washed with ethanol, and then dried again at 60 °C.','Synthesis of melamine functionalized GO (AGO)',11331,11456);
INSERT INTO "steps" VALUES(5699,4552,7,'dissolve','Dissolution de la mélamine dans le DMSO sous agitation magnétique.','melamine (0.5 g) was added into 30 mL DMSO and magnetically stirred to obtain a colorless and homogeneous solution','Synthesis of melamine functionalized GO (AGO)',11465,11579);
INSERT INTO "steps" VALUES(5700,4552,8,'mix','Dispersion de la poudre de GO chlorée dans la solution de mélamine aux ultrasons.','Acyl chloride GO powder was dispersed in the melamine solution under ultra-sonication for 1 h','Synthesis of melamine functionalized GO (AGO)',11581,11674);
INSERT INTO "steps" VALUES(5701,4552,9,'heat','Chauffage du mélange pour greffer la mélamine.','dispersed in the melamine solution under ultra-sonication for 1 h followed by heating at 80 °C for 24 h','Synthesis of melamine functionalized GO (AGO)',11609,11712);
INSERT INTO "steps" VALUES(5702,4552,10,'centrifuge','Séparation de la poudre fonctionnalisée par centrifugation.','Finally, the melamine-functionalized GO powder was separated through centrifugation, dried at 100 °C, and washed with ethanol.','Synthesis of melamine functionalized GO (AGO)',11714,11840);
INSERT INTO "steps" VALUES(5703,4552,11,'dry','Séchage à 100 °C.','Finally, the melamine-functionalized GO powder was separated through centrifugation, dried at 100 °C, and washed with ethanol.','Synthesis of melamine functionalized GO (AGO)',11714,11840);
INSERT INTO "steps" VALUES(5704,4552,12,'wash','Lavage à l''éthanol.','Finally, the melamine-functionalized GO powder was separated through centrifugation, dried at 100 °C, and washed with ethanol.','Synthesis of melamine functionalized GO (AGO)',11714,11840);
INSERT INTO "steps" VALUES(5705,4553,1,'mix','Dispersion de GO dans l''eau déionisée, puis sonication pour obtenir une dispersion aqueuse uniforme.','graphene oxide was dispersed in deionized water followed by sonication for 1 h to obtain a uniform aqueous dispersion of GO (10 mg mL−1)','Synthesis of GO–CTS hydrogels',12127,12263);
INSERT INTO "steps" VALUES(5706,4553,2,'mix','Mélange d''une quantité prédéterminée de dispersion de GO avec 10 mL de solution de chitosane dans un flacon en verre.','A predetermined amount of GO dispersion was mixed with 10 mL of as-prepared CTS solution (50 mg mL−1) in a glass vial','Synthesis of GO–CTS hydrogels',12265,12382);
INSERT INTO "steps" VALUES(5707,4553,3,'add','Ajout immédiat d''acide acétique glacial.','instantly followed by the addition of 0.6 mL of glacial acetic acid','Synthesis of GO–CTS hydrogels',12384,12451);
INSERT INTO "steps" VALUES(5708,4553,4,'mix','Mélange mécanique jusqu''à homogénéité.','The mixture was mechanically mixed for 30 min to ensure that the mixture was completely homogeneous.','Synthesis of GO–CTS hydrogels',12453,12553);
INSERT INTO "steps" VALUES(5709,4553,5,'age','Repos à température ambiante pour achever la gélification.','Then, the mixture was settled down for several days at room temperature in order to allow the gelation process to complete.','Synthesis of GO–CTS hydrogels',12554,12677);
INSERT INTO "steps" VALUES(5710,4553,6,'dry','Séchage de l''hydrogel, non décrit : l''article dit seulement que les hydrogels séchés sont obtenus.','The dried hydrogels were obtained and kept at 0 °C for later use.','Synthesis of GO–CTS hydrogels',12678,12743);
INSERT INTO "steps" VALUES(5711,4553,7,'collect','Hydrogels séchés obtenus et conservés à 0 °C.','The dried hydrogels were obtained and kept at 0 °C for later use.','Synthesis of GO–CTS hydrogels',12678,12743);
INSERT INTO "steps" VALUES(5712,4558,1,'wash','Immersion des hydrogels dans l''eau déionisée pendant 24 h, avec renouvellement de l''eau toutes les 2 h, pour éliminer l''acide acétique résiduel.','immersed in deionized water before adsorption tests for 24 h with water replacement every 2 h to remove the residual acetic acid','Sorption tests',14005,14133);
INSERT INTO "steps" VALUES(5713,4559,1,'wash','Immersion des hydrogels usagés dans l''eau distillée pendant 24 h, avec renouvellement de l''eau toutes les 2 h.','placing the adsorbents into distilled water for 24 h with water replacement every 2 h','Recyclability',48057,48142);
INSERT INTO "steps" VALUES(5714,4559,2,'collect','Séparation des hydrogels de l''eau de régénération.','Finally, the hydrogels were separated, dried, and utilized for the next cycles of diclofenac removal.','Recyclability',48144,48245);
INSERT INTO "steps" VALUES(5715,4559,3,'dry','Séchage des hydrogels avant le cycle d''adsorption suivant.','Finally, the hydrogels were separated, dried, and utilized for the next cycles of diclofenac removal.','Recyclability',48144,48245);
INSERT INTO "synthesis_routes" VALUES(3951,13,1,NULL,'AgNPs_AloeVera',1,'green synthesis (reduction of silver nitrate by Aloe vera leaf extract)',NULL,NULL,NULL,NULL,1,'["silver_nitrate_mass", "silver_nitrate_purity", "silver_nitrate_supplier", "aloe_vera_species_or_leaf_part", "stirring_speed", "reaction_duration_hours", "yield", "nanoparticle_concentration", "purification_or_washing_of_AgNPs"]',1.0,'Briefly, 10 ml of Aloe vera leaf extract was added into 90 ml of aqueous solution of 1 mM silver nitrate and incubated in the dark overnight at room temperature.','AgNPs synthesis',6025,6186,'material');
