INSERT INTO "synthesis_routes" VALUES(3972,14,16,3957,'AuCu_1to5',0,'aqueous-phase glucose reduction with hexadecylamine capping (one-pot, oil bath)',NULL,NULL,NULL,NULL,0,'[]',0.875,'Other intermediate molar ratios (3:1, 3:2, 11:9, 2:3, 1:2 and 1:5), however, either gave rise to broken pentacle nanocrystals (resembling multipods), dendritic nanocrystals or a mixture of various shapes.','Formation mechanism',16862,17066,'material');
INSERT INTO "synthesis_routes" VALUES(3973,14,17,3957,'pure_Au_precursor',0,'aqueous-phase glucose reduction with hexadecylamine capping (one-pot, oil bath)',NULL,NULL,NULL,NULL,0,'[]',1.0,'Specifically, pure Au and pure Cu precursors led to the formation of sphere-like Au particles and cube-like Cu particles, respectively.','Formation mechanism',16726,16861,'material');
