INSERT INTO "synthesis_routes" VALUES(3978,14,344,NULL,'PEGylated_70nm',0,'surface coating of the finished 70-nm pentacle nanocrystals with polyethylene glycol (procedure not described)',NULL,NULL,NULL,NULL,1,'[]',0.125,'The surface of pentacle nanocrystals was coated with a monolayer of polyethylene glycol (PEG), which allows a long circulation time of pentacle nanocrystals in the blood stream and accumulation in the tumour.','Plasmonic properties and photothermal therapy (PTT)',24655,24863,'post_treatment');
