INSERT INTO "synthesis_routes" VALUES(3982,63,326,NULL,'Electrode_Sb2S3',0,'slurry mixing of active material, acetylene black and CMC binder in water',NULL,NULL,NULL,NULL,NULL,'[]',0.625,'The work electrode was prepared by mixing the carboxymethyl cellulose Na salt (CMC), acetylene black, and active material in the mass ratio of 1:1:3, after which the viscosity was varied with distilled water and magnetic stirring overnight.','Electrochemical Measurements',5959,6199,'device');
INSERT INTO "synthesis_routes" VALUES(3983,63,327,NULL,'LIB_cell_Sb2S3',0,'assembly of a test cell in an argon-filled glove box',NULL,NULL,NULL,NULL,NULL,'[]',0.25,'For LIBs, the testing batteries were assembled with the working electrode already prepared, and with Celgard 2300 film as the separator, lithium metal as the reference/counter electrode, and 1 M LiPF6 in dimethyl carbonate (DMC)/ethylene carbonate (EC) (1:1 v/v) as the electrolyte.','Electrochemical Measurements',6261,6543,'device');
INSERT INTO "synthesis_routes" VALUES(3984,63,328,3983,'NIB_cell_Sb2S3',0,'assembly of a test cell in an argon-filled glove box',NULL,NULL,NULL,NULL,NULL,'[]',0.25,'However, NIBs were assembled with glass fiber film (Whatman GF/D) as the separator, metal sodium as the reference/counter electrode, and 1 M NaClO4 in ethylene carbonate (EC)/propylene carbonate (PC) (1:1 v/v) as the electrolyte.','Electrochemical Measurements',6544,6773,'device');
