INSERT INTO "synthesis_routes" VALUES(4054,123,67,4053,'Ni11',0,NULL,NULL,10.3,'%','Ni11 | Na2S2O3 ∙ 5H2O | 1:2 | - | 60 | 70 | Ni3S4, (NiS) | 7 (Ni3S4) | 10.3 (Ni3S4)',1,'[]',0.75,'By changing the n(Ni): n(S) ratio to 1:2, nanosized cubic Ni3S4 (PDF No. 00-047-1739) with traces of rhomboedral β-NiS (PDF No. 00-003-0760) was obtained, as shown in Fig. 6 (sample Ni11).','Nickel sulfides',18676,18864,'material');
INSERT INTO "synthesis_routes" VALUES(4055,123,68,NULL,'Co1',1,'sonochemical synthesis in water (70% amplitude, 1 h) of an amorphous precursor, then heating at 500 °C to crystallize',NULL,32.1,'%','Co1 | C2H5NS | 1:1 | - | 60 | 70 | CoS1.097 | 26 | 32.1',1,'["centrifugation_duration", "drying_temperature", "sonication_temperature", "furnace_or_tga_used_for_the_2_h_heating", "water_purity"]',0.875,'The same general procedure was used for the sonochemical preparation of cobalt sulfides: we dissolved 2.13 g (= 0.01 mol) of Co(CH3COO)2 ∙ 2H2O and 0.75 g (= 0.01 mol) of C2H5NS in 50 mL of water and sonicated the solution for 1 h at 70% amplitude.','Experimental',8231,8479,'material');
INSERT INTO "synthesis_routes" VALUES(4056,123,69,4055,'Co1_400C',0,'sonochemical synthesis in water (70% amplitude, 1 h) of an amorphous precursor, then heating at 500 °C to crystallize',NULL,NULL,NULL,NULL,0,'[]',0.75,'Heating at 400 °C still produced amorphous products, while nanocrystalline products were obtained by heating the precursors obtained by the sonochemical reaction for 2 h at 500 °C.','Cobalt sulfides',19277,19457,'material');
INSERT INTO "synthesis_routes" VALUES(4057,123,70,4055,'Co2',0,'sonochemical synthesis in water (70% amplitude, 1 h) of an amorphous precursor, then heating at 500 °C to crystallize',NULL,49.6,'%','Co2 | C2H5NS | 1.2:1 | - | 60 | 70 | Co9S8 | 30 | 49.6',1,'[]',0.875,'On the contrary, cubic Co9S8 (PDF No. 00-019-0364) was obtained when a 20% excess of cobalt was used during the synthesis.','Cobalt sulfides',19810,19932,'material');
INSERT INTO "synthesis_routes" VALUES(4058,123,68,4055,'Co3',0,'sonochemical synthesis in water (70% amplitude, 1 h) of an amorphous precursor, then heating at 500 °C to crystallize',NULL,33.3,'%','Co3 | C2H5NS | 1:2 | - | 60 | 70 | CoS1.097 | 22 | 33.3',1,'[]',0.875,'Hexagonal CoS1.097 (PDF No. 00-019-0366) was prepared from an equimolar mixture as well as from mixtures where a molar ratio n(Co): n(S) = 1: 2 was used.','Cobalt sulfides',19656,19809,'material');
