INSERT INTO "synthesis_routes" VALUES(4300,18,211,NULL,'ZIF-8-Ins',1,'soft-templating synthesis in a surfactant-stabilized oil-in-water microemulsion (n-hexane/HFS), ultrasonication then low-temperature synthesis at 30 °C',NULL,NULL,NULL,NULL,1,'["yield", "centrifugation_duration", "number_of_washes", "methanol_volume", "drying_duration_numeric", "reaction_vessel", "volume_of_stock_solution_used_in_ratio"]',0.75,'Herein, we report a facile, one-pot, highly controlled soft-templating synthesis strategy for hollow ZIF-8 nanospheres with reduced synthesis time, energy consumption and overall chemical usage, ensuring the environmental friendliness of the synthesis procedure.','Introduction',7163,7425,'material');
INSERT INTO "synthesis_routes" VALUES(4301,18,212,4300,'ZIF-8-Out',0,'soft-templating synthesis in a surfactant-stabilized oil-in-water microemulsion (n-hexane/HFS), ultrasonication then low-temperature synthesis at 30 °C',NULL,NULL,NULL,NULL,1,'[]',0.75,'Depending on whether the step was performed without or with sonication, the corresponding samples were named as ZIF-8-Out (Figure 3d) and ZIF-8-Ins (Figure 3e), respectively.','Surfactant (HFS)-Stabilized Oil-in-Water Emulsion (S-O/W) as Hollow ZIF-8 Growth Template: Effect of the Amount of Oil Content',27673,27847,'material');
INSERT INTO "synthesis_routes" VALUES(4302,18,213,4300,'ZIF-8-Ins_0.5h',0,'soft-templating synthesis in a surfactant-stabilized oil-in-water microemulsion (n-hexane/HFS), ultrasonication then low-temperature synthesis at 30 °C',NULL,NULL,NULL,NULL,NULL,'[]',0.75,'The sample synthesized for 0.5 h produced the largest-sized hollow spheres with an average diameter of ∼0.50 μm and exhibited the highest degree of standard deviation (∼0.30).','Synthesis Time',41815,41990,'material');
INSERT INTO "synthesis_routes" VALUES(4303,18,214,4300,'ZIF-8-Ins_1h',0,'soft-templating synthesis in a surfactant-stabilized oil-in-water microemulsion (n-hexane/HFS), ultrasonication then low-temperature synthesis at 30 °C',NULL,NULL,NULL,NULL,NULL,'[]',0.75,'the synthesis time was varied in a wide range, for example, 0.5, 1, 1.5, 2, 6, 14, and 24 h for ZIF-8-Ins (x h) preparation with x denoting the synthesis time (0–24 h)','Synthesis Time',41256,41423,'material');
