INSERT INTO "synthesis_routes" VALUES(4364,116,455,NULL,'WLED_WCDs',0,'drop-casting of a WCDs/PVP ethanol solution into an LED lamp cup, then mounting on a 380 nm LED chip',NULL,NULL,NULL,NULL,1,'["drying_time", "drive_current", "chip_manufacturer"]',0.625,'Specifically, WCDs/PVP mixed solution (40 µL) was dropped into the LED lamp cup, and after natural drying, continued to drop and dry until 120 µL WCDs/PVP complex solution was dropped into the LED lamp cup.','Fabrication of WLEDs and Multicolor LEDs',29649,29855,'device');
INSERT INTO "synthesis_routes" VALUES(4365,116,456,4364,'WLED_remixed',0,'drop-casting of a WCDs/PVP ethanol solution into an LED lamp cup, then mounting on a 380 nm LED chip',NULL,NULL,NULL,NULL,1,'[]',0.625,'The WCDs/PVP complex solution was prepared from isolated multicolor CDs as follows: BCDs (0.30 mg), GCDs (0.50 mg), YCDs (0.20 mg), and RCDs (0.30 mg) were mixed in PVP ethanol solution (0.25 g mL−1, 120 µL) under ultrasonic treatment for 5 min to obtain WCDs/PVP complex solution.','Preparation of CDs/PVP Complex Solution',29041,29322,'device');
INSERT INTO "synthesis_routes" VALUES(4366,116,457,4364,'LED_BCDs',0,'drop-casting of a WCDs/PVP ethanol solution into an LED lamp cup, then mounting on a 380 nm LED chip',NULL,NULL,NULL,NULL,1,'[]',0.625,'The fabrication method of multicolor LEDs is the same as that of WLEDs.','Fabrication of WLEDs and Multicolor LEDs',29960,30031,'device');
