INSERT INTO "synthesis_routes" VALUES(4370,56,254,NULL,'QD_EtOAc',1,'room temperature, open atmosphere anti-solvent precipitation in ethyl acetate with oleylamine and oleic acid as capping ligands',NULL,NULL,NULL,NULL,1,'["stirring_speed", "reaction_temperature_value", "wash_volume", "number_of_washes", "yield"]',0.875,'When ethyl acetate is used as the anti-solvent, 2.6 ± 0.9 nm sized quasi-cubic CsPbBr3 QDs are formed immediately on addition of the precursor solution.','Quantum Dots',4630,4782,'material');
INSERT INTO "synthesis_routes" VALUES(4371,56,255,4370,'NPL_EtOAc_10min',0,'room temperature, open atmosphere anti-solvent precipitation in ethyl acetate with oleylamine and oleic acid as capping ligands',NULL,NULL,NULL,NULL,1,'[]',0.875,'Allowing the reaction up to 10 minutes, a few unit cell thick, square shaped CsPbBr3 NPLs of 60 nm edge length are obtained.','Nanoplates',5478,5602,'material');
